(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("ovid-heroides-b",[{"sp":"HDR","t":"I","st":"1"},{"sp":"N","t":"Haec tua Penelope lento tibi mittit, Ulixe<br>     nil mihi rescribas attinet: ipse veni!<br>Troia iacet certe, Danais invisa puellis;<br>     vix Priamus tanti totaque Troia fuit.<br>o utinam tum, cum Lacedaemona classe petebat,   5<br>     obrutus insanis esset adulter aquis!<br>non ego deserto iacuissem frigida lecto,<br>     nec quererer tardos ire relicta dies;<br>nec mihi quaerenti spatiosam fallere noctem<br>     lassaret viduas pendula tela manus.   10<br>Quando ego non timui graviora pericula veris?<br>     res est solliciti plena timoris amor.<br>in te fingebam violentos Troas ituros;<br>     nomine in Hectoreo pallida semper eram.<br>sive quis Antilochum narrabat ab hoste revictum,   15<br>     Antilochus nostri causa timoris erat;<br>sive Menoetiaden falsis cecidisse sub armis,<br>     flebam successu posse carere dolos.<br>sanguine Tlepolemus Lyciam tepefecerat hastam;<br>     Tlepolemi leto cura novata mea est.   20<br>denique, quisquis erat castris iugulatus Achivis,<br>     frigidius glacie pectus amantis erat.<br>Sed bene consuluit casto deus aequus amori.<br>     versa est in cineres sospite Troia viro.<br>Argolici rediere duces, altaria fumant;   25<br>     ponitur ad patrios barbara praeda deos.<br>grata ferunt nymphae pro salvis dona maritis;<br>     illi victa suis Troica fata canunt.<br>mirantur iustique senes trepidaeque puellae;<br>     narrantis coniunx pendet ab ore viri.   30<br>atque aliquis posita monstrat fera proelia mensa,<br>     pingit et exiguo Pergama tota mero:<br>‘hac ibat Simois; haec est Sigeia tellus;<br>     hic steterat Priami regia celsa senis.<br>illic Aeacides, illic tendebat Ulixes;   35<br>     hic lacer admissos terruit Hector equos.’<br>Omnia namque tuo senior te quaerere misso<br>     rettulerat nato Nestor, at ille mihi.<br>rettulit et ferro Rhesumque Dolonaque caesos,<br>     utque sit hic somno proditus, ille dolo.   40<br>ausus es — o nimium nimiumque oblite tuorum! — <br>     Thracia nocturno tangere castra dolo<br>totque simul mactare viros, adiutus ab uno!<br>     at bene cautus eras et memor ante mei!<br>usque metu micuere sinus, dum victor amicum   45<br>     dictus es Ismariis isse per agmen equis.<br>Sed mihi quid prodest vestris disiecta lacertis<br>     Ilios et, murus quod fuit, esse solum,<br>si maneo, qualis Troia durante manebam,<br>     virque mihi dempto fine carendus abest?   50<br>diruta sunt aliis, uni mihi Pergama restant,<br>     incola captivo quae bove victor arat.<br>iam seges est, ubi Troia fuit, resecandaque falce<br>     luxuriat Phrygio sanguine pinguis humus;<br>semisepulta virum curvis feriuntur aratris   55<br>     ossa, ruinosas occulit herba domos.<br>victor abes, nec scire mihi, quae causa morandi,<br>     aut in quo lateas ferreus orbe, licet!<br>Quisquis ad haec vertit peregrinam litora puppim,<br>     ille mihi de te multa rogatus abit,   60<br>quamque tibi reddat, si te modo viderit usquam,<br>     traditur huic digitis charta notata meis.<br>nos Pylon, antiqui Neleia Nestoris arva,<br>     misimus; incerta est fama remissa Pylo.<br>misimus et Sparten; Sparte quoque nescia veri.   65<br>     quas habitas terras, aut ubi lentus abes?<br>utilius starent etiamnunc moenia Phoebi — <br>     irascor votis, heu, levis ipsa meis!<br>scirem ubi pugnares, et tantum bella timerem,<br>     et mea cum multis iuncta querela foret.    70<br>quid timeam, ignoro — timeo tamen omnia demens,<br>     et patet in curas area lata meas.<br>quaecumque aequor habet, quaecumque pericula tellus,<br>     tam longae causas suspicor esse morae.<br>haec ego dum stulte metuo, quae vestra libido est,   75<br>     esse peregrino captus amore potes.<br>forsitan et narres, quam sit tibi rustica coniunx,<br>     quae tantum lanas non sinat esse rudes.<br>fallar, et hoc crimen tenues vanescat in auras,<br>     neve, revertendi liber, abesse velis!   80<br>Me pater Icarius viduo discedere lecto<br>     cogit et immensas increpat usque moras.<br>increpet usque licet — tua sum, tua dicar oportet;<br>     Penelope coniunx semper Ulixis ero.<br>ille tamen pietate mea precibusque pudicis   85<br>     frangitur et vires temperat ipse suas.<br>Dulichii Samiique et quos tulit alta Zacynthos,<br>     turba ruunt in me luxuriosa proci,<br>inque tua regnant nullis prohibentibus aula;<br>     viscera nostra, tuae dilacerantur opes.   90","st":"1"},{"sp":"N","t":"quid tibi Pisandrum Polybumque Medontaque dirum<br>     Eurymachique avidas Antinoique manus<br>atque alios referam, quos omnis turpiter absens<br>     ipse tuo partis sanguine rebus alis?<br>Irus egens pecorisque Melanthius actor edendi   95<br>     ultimus accedunt in tua damna pudor.<br>Tres sumus inbelles numero, sine viribus uxor<br>     Laertesque senex Telemachusque puer.<br>ille per insidias paene est mihi nuper ademptus,<br>     dum parat invitis omnibus ire Pylon.   100<br>di, precor, hoc iubeant, ut euntibus ordine fatis<br>     ille meos oculos conprimat, ille tuos!<br>hac faciunt custosque boum longaevaque nutrix,<br>     Tertius inmundae cura fidelis harae;<br>sed neque Laertes, ut qui sit inutilis armis,   105<br>     hostibus in mediis regna tenere potest — <br>Telemacho veniet, vivat modo, fortior aetas;<br>     nunc erat auxiliis illa tuenda patris — <br>nec mihi sunt vires inimicos pellere tectis.<br>     tu citius venias, portus et ara tuis!   110<br>est tibi sitque, precor, natus, qui mollibus annis<br>     in patrias artes erudiendus erat.<br>respice Laerten; ut tu sua lumina condas,<br>     extremum fati sustinet ille diem.<br>Certe ego, quae fueram te discedente puella,   115<br>     protinus ut venias, facta videbor anus.","st":"1"},{"sp":"HDR","t":"II","st":"2"},{"sp":"N","t":"Hospita, Demophoon, tua te Rhodopeia Phyllis<br>     ultra promissum tempus abesse queror.<br>cornua cum lunae pleno semel orbe coissent,<br>     litoribus nostris ancora pacta tua est — <br>luna quater latuit, toto quater orbe recrevit;   5<br>     nec vehit Actaeas Sithonis unda rates.<br>tempora si numeres — bene quae numeramus amantes — <br>     non venit ante suam nostra querela diem.<br>Spes quoque lenta fuit; tarde, quae credita laedunt,<br>     credimus. invita nunc es amante nocens.   10<br>saepe fui mendax pro te mihi, saepe putavi<br>     alba procellosos vela referre Notos.<br>Thesea devovi, quia te dimittere nollet;<br>     nec tenuit cursus forsitan ille tuos.<br>interdum timui, ne, dum vada tendis ad Hebri,   15<br>     mersa foret cana naufraga puppis aqua.<br>saepe deos supplex, ut tu, scelerate, valeres,<br>     cum prece turicremis sum venerata sacris;<br>saepe, videns ventos caelo pelagoque faventes,<br>     ipsa mihi dixi: ‘si valet ille, venit.’   20<br>denique fidus amor, quidquid properantibus obstat,<br>     finxit, et ad causas ingeniosa fui.<br>at tu lentus abes; nec te iurata reducunt<br>     numina, nec nostro motus amore redis.<br>Demophoon, ventis et verba et vela dedisti;   25<br>     vela queror reditu, verba carere fide.<br>Dic mihi, quid feci, nisi non sapienter amavi?<br>     crimine te potui demeruisse meo.<br>unum in me scelus est, quod te, scelerate, recepi;<br>     sed scelus hoc meriti pondus et instar habet.   30<br>iura fidesque ubi nunc, commissaque dextera dextrae,<br>     quique erat in falso plurimus ore deus?<br>promissus socios ubi nunc Hymenaeus in annos,<br>     qui mihi coniugii sponsor et obses erat?<br>per mare, quod totum ventis agitatur et undis,   35<br>     per quod nempe ieras, per quod iturus eras,<br>perque tuum mihi iurasti — nisi fictus et ille est — <br>     concita qui ventis aequora mulcet, avum,<br>per Venerem nimiumque mihi facientia tela — <br>     altera tela arcus, altera tela faces — 40<br>Iunonemque, toris quae praesidet alma maritis,<br>     et per taediferae mystica sacra deae.<br>si de tot laesis sua numina quisque deorum<br>     vindicet, in poenas non satis unus eris.<br>Ah, laceras etiam puppes furiosa refeci — 45<br>     ut, qua desererer, firma carina foret! — <br>remigiumque dedi, quod me fugiturus haberes.<br>     heu! patior telis vulnera facta meis!<br>credidimus blandis, quorum tibi copia, verbis;<br>     credidimus generi nominibusque tuis;    50<br>credidimus lacrimis — an et hae simulare docentur?<br>     hae quoque habent artes, quaque iubentur, eunt?<br>dis quoque credidimus. quo iam tot pignora nobis?<br>     parte satis potui qualibet inde capi.<br>Nec moveor, quod te iuvi portuque locoque — 55<br>     debuit haec meriti summa fuisse mei!<br>turpiter hospitium lecto cumulasse iugali<br>     paenitet, et lateri conseruisse latus.<br>quae fuit ante illam, mallem suprema fuisset<br>     nox mihi, dum potui Phyllis honesta mori.   60<br>speravi melius, quia me meruisse putavi;<br>     quaecumque ex merito spes venit, aequa venit.<br>Fallere credentem non est operosa puellam<br>     gloria. simplicitas digna favore fuit.<br>sum decepta tuis et amans et femina verbis.   65<br>     di faciant, laudis summa sit ista tuae!<br>inter et Aegidas, media statuaris in urbe,<br>     magnificus titulis stet pater ante suis.<br>cum fuerit Sciron lectus torvusque Procrustes<br>     et Sinis et tauri mixtaque forma viri   70<br>et domitae bello Thebae fusique bimembres<br>     et pulsata nigri regia caeca dei — <br>hoc tua post illos titulo signetur imago:<br>     hic est, cuius amans hospita capta dolo est.<br>de tanta rerum turba factisque parentis   75<br>     sedit in ingenio Cressa relicta tuo.<br>quod solum excusat, solum miraris in illo;<br>     heredem patriae, perfide, fraudis agis.<br>illa — nec invideo — fruitur meliore marito<br>     inque capistratis tigribus alta sedet;   80<br>at mea despecti fugiunt conubia Thraces,<br>     quod ferar externum praeposuisse meis.<br>atque aliquis ‘iam nunc doctas eat,’ inquit, ‘Athenas;<br>     armiferam Thracen qui regat, alter erit.<br>exitus acta probat.’ careat successibus, opto,   85<br>     quisquis ab eventu facta notanda putat!<br>at si nostra tuo spumescant aequora remo,<br>     iam mihi, iam dicar consuluisse meis — <br>sed neque consului, nec te mea regia tanget","st":"2"},{"sp":"N","t":"fessaque Bistonia membra lavabis aqua!   90<br>Illa meis oculis species abeuntis inhaeret,<br>     cum premeret portus classis itura meos.<br>ausus es amplecti colloque infusus amantis<br>     oscula per longas iungere pressa moras<br>cumque tuis lacrimis lacrimas confundere nostras,   95<br>     quodque foret velis aura secunda, queri<br>et mihi discedens suprema dicere voce:<br>     ‘Phylli, fac expectes Demophoonta tuum!’<br>Expectem, qui me numquam visurus abisti?<br>     expectem pelago vela negata meo?    100<br>et tamen expecto — redeas modo serus amanti,<br>     ut tua sit solo tempore lapsa fides!<br>Quid precor infelix? te iam tenet altera coniunx<br>     forsitan et, nobis qui male favit, amor;<br>iamque tibi excidimus, nullam, puto, Phyllida nosti.   105<br>     ei mihi! si, quae sim Phyllis et unde, rogas — <br>quae tibi, Demophoon, longis erroribus acto<br>     Threicios portus hospitiumque dedi,<br>cuius opes auxere meae, cui dives egenti<br>     munera multa dedi, multa datura fui;   110<br>quae tibi subieci latissima regna Lycurgi,<br>     nomine femineo vix satis apta regi,<br>qua patet umbrosum Rhodope glacialis ad Haemum,<br>     et sacer admissas exigit Hebrus aquas,<br>cui mea virginitas avibus libata sinistris   115<br>     castaque fallaci zona recincta manu!<br>pronuba Tisiphone thalamis ululavit in illis,<br>     et cecinit maestum devia carmen avis;<br>adfuit Allecto brevibus torquata colubris,<br>     suntque sepulcrali lumina mota face!   120<br>Maesta tamen scopulos fruticosaque litora calco<br>     quaeque patent oculis litora lata meis.<br>sive die laxatur humus, seu frigida lucent<br>     sidera, prospicio, quis freta ventus agat;<br>et quaecumque procul venientia lintea vidi,   125<br>     protinus illa meos auguror esse deos.<br>in freta procurro, vix me retinentibus undis,<br>     mobile qua primas porrigit aequor aquas.<br>quo magis accedunt, minus et minus utilis adsto;<br>     linquor et ancillis excipienda cado.   130<br>Est sinus, adductos modice falcatus in arcus;<br>     ultima praerupta cornua mole rigent.<br>hinc mihi suppositas inmittere corpus in undas<br>     mens fuit; et, quoniam fallere pergis, erit.<br>ad tua me fluctus proiectam litora portent,   135<br>     occurramque oculis intumulata tuis!<br>duritia ferrum ut superes adamantaque teque,<br>     ‘non tibi sic,’ dices, ‘Phylli, sequendus eram!’<br>saepe venenorum sitis est mihi; saepe cruenta<br>     traiectam gladio morte perire iuvat.   140<br>colla quoque, infidis quia se nectenda lacertis<br>     praebuerunt, laqueis inplicuisse iuvat.<br>stat nece matura tenerum pensare pudorem.<br>     in necis electu parva futura mora est.<br>Inscribere meo causa invidiosa sepulcro.   145<br>     aut hoc aut simili carmine notus eris:<br>phyllida demophoon leto dedit hospes amantem;<br>     ille necis causam praebuit, ipsa manum.","st":"2"},{"sp":"HDR","t":"III","st":"3"},{"sp":"N","t":"Quam legis, a rapta Briseide littera venit,<br>     vix bene barbarica Graeca notata manu.<br>quascumque adspicies, lacrimae fecere lituras;<br>     sed tamen et lacrimae pondera vocis habent.<br>Si mihi pauca queri de te dominoque viroque   5<br>     fas est, de domino pauca viroque querar.<br>non, ego poscenti quod sum cito tradita regi,<br>     culpa tua est — quamvis haec quoque culpa tua est;<br>nam simul Eurybates me Talthybiusque vocarunt,<br>     Eurybati data sum Talthybioque comes.   10<br>alter in alterius iactantes lumina vultum<br>     quaerebant taciti, noster ubi esset amor.<br>differri potui; poenae mora grata fuisset.<br>     ei mihi! discedens oscula nulla dedi;<br>at lacrimas sine fine dedi rupique capillos — 15<br>     infelix iterum sum mihi visa capi!<br>Saepe ego decepto volui custode reverti,<br>     sed, me qui timidam prenderet, hostis erat.<br>si progressa forem, caperer ne, nocte, timebam,<br>     quamlibet ad Priami munus itura nurum.   20<br>Sed data sim, quia danda fui — tot noctibus absum<br>     nec repetor; cessas, iraque lenta tua est.<br>ipse Menoetiades tum, cum tradebar, in aurem<br>     ‘quid fles? hic parvo tempore,’ dixit, ‘eris.’<br>Nec repetisse parum; pugnas ne reddar, Achille!   25<br>     i nunc et cupidi nomen amantis habe!<br>venerunt ad te Telamone et Amyntore nati — <br>     ille gradu propior sanguinis, ille comes — <br>Laertaque satus, per quos comitata redirem<br>     (auxerunt blandas grandia dona preces)   30<br>viginti fulvos operoso ex aere lebetas,<br>     et tripodas septem pondere et arte pares;<br>addita sunt illis auri bis quinque talenta,<br>     bis sex adsueti vincere semper equi,<br>quodque supervacuum est, forma praestante puellae   35<br>     Lesbides, eversa corpora capta domo,<br>cumque tot his — sed non opus est tibi coniuge — coniunx<br>     ex Agamemnoniis una puella tribus.<br>si tibi ab Atride pretio redimenda fuissem,<br>     quae dare debueras, accipere illa negas!   40<br>qua merui culpa fieri tibi vilis, Achille?<br>     quo levis a nobis tam cito fugit amor?<br>An miseros tristis fortuna tenaciter urget,<br>     nec venit inceptis mollior hora malis?<br>diruta Marte tuo Lyrnesia moenia vidi — 45<br>     et fueram patriae pars ego magna meae;<br>vidi consortes pariter generisque necisque<br>     tres cecidisse, quibus, quae mihi, mater erat;<br>vidi, quantus erat, fusum tellure cruenta<br>     pectora iactantem sanguinolenta virum.    50<br>tot tamen amissis te conpensavimus unum;<br>     tu dominus, tu vir, tu mihi frater eras.<br>tu mihi, iuratus per numina matris aquosae,<br>     utile dicebas ipse fuisse capi — <br>scilicet ut, quamvis veniam dotata, repellas   55<br>     et mecum fugias quae tibi dantur opes!<br>quin etiam fama est, cum crastina fulserit Eos,<br>     te dare nubiferis lintea velle Notis.<br>Quod scelus ut pavidas miserae mihi contigit aures,<br>     sanguinis atque animi pectus inane fuit.   60<br>ibis et — o miseram! — cui me, violente, relinquis?<br>     quis mihi desertae mite levamen erit?<br>devorer ante, precor, subito telluris hiatu<br>     aut rutilo missi fulminis igne cremer,<br>quam sine me Pthiis canescant aequora remis,   65<br>     et videam puppes ire relicta tuas!<br>si tibi iam reditusque placent patriique Penates,<br>     non ego sum classi sarcina magna tuae.<br>victorem captiva sequar, non nupta maritum;<br>     est mihi, quae lanas molliat, apta manus.   70<br>inter Achaeiadas longe pulcherrima matres<br>     in thalamos coniunx ibit eatque tuos,<br>digna nurus socero, Iovis Aeginaeque nepote,<br>     cuique senex Nereus prosocer esse velit.<br>nos humiles famulaeque tuae data pensa trahemus,   75<br>     et minuent plenas stamina nostra colos.<br>exagitet ne me tantum tua, deprecor, uxor — <br>     quae mihi nescio quo non erit aequa modo — <br>neve meos coram scindi patiare capillos<br>     et leviter dicas: ‘haec quoque nostra fuit.’   80<br>vel patiare licet, dum ne contempta relinquar — <br>     hic mihi vae! miserae concutit ossa metus.<br>Quid tamen expectas? Agamemnona paenitet irae,<br>     et iacet ante tuos Graecia maesta pedes.<br>vince animos iramque tuam, qui cetera vincis!   85<br>     quid lacerat Danaas inpiger Hector opes?<br>arma cape, Aeacide, sed me tamen ante recepta,<br>     et preme turbatos Marte favente viros!<br>propter me mota est, propter me desinat ira,","st":"3"},{"sp":"N","t":"simque ego tristitiae causa modusque tuae.   90<br>nec tibi turpe puta precibus succumbere nostris;<br>     coniugis Oenides versus in arma prece est.<br>res audita mihi, nota est tibi. fratribus orba<br>     devovit nati spemque caputque parens.<br>bellum erat; ille ferox positis secessit ab armis   95<br>     et patriae rigida mente negavit opem.<br>sola virum coniunx flexit. felicior illa!<br>     at mea pro nullo pondere verba cadunt.<br>nec tamen indignor nec me pro coniuge gessi<br>     saepius in domini serva vocata torum.   100<br>me quaedam, memini, dominam captiva vocabat.<br>     ‘servitio,’ dixi, ‘nominis addis onus.’<br>Per tamen ossa viri subito male tecta sepulcro,<br>     semper iudiciis ossa verenda meis;<br>perque trium fortes animas, mea numina, fratrum,   105<br>     qui bene pro patria cum patriaque iacent;<br>perque tuum nostrumque caput, quae iunximus una,<br>     perque tuos enses, cognita tela meis — <br>nulla Mycenaeum sociasse cubilia mecum<br>     iuro; fallentem deseruisse velis!   110<br>si tibi nunc dicam, fortissime: ‘tu quoque iura<br>     nulla tibi sine me gaudia capta!’ neges.<br>at Danai maerere putant — tibi plectra moventur,<br>     te tenet in tepido mollis amica sinu!<br>et quisquam quaerit, quare pugnare recuses?   115<br>     pugna nocet, citharae voxque Venusque iuvant.<br>tutius est iacuisse toro, tenuisse puellam,<br>     Threiciam digitis increpuisse lyram,<br>quam manibus clipeos et acutae cuspidis hastam,<br>     et galeam pressa sustinuisse coma.   120<br>Sed tibi pro tutis insignia facta placebant,<br>     partaque bellando gloria dulcis erat.<br>an tantum dum me caperes, fera bella probabas,<br>     cumque mea patria laus tua victa iacet?<br>di melius! validoque, precor, vibrata lacerto   125<br>     transeat Hectoreum Pelias hasta latus!<br>mittite me, Danai! dominum legata rogabo<br>     multaque mandatis oscula mixta feram.<br>plus ego quam Phoenix, plus quam facundus Ulixes,<br>     plus ego quam Teucri, credite, frater agam.    130<br>est aliquid collum solitis tetigisse lacertis,<br>     praesentisque oculos admonuisse sui.<br>sis licet inmitis matrisque ferocior undis,<br>     ut taceam, lacrimis conminuere meis.<br>Nunc quoque — sic omnes Peleus pater inpleat annos,   135<br>     sic eat auspiciis Pyrrhus ad arma tuis! — <br>respice sollicitam Briseida, fortis Achille,<br>     nec miseram lenta ferreus ure mora!<br>aut, si versus amor tuus est in taedia nostri,<br>     quam sine te cogis vivere, coge mori!   140<br>utque facis, coges. abiit corpusque colorque;<br>     sustinet hoc animae spes tamen una tui.<br>qua si destituor, repetam fratresque virumque — <br>     nec tibi magnificum femina iussa mori.<br>cur autem iubeas? stricto pete corpora ferro;   145<br>     est mihi qui fosso pectore sanguis eat.<br>me petat ille tuus, qui, si dea passa fuisset,<br>     ensis in Atridae pectus iturus erat!<br>A, potius serves nostram, tua munera, vitam!<br>     quod dederas hosti victor, amica rogo.   150<br>perdere quos melius possis, Neptunia praebent<br>     Pergama; materiam caedis ab hoste pete.<br>me modo, sive paras inpellere remige classem,<br>     sive manes, domini iure venire iube!","st":"3"},{"sp":"HDR","t":"IV","st":"4"},{"sp":"N","t":"Quam nisi tu dederis, caritura est ipsa, salutem<br>     mittit Amazonio Cressa puella viro.<br>perlege, quodcumque est — quid epistula lecta nocebit?<br>     te quoque in hac aliquid quod iuvet esse potest;<br>his arcana notis terra pelagoque feruntur.   5<br>     inspicit acceptas hostis ab hoste notas.<br>Ter tecum conata loqui ter inutilis haesit<br>     lingua, ter in primo restitit ore sonus.<br>qua licet et sequitur, pudor est miscendus amori;<br>     dicere quae puduit, scribere iussit amor.   10<br>quidquid Amor iussit, non est contemnere tutum;<br>     regnat et in dominos ius habet ille deos.<br>ille mihi primo dubitanti scribere dixit:<br>     ‘scribe! dabit victas ferreus ille manus.’<br>adsit et, ut nostras avido fovet igne medullas,   15<br>     figat sic animos in mea vota tuos!<br>Non ego nequitia socialia foedera rumpam;<br>     fama — velim quaeras — crimine nostra vacat.<br>venit amor gravius, quo serius — urimur intus;<br>     urimur, et caecum pectora vulnus habent.    20<br>scilicet ut teneros laedunt iuga prima iuvencos,<br>     frenaque vix patitur de grege captus equus,<br>sic male vixque subit primos rude pectus amores,<br>     sarcinaque haec animo non sedet apta meo.<br>ars fit, ubi a teneris crimen condiscitur annis;   25<br>     cui venit exacto tempore, peius amat.<br>tu nova servatae capies libamina famae,<br>     et pariter nostrum fiet uterque nocens.<br>est aliquid, plenis pomaria carpere ramis,<br>     et tenui primam delegere ungue rosam.   30<br>si tamen ille prior, quo me sine crimine gessi,<br>     candor ab insolita labe notandus erat,<br>at bene successit, digno quod adurimur igni;<br>     peius adulterio turpis adulter obest.<br>si mihi concedat Iuno fratremque virumque,   35<br>     Hippolytum videor praepositura Iovi!<br>Iam quoque — vix credes — ignotas mittor in artes;<br>     est mihi per saevas impetus ire feras.<br>iam mihi prima dea est arcu praesignis adunco<br>     Delia; iudicium subsequor ipsa tuum.   40<br>in nemus ire libet pressisque in retia cervis<br>     hortari celeris per iuga summa canes,<br>aut tremulum excusso iaculum vibrare lacerto,<br>     aut in graminea ponere corpus humo.<br>saepe iuvat versare leves in pulvere currus   45<br>     torquentem frenis ora fugacis equi;<br>nunc feror, ut Bacchi furiis Eleleides actae,<br>     quaeque sub Idaeo tympana colle movent,<br>aut quas semideae Dryades Faunique bicornes<br>     numine contactas attonuere suo.   50<br>namque mihi referunt, cum se furor ille remisit,<br>     omnia; me tacitam conscius urit amor.<br>Forsitan hunc generis fato reddamus amorem,<br>     et Venus ex tota gente tributa petat.<br>Iuppiter Europen — prima est ea gentis origo — 55<br>     dilexit, tauro dissimulante deum.<br>Pasiphae mater, decepto subdita tauro,<br>     enixa est utero crimen onusque suo.<br>perfidus Aegides, ducentia fila secutus,<br>     curva meae fugit tecta sororis ope.   60<br>en, ego nunc, ne forte parum Minoia credar,<br>     in socias leges ultima gentis eo!<br>hoc quoque fatale est: placuit domus una duabus;<br>     me tua forma capit, capta parente soror.<br>Thesides Theseusque duas rapuere sorores — 65<br>     ponite de nostra bina tropaea domo!<br>Tempore quo nobis inita est Cerealis Eleusin,<br>     Gnosia me vellem detinuisset humus!<br>tunc mihi praecipue (nec non tamen ante placebas)<br>     acer in extremis ossibus haesit amor.   70<br>candida vestis erat, praecincti flore capilli,<br>     flava verecundus tinxerat ora rubor,<br>quemque vocant aliae vultum rigidumque trucemque,<br>     pro rigido Phaedra iudice fortis erat.<br>sint procul a nobis iuvenes ut femina compti! — 75<br>     fine coli modico forma virilis amat.<br>te tuus iste rigor positique sine arte capilli<br>     et levis egregio pulvis in ore decet.<br>sive ferocis equi luctantia colla recurvas,<br>     exiguo flexos miror in orbe pedes;   80<br>seu lentum valido torques hastile lacerto,<br>     ora ferox in se versa lacertus habet,<br>sive tenes lato venabula cornea ferro.<br>     denique nostra iuvat lumina, quidquid agis.<br>Tu modo duritiam silvis depone iugosis;   85<br>     non sum militia digna perire tua.<br>quid iuvat incinctae studia exercere Dianae,<br>     et Veneri numeros eripuisse suos?<br>quod caret alterna requie, durabile non est;<br>     haec reparat vires fessaque membra novat.   90","st":"4"},{"sp":"N","t":"arcus — et arma tuae tibi sunt imitanda Dianae — <br>     si numquam cesses tendere, mollis erit.<br>clarus erat silvis Cephalus, multaeque per herbas<br>     conciderant illo percutiente ferae;<br>nec tamen Aurorae male se praebebat amandum.   95<br>     ibat ad hunc sapiens a sene diva viro.<br>saepe sub ilicibus Venerem Cinyraque creatum<br>     sustinuit positos quaelibet herba duos.<br>arsit et Oenides in Maenalia Atalanta;<br>     illa ferae spolium pignus amoris habet.   100<br>nos quoque quam primum turba numeremur in ista!<br>     si Venerem tollas, rustica silva tua est.<br>ipsa comes veniam, nec me latebrosa movebunt<br>     saxa neque obliquo dente timendus aper.<br>Aequora bina suis obpugnant fluctibus isthmon,   105<br>     et tenuis tellus audit utrumque mare.<br>hic tecum Troezena colam, Pittheia regna;<br>     iam nunc est patria carior illa mea.<br>tempore abest aberitque diu Neptunius heros;<br>     illum Pirithoi detinet ora sui.   110<br>praeposuit Theseus — nisi si manifesta negamus — <br>     Pirithoum Phaedrae Pirithoumque tibi.<br>sola nec haec ad nos iniuria venit ab illo;<br>     in magnis laesi rebus uterque sumus.<br>ossa mei fratris clava perfracta trinodi   115<br>     sparsit humi; soror est praeda relicta feris.<br>prima securigeras inter virtute puellas<br>     te peperit, nati digna vigore parens;<br>si quaeras, ubi sit — Theseus latus ense peregit,<br>     nec tanto mater pignore tuta fuit.   120<br>at ne nupta quidem taedaque accepta iugali — <br>     cur, nisi ne caperes regna paterna nothus?<br>addidit et fratres ex me tibi, quos tamen omnis<br>     non ego tollendi causa, sed ille fuit.<br>o utinam nocitura tibi, pulcherrime rerum,   125<br>     in medio nisu viscera rupta forent!<br>i nunc, sic meriti lectum reverere parentis — <br>     quem fugit et factis abdicat ipse suis!<br>Nec, quia privigno videar coitura noverca,<br>     terruerint animos nomina vana tuos.    130<br>ista vetus pietas, aevo moritura futuro,<br>     rustica Saturno regna tenente fuit.<br>Iuppiter esse pium statuit, quodcumque iuvaret,<br>     et fas omne facit fratre marita soror.<br>illa coit firma generis iunctura catena,   135<br>     inposuit nodos cui Venus ipsa suos.<br>nec labor est celare, licet peccemus, amorem.<br>     cognato poterit nomine culpa tegi.<br>viderit amplexos aliquis, laudabimur ambo;<br>     dicar privigno fida noverca meo.   140<br>non tibi per tenebras duri reseranda mariti<br>     ianua, non custos decipiendus erit;<br>ut tenuit domus una duos, domus una tenebit;<br>     oscula aperta dabas, oscula aperta dabis;<br>tutus eris mecum laudemque merebere culpa,   145<br>     tu licet in lecto conspiciare meo.<br>tolle moras tantum properataque foedera iunge — <br>     qui mihi nunc saevit, sic tibi parcat Amor!<br>non ego dedignor supplex humilisque precari.<br>     heu! ubi nunc fastus altaque verba iacent?   150<br>et pugnare diu nec me submittere culpae<br>     certa fui — certi siquid haberet amor;<br>victa precor genibusque tuis regalia tendo<br>     bracchia! quid deceat, non videt ullus amans.<br>depudui, profugusque pudor sua signa reliquit.   155<br>     Da veniam fassae duraque corda doma!<br>quod mihi sit genitor, qui possidet aequora, Minos,<br>     quod veniant proavi fulmina torta manu,<br>quod sit avus radiis frontem vallatus acutis,<br>     purpureo tepidum qui movet axe diem — 160<br>nobilitas sub amore iacet! miserere priorum<br>     et, mihi si non vis parcere, parce meis!<br>est mihi dotalis tellus Iovis insula, Crete — <br>     serviat Hippolyto regia tota meo!<br>Flecte, ferox, animos! potuit corrumpere taurum   165<br>     mater; eris tauro saevior ipse truci?<br>per Venerem, parcas, oro, quae plurima mecum est!<br>     sic numquam, quae te spernere possit, ames;<br>sic tibi secretis agilis dea saltibus adsit,<br>     silvaque perdendas praebeat alta feras;   170<br>sic faveant Satyri montanaque numina Panes,<br>     et cadat adversa cuspide fossus aper;<br>sic tibi dent Nymphae, quamvis odisse puellas<br>     diceris, arentem quae levet unda sitim!<br>Addimus his precibus lacrimas quoque; verba precantis   175<br>     qui legis, et lacrimas finge videre meas!","st":"4"},{"sp":"HDR","t":"V","st":"5"},{"sp":"N","t":"Nympha suo Paridi, quamvis suus esse recuset,<br>mittit ab Idaeis verba legenda iugis.","st":"5"},{"sp":"N","t":"Perlegis? an coniunx prohibet nova? perlege! non est <br>     ista Mycenaea littera facta manu.<br>Pedasis Oenone, Phrygiis celeberrima silvis, <br>     laesa queror de te, si sinis, ipse meo. <br>Quis deus opposuit nostris sua numina votis? <br>     ne tua permaneam, quod mihi crimen obest? <br>leniter, e merito quicquid patiare, ferendum est; <br>     quae venit indignae poena dolenda venit. <br>Nondum tantus eras, cum te contenta marito <br>     edita de magno flumine nympha fui. <br>qui nunc Priamides (absit reverentia vero)<br>     servus eras; servo nubere nympha tuli! <br>saepe greges inter requievimus arbore tecti<br>     mixtaque cum foliis praebuit herba torum.<br>saepe super stramen fenoque iacentibus alto <br>     defensa est humili cana pruina casa. <br>quis tibi monstrabat saltus venatibus aptos<br>     et tegeret catulos qua fera rupe suos? <br>retia saepe comes maculis distincta tetendi,<br>     saepe citos egi per iuga longa canes.<br>incisae servant a te mea nomina fagi<br>     et legor Oenone falce notata tua;<br>et quantum trunci, tantum mea nomina crescunt;<br>     crescite et in titulos surgite recta meos!","st":"5"},{"sp":"N","t":"[Populus est, memini, fluviali consita rivo,<br>     est in qua nostri littera scripta memor.]<br>popule, vive, precor, quae consita margine ripae <br>     hoc in rugoso cortice carmen habes: <br>“cum Paris Oenone poterit spirare relicta,<br>     ad fontem Xanthi versa recurret aqua.”<br>Xanthe, retro propera versaeque recurrite lymphae! <br>     sustinet Oenonen deseruisse Paris. <br>Illa dies fatum miserae mihi dixit, ab illa <br>     pessima mutati coepit amoris hiems, <br>qua Venus et Iuno sumptisque decentior armis <br>     venit in arbitrium nuda Minerva tuum. <br>attoniti micuere sinus gelidusque cucurrit, <br>     ut mihi narrasti, dura per ossa tremor. <br>consului (neque enim modice terrebar) anusque <br>     longaevosque senes: constitit esse nefas. <br>Caesa abies sectaeque trabes et classe parata <br>     caerula ceratas accipit unda rates. <br>flesti discedens. hoc saltim parce negare;<br>     praeterito magis est iste pudendus amor.<br>et flesti et nostros vidisti flentis ocellos;<br>     miscuimus lacrimas maestus uterque suas. <br>non sic appositis vincitur vitibus ulmus, <br>     ut tua sunt collo bracchia nexa meo. <br>ah quotiens, cum te vento quererere teneri, <br>     riserunt comites — ille secundus erat.<br>oscula dimissae quotiens repetita dedisti! <br>     quam vix sustinuit dicere lingua “vale!”<br>Aura levis rigido pendentia lintea malo <br>     suscitat et remis eruta canet aqua. <br>prosequor infelix oculis abeuntia vela, <br>     qua licet, et lacrimis umet arena meis, <br>utque celer venias, virides Nereidas oro — <br>     scilicet ut venias in mea damna celer.<br>votis ergo meis, alii rediture, redisti? <br>     ei mihi, pro dira paelice blanda fui! <br>Adspicit immensum moles nativa profundum<br>     (mons fuit), aequoreis illa resistit aquis;<br>hinc ego vela tuae cognovi prima carinae<br>     et mihi per fluctus impetus ire fuit. <br>dum moror, in summa fulsit mihi purpura prora.<br>     pertimui: cultus non erat ille tuus. <br>fit propior terrasque cita ratis attigit aura:<br>     femineas vidi corde tremente genas. <br>non satis id fuerat — quid enim furiosa morabar? — <br>     haerebat gremio turpis amica tuo! <br>tunc vero rupique sinus et pectora planxi     <br>     et secui madidas ungue rigente genas<br>implevique sacram querulis ululatibus Iden <br>     illuc has lacrimas in mea saxa tuli. <br>sic Helene doleat defectaque coniuge ploret, <br>     quaeque prior nobis intulit, ipsa ferat! <br>Nunc tibi conveniunt, quae te per aperta sequantur <br>     aequora legitimos destituantque viros.<br>at cum pauper eras armentaque pastor agebas, <br>     nulla nisi Oenone pauperis uxor erat. <br>non ego miror opes, nec me tua regia tangit <br>     nec de tot Priami dicar ut una nurus,<br>non tamen ut Priamus nymphae socer esse recuset<br>     aut Hecubae fuerim dissimulanda nurus. <br>dignaque sum et cupio fieri matrona potentis; <br>     sunt mihi quas possint sceptra decere manus. <br>nec me, faginea quod tecum fronde iacebam, <br>     despice; purpureo sum magis apta toro. <br>Denique tutus amor meus est; ibi nulla parantur <br>     bella nec ultrices advehit unda rates. <br>Tyndaris infestis fugitiva reposcitur armis; <br>     hac venit in thalamos dote superba tuos. <br>quae si sit Danais reddenda, vel Hectora fratrem, <br>     vel cum Deiphobo Polydamanta roga; <br>quid gravis Antenor, Priamus quid suadeat ipse, <br>     consule, quis aetas longa magistra fuit.<br>turpe rudimentum, patriae praeponere raptam. <br>     causa pudenda tua est; iusta vir arma movet. <br>Nec tibi, si sapias, fidam promitte Lacaenam, <br>     quae sit in amplexus tam cito versa tuos. <br>ut minor Atrides temerati foedera lecti <br>     clamat et externo laesus amore dolet, <br>tu quoque clamabis. nulla reparabilis arte <br>     laesa pudicitia est; deperit illa semel. <br>ardet amore tui; sic et Menelaon amavit;<br>     nunc iacet in viduo credulus ille toro. <br>felix Andromache certo bene nupta marito; <br>     uxor ad exemplum fratris habenda fui.<br>tu levior foliis, tum cum sine pondere suci <br>     mobilibus ventis arida facta volant.<br>et minus est in te quam summa pondus arista, <br>     quae levis adsiduis solibus usta riget. <br>Hoc tua (nam recolo) quondam germana canebat <br>     sic mihi diffusis vaticinata comis: <br>“quid facis, Oenone? quid arenae semina mandas?","st":"5"},{"sp":"N","t":"non profecturis litora bubus aras!<br>Graia iuvenca venit, quae te patriamque domumque <br>     perdat! io prohibe! Graia iuvenca venit! <br>dum licet, obscenam ponto demergite puppim! <br>     heu! quantum Phrygii sanguinis illa vehit!”<br>dixerat; in cursu famulae rapuere furentem, <br>     at mihi flaventes diriguere comae. <br>ah, nimium miserae vates mihi vera fuisti;<br>     possidet en saltus Graia iuvenca meos! <br>sit facie quamvis insignis, adultera certe est; <br>     deseruit socios hospite capta deos. <br>illam de patria Theseus, nisi nomine fallor,<br>     nescioquis Theseus abstulit ante sua. <br>a iuvene, et cupido, credatur reddita virgo? <br>     unde hoc compererim tam bene quaeris? amo!<br>vim licet appelles et culpam nomine veles; <br>     quae totiens rapta est, praebuit ipsa rapi. <br>at manet Oenone fallenti casta marito — <br>     et poteras falli legibus ipse tuis:<br>Me Satyri celeres (silvis ego tecta latebam)<br>     quaesierunt rapido, turba proterva, pede <br>cornigerumque caput pinu praecinctus acuta <br>     Faunus, in immensis qua tumet Ida iugis. <br>me fide conspicuus Troiae munitor amavit;<br>     ille meae spolium virginitatis habet.<br>id quoque luctando; rupi tamen ungue capillos<br>     oraque sunt digitis aspera facta meis.<br>nec pretium stupri gemmas aurumque poposci;<br>     turpiter ingenuum munera corpus emunt.<br>Ipse ratus dignam medicas mihi tradidit artes<br>     admisitque meas ad sua dona manus. <br>quaecumque herba potens ad opem radixque medendi <br>     utilis in toto nascitur orbe, mea est. <br>me miseram, quod amor non est medicabilis herbis! <br>     deficior prudens artis ab arte mea. <br>ipse repertor opis vaccas pavisse Pheraeas<br>     fertur et e nostro saucius igne fuit.<br>Quod nec graminibus tellus fecunda creandis <br>     nec deus, auxilium tu mihi ferre potes. <br>et potes et merui. dignae miserere puellae! <br>     non ego cum Danais arma cruenta fero.<br>sed tua sum tecumque fui puerilibus annis <br>     et tua, quod superest temporis, esse precor.","st":"5"},{"sp":"HDR","t":"VI","st":"6"},{"sp":"N","t":"Lemnias Hypsipyle Bacchi genus Aesone nato<br>dicit: et in verbis pars quota mentis erat?","st":"6"},{"sp":"N","t":"Litora Thessaliae reduci tetigisse carina <br>     diceris auratae vellere dives ovis. <br>gratulor incolumi quantum sinis; hoc tamen ipso<br>     debueram scripto certior esse tuo. <br>nam ne pacta tibi praeter mea regna redires, <br>     cum cuperes, ventos non habuisse potes:<br>quamlibet adverso signatur epistula vento,<br>     Hypsipyle missa digna salute fui!<br>Cur mihi fama prior quam littera nuntia venit: <br>     isse sacros Martis sub iuga panda boves, <br>seminibus iactis segetes adolesse virorum <br>     inque necem dextra non eguisse tua, <br>pervigilem spolium pecudis servasse draconem, <br>     rapta tamen forti vellera fulva manu? <br>hoc ego si possem timide credentibus “ista <br>     ipse mihi scripsit” dicere, quanta forem! <br>Quid queror officium lenti cessasse mariti? <br>     obsequium, maneo si tua, grande tuli.<br>barbara narratur venisse venefica tecum<br>     in mihi promissi parte recepta tori. <br>credula res amor est. utinam temeraria dicar <br>     criminibus falsis insimulasse virum! <br>nuper ab Haemoniis hospes mihi Thessalus oris <br>     venerat et tactum vix bene limen erat, <br>“Aesonides,” dixi, “quid agit meus?” ille pudore <br>     haesit in opposita lumina fixus humo. <br>protinus exilui tunicisque a pectore ruptis <br>     “vivit? an,” exclamo, “me quoque fata vocant?” <br>“vivit,” ait timidus; timidum iurare coegi. <br>     vix mihi teste deo credita vita tua est. <br>Utque animus rediit, tua facta requirere coepi:<br>     narrat aeripedes Martis arasse boves, <br>vipereos dentes in humum pro semine iactos<br>     et subito natos arma tulisse viros,<br>terrigenas populos civili Marte peremptos <br>     inplesse aetatis fata diurna suae. <br>devictus serpens. iterum, si vivat Iason, <br>     quaerimus; alternant spesque timorque fidem. <br>Singula dum narrat, studio cursuque loquendi <br>     detegit ingenio vulnera nostra suo. <br>heus, ubi pacta fides? ubi conubialia iura <br>     faxque sub arsuros dignior ire rogos? <br>non ego sum furto tibi cognita. pronuba Iuno <br>     affuit et sertis tempora vinctus Hymen. <br>at mihi nec Iuno nec Hymen, sed tristis Erinys <br>     praetulit infaustas sanguinolenta faces. <br>Quid mihi cum Minyis? quid cum Tritonide pinu? <br>     quid tibi cum patria, navita Tiphy, mea? <br>non erat hic aries villo spectabilis aureo, <br>     nec senis Aeetae regia Lemnos erat. <br>certa fui primo — sed me mala fata trahebant — <br>     hospita feminea pellere castra manu<br>Lemniadesque viros — nimium quoque! — vincere norunt:<br>     milite tam forti vita tuenda fuit! <br>Urbe virum vidi tectoque animoque recepi.<br>     hic tibi bisque aestas bisque cucurrit hiems. <br>tertia messis erat, cum tu dare vela coactus <br>     inplesti lacrimis talia verba tuis: <br>“abstrahor, Hypsipyle. sed dent modo fata recursus;<br>     vir tuus hinc abeo, vir tibi semper ero. <br>quod tamen e nobis gravida celatur in alvo, <br>     vivat et eiusdem simus uterque parens!”<br>Hactenus. et lacrimis in falsa cadentibus ora <br>     cetera te memini non potuisse loqui. <br>Ultimus e sociis sacram conscendis in Argon; <br>     illa volat, ventus concava vela tenet.<br>caerula propulsae subducitur unda carinae:<br>     terra tibi, nobis adspiciuntur aquae. <br>in latus omne patens turris circumspicit undas; <br>     huc feror et lacrimis osque sinusque madent. <br>per lacrimas specto cupidaeque faventia menti <br>     longius adsueto lumina nostra vident. <br>adde preces castas inmixtaque vota timori<br>     nunc quoque te salvo persoluenda mihi!<br>Vota ego persolvam? votis Medea fruetur! <br>     cor dolet atque ira mixtus abundat amor. <br>dona feram templis, vivum quod Iasona perdo? <br>     hostia pro damnis concidat icta meis? <br>Non equidem secura fui semperque verebar, <br>     ne pater Argolica sumeret urbe nurum. <br>Argolidas timui — nocuit mihi barbara paelex! <br>     non expectato vulnus ab hoste tuli. <br>nec facie meritisque placet, sed carmina novit <br>     diraque cantata pabula falce metit. <br>illa reluctantem cursu deducere Lunam <br>     nititur et tenebris abdere Solis equos;<br>illa refrenat aquas obliquaque flumina sistit,<br>     illa loco silvas vivaque saxa movet. <br>per tumulos errat passis discincta capillis <br>     certaque de tepidis colligit ossa rogis. <br>devovet absentis simulacraque cerea figit","st":"6"},{"sp":"N","t":"et miserum tenues in iecur urget acus.<br>et quae nescierim melius: male quaeritur herbis <br>     moribus et forma conciliandus amor. <br>Hanc potes amplecti thalamoque relictus in uno <br>     inpavidus somno nocte silente frui? <br>scilicet ut tauros, ita te iuga ferre coegit:<br>     quaque feros angues, te quoque mulcet ope. <br>adde quod adscribi factis procerumque tuisque <br>     se favet et titulo coniugis uxor obest. <br>atque aliquis Peliae de partibus acta venenis <br>     inputat et populum qui sibi credat habet: <br>non haec Aesonides, sed Phasias Aeetine <br>     aurea Phrixeae terga revellit ovis.<br>non probat Alcimede mater tua — consule matrem! — <br>     non pater, a gelido cui venit axe nurus. <br>illa sibi a Tanai Scythiaeque paludibus udae <br>     quaerat et a patria Phasidis usque virum.<br>Mobilis Aesonide vernaque incertior aura, <br>     cur tua polliciti pondere verba carent? <br>vir meus hinc ieras, vir non meus inde redisti — <br>     sim reducis coniunx, sicut euntis eram.<br>si te nobilitas generosaque nomina tangunt:<br>     en ego Minoo nata Thoante feror.<br>Bacchus avus: Bacchi coniunx redimita corona <br>     praeradiat stellis signa minora suis. <br>dos tibi Lemnos erit, terra ingeniosa colenti; <br>     me quoque dotalis inter habere potes. <br>Nunc etiam peperi. gratare ambobus, Iason — <br>     dulce mihi gravidae fecerat auctor onus. <br>felix in numero quoque sum prolemque gemellam<br>     pignora Lucina bina favente dedi. <br>si quaeris, cui sint similes, cognosceris illis: <br>     fallere non norunt, cetera patris habent; <br>legatos quos paene dedi pro matre ferendos; <br>     sed tenuit coeptas saeva noverca vias. <br>Medeam timui — plus est Medea noverca — <br>     Medeae faciunt ad scelus omne manus. <br>Spargere quae fratris potuit lacerata per agros <br>     corpora, pignoribus parceret illa meis? <br>hanc, tamen o demens Colchisque ablate venenis, <br>     diceris Hypsipyles praeposuisse toro?<br>turpiter illa virum cognovit adultera virgo,<br>     me tibi teque mihi taeda pudica dedit. <br>prodidit illa patrem — rapui de caede Thoanta. <br>     deseruit Colchos — me mea Lemnos habet. <br>Quid refert, scelerata piam si vincit? et ipso <br>     crimine dotata est emeruitque virum.<br>Lemniadum facinus culpo, non miror, Iason!<br>     quamlibet ignavis ipse dat arma dolor. <br>dic age, si ventis ut oportuit actus iniquis <br>     intrasses portus tuque comesque meos<br>obviaque exissem fetu comitante gemello — <br>     hiscere nempe tibi terra roganda fuit! — <br>quo vultu natos, quo me scelerate videres? <br>     perfidiae pretio qua nece dignus eras? <br>ipse quidem per me tutus sospesque fuisses,<br>     non quia tu dignus, sed quia mitis ego. <br>paelicis ipsa meos implessem sanguine vultus, <br>     quosque veneficiis abstulit illa suis.<br>Medeae Medea forem. quod si quid ab alto <br>     iustus adest votis Iuppiter ipse meis, <br>quod gemit Hypsipyle, lecti quoque subnuba nostri <br>     maereat et leges sentiat ipsa suas<br>utque ego destituor coniunx materque duorum, <br>     a totidem natis orba sit aque viro! <br>nec male parta diu teneat peiusque relinquat:<br>     exulet et toto quaerat in orbe fugam.<br>quam fratri germana fuit miseroque parenti <br>     filia tam natis, tam sit acerba viro!<br>cum mare, cum terras consumpserit, aera temptet; <br>     erret inops, exspes, caede cruenta sua.<br>haec ego, coniugio fraudata Thoantias, oro. <br>     vivite devoto nuptaque virque toro!","st":"6"},{"sp":"HDR","t":"VII","st":"7"},{"sp":"N","t":"Accipe, Dardanide, moriturae carmen Elissae;<br>quae legis a nobis ultima verba legi.","st":"7"},{"sp":"N","t":"Sic ubi fata vocant, udis abiectus in herbis <br>     ad vada Maeandri concinit albus olor. <br>Nec quia te nostra sperem prece posse moveri, <br>     alloquor: adverso movimus ista deo!<br>sed meriti famam corpusque animumque pudicum <br>     cum male perdiderim, perdere verba leve est.","st":"7"},{"sp":"N","t":"Certus es ire tamen miseramque relinquere Didon<br>     atque idem venti vela fidemque ferent.<br>certus es, Aenea, cum foedere solvere naves<br>     quaeque ubi sint nescis, Itala regna sequi.<br>nec nova Karthago, nec te crescentia tangunt <br>     moenia nec sceptro tradita summa tuo.<br>facta fugis, facienda petis; quaerenda per orbem <br>     altera, quaesita est altera terra tibi.<br>ut terram invenias, quis eam tibi tradet habendam? <br>     quis sua non notis arva tenenda dabit? <br>alter habendus amor tibi restat et altera Dido<br>     quamque iterum fallas, altera danda fides. <br>quando erit, ut condas instar Karthaginis urbem <br>     et videas populos altus ab arce tuos? <br>omnia ut eveniant, nec di tua vota morentur, <br>     unde tibi, quae te sic amet, uxor erit? <br>Uror ut inducto ceratae sulpure taedae, <br>     ut pia fumosis addita tura rogis.<br>Aeneas oculis vigilantis semper inhaeret;<br>     Aenean animo noxque diesque refert. <br>ille quidem male gratus et ad mea munera surdus<br>     et quo, si non sim stulta, carere velim.<br>non tamen Aenean, quamvis male cogitat, odi, <br>     sed queror infidum questaque peius amo. <br>parce, Venus, nurui, durumque amplectere fratrem, <br>     frater Amor; castris militet ille tuis.<br>aut ego quem coepi — neque enim dedignor — amare,<br>     materiam curae praebeat ille meae.<br>Fallor et ista mihi falso iactatur imago:<br>     matris ab ingenio dissidet ille suae. <br>te lapis et montes innataque rupibus altis <br>     robora, te saevae progenuere ferae<br>aut mare, quale vides agitari nunc quoque ventis:<br>     qua tamen adversis fluctibus ire paras?<br>quo fugis? obstat hiems. hiemis mihi gratia prosit! <br>     adspice ut eversas concitet Eurus aquas.<br>quod tibi malueram, sine me debere procellis; <br>     iustior est animo ventus et unda tuo. <br>Non ego sum tanti, quod non cessaris, inique,<br>     ut pereas, dum me per freta longa fugis. <br>exerces pretiosa odia et constantia magno, <br>     si, dum me careas, est tibi vile mori. <br>iam venti ponent, strataque aequaliter unda <br>     caeruleis Triton per mare curret equis. <br>tu quoque cum ventis utinam mutabilis esses<br>     et, nisi duritia robora vincis, eris. <br>quid, si nescires, insana quid aequora possunt, <br>     expertae totiens tam male credis aquae? <br>ut, pelago suadente etiam, retinacula solvas, <br>     multa tamen latus tristia pontus habet. <br>nec violasse fidem temptantibus aequora prodest; <br>     perfidiae poenas exigit ille locus, <br>praecipue cum laesus amor, quia mater Amorum <br>     nuda Cytheriacis edita fertur aquis. <br>Perdita ne perdam, timeo, noceamve nocenti<br>     neu bibat aequoreas naufragus hostis aquas. <br>vive, precor! sic te melius quam funere perdam,<br>     tu potius leti causa ferere mei.<br>finge, age, te rapido — nullum sit in omine pondus! — <br>     turbine deprendi; quid tibi mentis erit? <br>protinus occurrent falsae periuria linguae<br>     et Phrygia Dido fraude coacta mori; <br>coniugis ante oculos deceptae stabit imago <br>     tristis et effusis sanguinolenta comis. <br>quidquid id est “tantum merui! concedite!” dicas, <br>     quaeque cadent in te fulmina missa putes! <br>Da breve saevitiae spatium pelagique tuaeque; <br>     grande morae pretium tuta futura via est. <br>nec mihi tu curae; puero parcatur Iulo! <br>     te satis est titulum mortis habere meae. <br>quid puer Ascanius, quid di meruere Penates? <br>     ignibus ereptos obruet unda deos? <br>sed neque fers tecum, nec, quae mihi, perfide, iactas, <br>     presserunt umeros sacra paterque tuos. <br>omnia mentiris; neque enim tua fallere lingua <br>     incipit a nobis, primaque plector ego:<br>si quaeras ubi sit formosi mater Iuli — <br>     occidit a duro sola relicta viro! <br>haec mihi narraras, at me movere merentem.<br>     inde minor culpa poena futura mea est. <br>Nec mihi mens dubia est, quin te tua numina damnent:<br>     per mare, per terras septima iactat hiems. <br>fluctibus eiectum tuta statione recepi <br>     vixque bene audito nomine regna dedi. <br>his tamen officiis utinam contenta fuissem<br>     nec mea concubitu fama sepulta foret! <br>illa dies nocuit, qua nos declive sub antrum <br>     caeruleus subitis conpulit imber aquis. <br>audieram vocem; nymphas ululasse putavi:<br>     Eumenides fatis signa dedere meis.","st":"7"},{"sp":"N","t":"Exige, laese pudor, poenas, violataque lecti<br>     iura neque ad cineres fama retenta meos!<br>vosque mei manes animaeque cinisque Sychaei,<br>     ad quas, me miseram, plena pudoris eo. <br>est mihi marmorea sacratus in aede Sychaeus;<br>     oppositae frondes velleraque alba tegunt. <br>hinc ego me sensi noto quater ore citari; <br>     ipse sono tenui dixit “Elissa, veni!”<br>Nulla mora est: venio, venio tibi debita coniunx, — <br>     sum tamen admisso tarda pudore meo!<br>da veniam culpae; decepit idoneus auctor; <br>     invidiam noxae detrahit ille meae. <br>diva parens seniorque pater, pia sarcina nati, <br>     spem mihi mansuri rite dedere viri. <br>si fuit errandum, causas habet error honestas:<br>     adde fidem, nulla parte pigendus erit. <br>Durat in extremum vitaeque novissima nostrae <br>     prosequitur fati, qui fuit ante, tenor:<br>occidit internas coniunx mactatus ad aras<br>     et sceleris tanti praemia frater habet,<br>exul agor cineresque viri patriamque relinquo<br>     et feror in dubias hoste sequente vias;<br>adplicor ignotis fratrique elapsa fretoque;<br>     quod tibi donavi, perfide, litus emo. <br>urbem constitui lateque patentia fixi <br>     moenia finitimis invidiosa locis. <br>bella tument. bellis peregrina et femina temptor<br>     vixque rudis portas urbis et arma paro. <br>mille procis placui, qui me coiere querentes <br>     nescio quem thalamis praeposuisse suis.<br>quid dubitas vinctam Gaetulo tradere Iarbae? <br>     praebuerim sceleri bracchia nostra tuo. <br>est etiam frater, cuius manus impia poscit <br>     respergi nostro sparsa cruore viri. <br>pone deos et quae tangendo sacra profanas! <br>     non bene caelestis impia dextra colit. <br>si tu cultor eras elapsis igne futurus, <br>     paenitet elapsos ignibus esse deos. <br>Forsitan et gravidam Didon, scelerate, relinquas<br>     parsque tui lateat corpore clausa meo. <br>accedet fatis matris miserabilis infans<br>     et nondum nato funeris auctor eris.<br>cumque parente sua frater morietur Iuli, <br>     poenaque conexos auferet una duos. <br>“Sed iubet ire deus.” vellem, vetuisset adire<br>     Punica nec Teucris pressa fuisset humus.<br>hoc duce nempe deo ventis agitaris iniquis <br>     et teris in rapido tempora longa freto? <br>Pergama vix tanto tibi erant repetenda labore, <br>     Hectore si vivo quanta fuere forent. <br>non patrium Simoenta petis, sed Thybridis undas,<br>     nempe ut pervenias quo cupis hospes eris.<br>utque latet vitatque tuis obtrusa carinis, <br>     vix tibi continget terra petita seni. <br>Hos potius populos in dotem ambage remissa<br>     accipe et advectas Pygmalionis opes. <br>Ilion in Tyriam transfer felicius urbem <br>     resque loco regis sceptraque sacra tene! <br>si tibi mens avida est belli, si quaerit Iulus, <br>     unde suo partus Marte triumphus eat, <br>quem superet, nequid desit praebebimus hostem; <br>     hic pacis leges, hic locus arma capit. <br>tu modo — per matrem fraternaque tela, sagittas, <br>     perque fugae comites, Dardana sacra, deos! — <br>sic superent, quoscumque tua de gente reportas<br>     Mars ferus et damni sit modus ille tui<br>Ascaniusque suos feliciter inpleat annos<br>     et senis Anchisae molliter ossa cubent! — <br>parce, precor, domui, quae se tibi tradit habendam! <br>     quod crimen dicis praeter amasse meum? <br>non ego sum Pthias magnisque oriunda Mycenis, <br>     nec steterunt in te virque paterque meus.<br>si pudet uxoris, non nupta, sed hospita dicar; <br>     dum tua sit Dido, quidlibet esse feret. <br>Nota mihi freta sunt Afrum plangentia litus; <br>     temporibus certis dantque negantque viam:<br>cum dabit aura viam, praebebis carbasa ventis; <br>     nunc levis eiectam continet alga ratem. <br>tempus ut observem, manda mihi: certius ibis, <br>     nec te, si cupies, ipsa manere sinam. <br>et socii requiem poscunt, laniataque classis <br>     postulat exiguas semirefecta moras.<br>pro meritis et siqua tibi debebimus ultra, <br>     pro spe coniugii tempora parva peto:<br>dum freta mitescunt et amor, dum temperat usum, <br>     fortiter edisco tristia posse pati. <br>Si minus, est animus nobis effundere vitam; <br>     in me crudelis non potes esse diu. <br>adspicias utinam, quae sit scribentis imago;<br>     scribimus, et gremio Troicus ensis adest;<br>perque genas lacrimae strictum labuntur in ensem,","st":"7"},{"sp":"N","t":"qui iam pro lacrimis sanguine tinctus erit. <br>quam bene conveniunt fato tua munera nostro! <br>     instruis impensa nostra sepulcra brevi. <br>nec mea nunc primum feriuntur pectora telo:<br>     ille locus saevi vulnus amoris habet. <br>Anna soror, soror Anna, meae male conscia culpae, <br>     iam dabis in cineres ultima dona meos.<br>nec consumpta rogis inscribar Elissa Sychaei, <br>     hoc tantum in tumuli marmore carmen erit: <br>praebuit aeneas et causam mortis et ensem.<br>     ipsa sua Dido concidit usa manu.","st":"7"},{"sp":"HDR","t":"VIII","st":"8"},{"sp":"N","t":"Alloquor Hermione nuper fratremque virumque<br>nunc fratrem. nomen coniugis alter habet.","st":"8"},{"sp":"N","t":"Pyrrhus Achillides, animosus imagine patris, <br>     inclusam contra iusque piumque tenet. <br>quod potui renui, ne non invita tenerer,<br>     cetera femineae non valuere manus. <br>“quid facis, Aeacidae? non sum sine vindice!” dixi<br>     “haec tibi sub domino est, Pyrrhe, puella suo!”<br>surdior ille freto clamantem nomen Orestis <br>     traxit inornatis in sua tecta comis.<br>quid gravius capta Lacedaemone serva tulissem, <br>     si raperet Graias barbara turba nurus? <br>parcius Andromachen vexavit Achaia victrix, <br>     cum Danaus Phrygias ureret ignis opes. <br>At tu, cura mei si te pia tangit, Oreste, <br>     inice non timidas in tua iura manus!<br>an si quis rapiat stabulis armenta reclusis, <br>     arma feras, rapta coniuge lentus eris? <br>sit socer exemplo nuptae repetitor ademptae, <br>     cui pia militiae causa puella fuit;<br>si pater ignavus vidua plorasset in aula, <br>     nupta foret Paridi mater, ut ante fuit.<br>Nec tu mille rates sinuosaque vela pararis <br>     nec numeros Danai militis: ipse veni! <br>sic quoque eram repetenda tamen, nec turpe marito <br>     aspera pro caro bella tulisse toro. <br>quid, quod avus nobis idem Pelopeius Atreus, <br>     et si non esses vir mihi, frater eras. <br>vir, precor, uxori, frater succurre sorori;<br>     instant officio nomina bina tuo. <br>Me tibi Tyndareus, vita gravis auctor et annis<br>     tradidit; arbitrium neptis habebat avus.","st":"8"},{"sp":"N","t":"at pater Aeacidae promiserat inscius acti; <br>     plus patre, quo prior est ordine, posset avus. <br>cum tibi nubebam, nulli mea taeda nocebat; <br>     si iungar Pyrrho, tu mihi laesus eris. <br>et pater ignoscet nostro Menelaus amori;<br>     succubuit telis praepetis ipse dei. <br>quem sibi permisit, genero concedet amorem.<br>     proderit exemplo mater amata suo. <br>tu mihi, quod matri pater est. quas egerat olim <br>     Dardanius partes advena, Pyrrhus agit. <br>ille licet patriis sine fine superbiat actis; <br>     et tu quae referas facta parentis habes. <br>Tantalides omnes ipsumque regebat Achillem;<br>     hic pars militiae, dux erat ille ducum. <br>tu quoque habes proavum Pelopem Pelopisque parentem;<br>     si melius numeres, a Iove quintus eris. <br>Nec virtute cares. arma invidiosa tulisti;<br>     sed tu quid faceres? induit illa pater. <br>materia vellem fortis meliore fuisses; <br>     non lecta est operi, sed data causa tuo. <br>hanc tamen implesti; iuguloque Aegisthus aperto <br>     tecta cruentavit, quae pater ante tuus. <br>increpat Aeacides laudemque in crimina vertit;<br>     et tamen aspectus sustinet ille meos. <br>rumpor et ora mihi pariter cum mente tumescunt<br>     pectoraque inclusis ignibus usta dolent. <br>Hermione coram quisquamne obiecit Oresti, <br>     nec mihi sunt vires, nec ferus ensis adest!<br>flere licet certe; flendo diffundimus iram, <br>     perque sinum lacrimae fluminis instar eunt. <br>has semper solas habeo semperque profundo; <br>     ument incultae fonte perenne genae. <br>Num generis fato, quod nostros errat in annos, <br>     Tantalides matres apta rapina sumus?<br>non ego fluminei referam mendacia cygni <br>     nec querar in plumis delituisse Iovem. <br>qua duo porrectus longe freta distinet Isthmos, <br>     vecta peregrinis Hippodamia rotis.<br>Castori Amyclaeo et Amyclaeo Polluci<br>     reddita Moposia Taenaris urbe soror;<br>Taenaris Idaeo trans aequor ab hospite rapta <br>     Argolicas pro se vertit in arma manus. <br>vix equidem memini. memini tamen: omnia luctus, <br>     omnia solliciti plena timoris erant.<br>flebat avus Phoebeque soror fratresque gemelli, <br>     orabat superos Leda suumque Iovem. <br>ipsa ego non longos etiam tunc scissa capillos<br>     clamabam “sine me, me sine, mater abis?”<br>nam coniunx aberat. ne non Pelopeia credar, <br>     ecce Neoptolemo praeda parata fui. <br>Pelides utinam vitasset Apollinis arcus! <br>     damnaret nati facta proterva pater.<br>nec quondam placuit nec nunc placuisset Achilli <br>     abducta viduum coniuge flere virum. <br>quae mea caelestes iniuria fecit iniquos?<br>     quodve mihi miserae sidus obesse querar? <br>parva mea sine matre fui; pater arma ferebat; <br>     et duo cum vivant, orba duobus eram. <br>non tibi blanditias primis, mea mater, in annis <br>     incerto dictas ore puella tuli.<br>non ego captavi brevibus tua colla lacertis,<br>     nec gremio sedi sarcina grata tuo. <br>non cultus tibi cura mei, nec pacta marito <br>     intravi thalamos matre parante novos.<br>obvia prodieram reduci tibi — vera fatebor — <br>     nec facies nobis nota parentis erat! <br>te tamen esse Helenen, quod eras pulcherrima, sensi; <br>     ipsa requirebas quae tua nata foret.<br>Pars haec una mihi, coniunx bene cessit Orestes; <br>     is quoque, ni pro se pugnet, ademptus erit. <br>Pyrrhus habet captam reduce et victore parente;<br>     munus et hoc nobis diruta Troia dedit! <br>cum tamen altus equis Titan radiantibus instant, <br>     perfruor infelix liberiore malo; <br>nox ubi me thalamis ululantem et acerba gementem <br>     condidit in maesto procubuique toro, <br>pro somno lacrimis oculi funguntur obortis<br>     quaque licet fugio sicut ab hoste viro.<br>saepe malis stupeo rerumque oblita locique <br>     ignara tetigi Scyria membra manu;<br>utque nefas sensi, male corpora tacta relinquo <br>     et mihi pollutas credor habere manus. <br>saepe Neoptolemi pro nomine nomen Orestis<br>     exit, et errorem vocis ut omen amo.<br>Per genus infelix iuro generisque parentem, <br>     qui freta, qui terras et sua regna quatit; <br>per patris ossa tui, patrui mihi, quae tibi debent, <br>     quod se sub tumulo fortiter ulta iacent:<br>aut ego praemoriar primoque exstinguar in aevo, <br>     aut ego Tantalidae Tantalis uxor ero!","st":"8"},{"sp":"HDR","t":"IX","st":"9"},{"sp":"N","t":"Mittor ad Alciden a coniuge conscia mentis<br>littera si coniunx Deianira tua est.","st":"9"},{"sp":"N","t":"Gratulor Oechaliam titulis accedere nostris,<br>     victorem victae succubuisse queror. <br>fama Pelasgiadas subito pervenit in urbes <br>     decolor et factis infitianda tuis, <br>quem numquam Iuno seriesque inmensa laborum <br>     fregerit, huic Iolen inposuisse iugum. <br>hoc velit Eurystheus, velit hoc germana Tonantis, <br>     laetaque sit vitae labe noverca tuae.<br>at non ille velit, cui nox (si creditur) una <br>     non tanti, ut tantus conciperere, fuit. <br>Plus tibi quam Iuno nocuit Venus: illa premendo <br>     sustulit, haec humili sub pede colla tenet. <br>respice vindicibus pacatum viribus orbem, <br>     qua latam Nereus caerulus ambit humum. <br>se tibi pax terrae, tibi se tuta aequora debent; <br>     implesti meritis Solis utramque domum. <br>quod te laturum est, caelum prius ipse tulisti:<br>     Hercule supposito sidera fulsit Atlans. <br>quid nisi notitia est misero quaesita pudori, <br>     si cumulas sturpi facta priora nota?<br>tene ferunt geminos pressisse tenaciter angues, <br>     cum tener in cunis iam Iove dignus eras? <br>coepisti melius quam desinis; ultima primis <br>     cedunt: dissimiles hic vir et ille puer. <br>quem non mille ferae, quem non Stheneleius hostis, <br>     non potuit Iuno vincere, vincit Amor. <br>At bene nupta feror, quia nominer Herculis uxor, <br>     sitque socer, rapidis qui tonat altus equis. <br>quam male inaequales veniunt ad aratra iuvenci, <br>     tam premitur magno coniuge nupta minor. <br>non honor est sed onus species laesura ferentes:<br>     siqua voles apte nubere, nube pari. <br>vir mihi semper abest, et coniuge notior hospes<br>     monstraque terribiles persequiturque feras. <br>ipsa domo vidua votis operata pudicis <br>     torqueor, infesto ne vir ab hoste cadat; <br>inter serpentes aprosque avidosque leones <br>     iactor et haesuros terna per ora canes. <br>me pecudum fibrae simulacraque inania somni <br>     ominaque arcana nocte petita movent.","st":"9"},{"sp":"N","t":"aucupor infelix incertae murmura famae<br>     speque timor dubia spesque timore cadit. <br>mater abest queriturque deo placuisse potenti, <br>     nec pater Amphitryon nec puer Hyllus adest.<br>arbiter Eurystheus astu Iunonis iniquae <br>     sentitur nobis iraque longa deae.<br>Haec mihi ferre parum; peregrinos addis amores, <br>     et mater de te quaelibet esse potest. <br>non ego Partheniis temeratam vallibus Augen<br>     nec referam partus, Ormeni nympha, tuos; <br>non tibi crimen erunt, Teuthrantia turba, sorores, <br>     quarum de populo nulla relicta tibi est. <br>una, recens crimen, referetur adultera nobis, <br>     unde ego sum Lydo facta noverca Lamo. <br>Maeandros, totiens qui terris errat in isdem, <br>     qui lassas in se saepe retorquet aquas, <br>vidit in Herculeo suspensa monilia collo,<br>     illo, cui caelum sarcina parva fuit. <br>non puduit fortes auro cohibere lacertos<br>     et solidis gemmas opposuisse toris? <br>nempe sub his animam pestis Nemeaea lacertis <br>     edidit, unde umerus tegmina laevus habet.<br>ausus es hirsutos mitra redimire capillos! <br>     aptior Herculeae populus alba comae. <br>nec te Maeonia lascivae more puellae <br>     incingi zona dedecuisse pudet? <br>non tibi succurrit crudi Diomedis imago, <br>     efferus humana qui dape pavit equas? <br>si te vidisset cultu Busiris in isto, <br>     huic victor victo nempe pudendus eras!<br>detrahat Antaeus duro redimicula collo, <br>     ne pigeat molli succubuisse viro!<br>Inter Ioniacas calathum tenuisse puellas <br>     diceris et dominae pertimuisse minas. <br>non fugis, Alcide, victricem mille laborum <br>     rasilibus calathis inposuisse manum<br>crassaque robusto deducis pollice fila<br>     aequaque formosae pensa rependis erae? <br>a! quotiens, digitis dum torques stamina duris, <br>     praevalidae fusos conminuere manus! <br>[Crederis infelix scuticae tremefactis habenis<br>     ante pedes dominae pertimuisse minas ...<br>eximiis pompis, immania semina laudim]<br>     factaque narrabas dissimulanda tibi:<br>scilicet: immanes elisis faucibus hydros <br>     infantem caudis involuisse manum;<br>ut Tegeaeus aper cupressifero Erymantho <br>     incubet et vasto pondere laedat humum;<br>non tibi Threiciis adfixa penatibus ora, <br>     non hominum pingues caede tacentur equae,<br>prodigiumque triplex, armenti dives Hiberi <br>     Geryones, quamvis in tribus unus erat; <br>inque canes totidem trunco digestus ab uno <br>     Cerberos implicitis angue minante comis; <br>quaeque redundabat fecundo vulnere serpens <br>     fertilis et damnis dives ab ipsa suis,<br>quique inter laevumque latus laevumque lacertum <br>     praegrave conpressa fauce pependit onus,<br>et male confisum pedibus formaque bimembri <br>     pulsum Thessalicis agmen equestre iugis. <br>Haec tu Sidonio potes insignitus amictu <br>     dicere? non cultu lingua retenta silet? <br>se quoque nympha tuis ornavit Dardanis armis <br>     et tulit a capto nota tropaea viro.<br>i nunc, tolle animos et fortia gesta recense:<br>     quo tu non esses, iure vir illa fuit. <br>qua tanto minor es, quanto te, maxime rerum, <br>     quam quos vicisti, vincere maius erat. <br>illi procedit rerum mensura tuarum,<br>     cede bonis: heres laudis amica tuae. <br>o pudor! hirsuti costis exuta leonis <br>     aspera texerunt vellera molle latus! <br>falleris et nescis: non sunt spolia illa leonis, <br>     sed tua, tuque feri victor es, illa tui. <br>femina tela tulit Lernaeis atra venenis, <br>     ferre gravem lana vix satis apta colum, <br>instruxitque manum clava domitrice ferarum<br>     vidit et in speculo coniugis arma sui.<br>Haec tamen audieram; licuit non credere famae, <br>     et venit ad sensus mollis ab aure dolor.<br>ante meos oculos adducitur advena paelex, <br>     nec mihi, quae patior, dissimulare licet! <br>non sinis averti: mediam captiva per urbem <br>     invitis oculis adspicienda venit. <br>nec venit incultis captarum more capillis:<br>     fortunam vultu fassa decente suam<br>ingreditur late lato spectabilis auro, <br>     qualiter in Phrygia tu quoque cultus eras;<br>dat vultum populo sublimis ut Hercule victo:<br>     Oechaliam vivo stare parente putes;<br>forsitan et pulsa Aetolide Deianira <br>     nomine deposito paelicis uxor erit, <br>Eurytidosque Ioles Atque Aonii Alcidae <br>     turpia famosus corpora iunget Hymen.","st":"9"},{"sp":"N","t":"mens fugit admonitu, frigusque perambulat artus, <br>     et iacet in gremio languida facta manus. <br>Me quoque cum multis, sed me sine crimine amasti;<br>     ne pigeat, pugnae bis tibi causa fui. <br>cornua flens legit ripis Achelous in udis <br>     truncaque limosa tempora mersit aqua; <br>semivir occubuit in letifero Eueno <br>     Nessus et infecit sanguis equinus aquas.<br>sed quid ego haec refero? scribenti nuntia venit <br>     fama virum tunicae tabe perire meae. <br>ei mihi! quid feci? quo me furor egit amantem? <br>     impia quid dubitas Deianira mori? <br>An tuus in media coniunx lacerabitur Oeta, <br>     tu sceleris tanti causa superstes eris? <br>siquid adhuc habeo facti, cur Herculis uxor <br>     credar, coniugii mors mea pignus erit.<br>tu quoque cognosces in me, Meleagre, sororem! <br>     impia quid dubitas Deianira mori? <br>Heu devota domus! solio sedet Agrios alto; <br>     Oenea desertum nuda senecta premit;<br>exulat ignotis Tydeus germanus in oris; <br>     alter fatali vivus in igne fuit;<br>exegit ferrum sua per praecordia mater. <br>     impia quid dubitas Deianira mori? <br>Deprecor hoc unum per iura sacerrima lecti, <br>     ne videar fatis insidiata tuis. <br>Nessus, ut est avidum percussus harundine pectus, <br>     “hic,” dixit, “vires sanguis amoris habet.”<br>illita Nesseo misi tibi texta veneno. <br>     impia quid dubitas Deianira mori? <br>Iamque vale, seniorque pater germanaque Gorge<br>     et patria et patriae frater adempte tuae<br>et tu lux oculis hodierna novissima nostris<br>     virque — sed o possis! — et puer Hylle, vale!","st":"9"},{"sp":"HDR","t":"X","st":"10"},{"sp":"N","t":"Illa relicta feris etiam nunc, improbe Theseu<br>vivit. Et haec aequa mente tulisse velis?","st":"10"},{"sp":"N","t":"Mitius inveni quam te genus omne ferarum; <br>     credita non ulli quam tibi peius eram.","st":"10"},{"sp":"N","t":"quae legis, ex illo, Theseu, tibi litore mitto <br>     unde tuam sine me vela tulere ratem, <br>in quo me somnusque meus male prodidit et tu, <br>     per facinus somnis insidiate meis. <br>Tempus erat, vitrea quo primum terra pruina <br>     spargitur et tectae fronde queruntur aves;<br>incertum vigilans ac somno languida movi <br>     Thesea prensuras semisupina manus:<br>nullus erat. referoque manus iterumque retempto<br>     perque torum moveo bracchia: nullus erat.<br>excussere metus somnum; conterrita surgo<br>     membraque sunt viduo praecipitata toro. <br>protinus adductis sonuerunt pectora palmis<br>     utque erat e somno turbida, rupta coma est. <br>Luna fuit; specto siquid nisi litora cernam;<br>     quod videant oculi, nil nisi litus habent. <br>nunc huc, nunc illuc et utroque sine ordine, curro,<br>     alta puellares tardat harena pedes. <br>interea toto clamanti litore “Theseu!”<br>     reddebant nomen concava saxa tuum<br>et quotiens ego te, totiens locus ipse vocabat;<br>     ipse locus miserae ferre volebat opem. <br>Mons fuit; apparent frutices in vertice rari; <br>     hinc scopulus raucis pendet adesus aquis. <br>adscendo; vires animus dabat; atque ita late <br>     aequora prospectu metior alta meo. <br>inde ego — nam ventis quoque sum crudelibus usa — <br>     vidi praecipiti carbasa tenta Noto. <br>aut vidi aut fuerant quae me vidisse putarem;<br>     frigidior glacie semianimisque fui. <br>nec languere diu patitur dolor. excitor illo, <br>     excitor et summa Thesea voce voco. <br>“quo fugis?” exclamo “scelerate revertere Theseu! <br>     flecte ratem! numerum non habet illa suum!”<br>Haec ego. quod voci deerat, plangore replebam; <br>     verbera cum verbis mixta fuere meis. <br>si non audires, ut saltem cernere posses:<br>     iactatae late signa dedere manus.<br>candidaque imposui longae velamina virgae<br>     scilicet oblitos admonitura mei.<br>iamque oculis ereptus eras. tum denique flevi; <br>     torpuerant molles ante dolore genae. <br>quid potius facerent, quam me mea lumina flerent, <br>     postquam desieram vela videre tua? <br>aut ego diffusis erravi sola capillis, <br>     qualis ab Ogygio concita Baccha deo;<br>aut mare prospiciens in saxo frigida sedi, <br>     quamque lapis sedes, tam lapis ipsa fui. <br>saepe torum repeto qui nos acceperat ambos, <br>     sed non acceptos exhibiturus erat<br>et tua quae possum pro te vestigia tango <br>     strataque quae membris intepuere tuis. <br>incumbo lacrimisque toro manante profusis<br>     “pressimus” exclamo “te duo, redde duos! <br>venimus huc ambo; cur non discedimus ambo? <br>     perfide, pars nostri, lectule, maior ubi est?”<br>Quid faciam? quo sola ferar? vacat insula cultu;<br>     non hominum video, non ego facta boum. <br>omne latus terrae cingit mare; navita nusquam.<br>     nulla per ambiguas puppis itura vias. <br>finge dari comitesque mihi ventosque ratemque,<br>     quid sequar? accessus terra paterna negat.<br>ut rate felici pacata per aequora labar, <br>     temperet ut ventos Aeolus; exul ero.<br>non ego te, Crete, centum digesta per urbes, <br>     adspiciam, puero cognita terra Iovi.<br>at pater et tellus iusto regnata parenti <br>     prodita sunt facto, nomina cara, meo,<br>cum tibi, ne victor tecto morerere recurvo, <br>     quae regerent passus, pro duce fila dedi.<br>tum mihi dicebas: “per ego ipsa pericula iuro<br>     te fore, dum nostrum vivet uterque, meam.”<br>Vivimus, et non sum, Theseu, tua, si modo vivis,<br>     femina periuri fraude sepulta viri. <br>me quoque, qua fratrem mactasses, improbe, clava!<br>     esset, quam dederas, morte soluta fides. <br>nunc ego non tantum, quae sum passura, recordor, <br>     sed quaecumque potest ulla relicta pati.<br>occurrunt animo pereundi mille figurae, <br>     morsque minus poenae quam mora mortis habet. <br>iam iam venturos aut hac aut suspicor illac, <br>     qui lanient avido viscera dente lupos. <br>forsitan et fulvos tellus alat ista leones? <br>     quis scit an et saevas tigridas insula habet.<br>et freta dicuntur magnas expellere phocas;<br>     quis vetat et gladios per latus ire meum? <br>Tantum ne religer dura captiva catena, <br>     neve traham serva grandia pensa manu,<br>cui pater est Minos, cui mater filia Phoebi, <br>     quodque magis memini, quae tibi pacta fui! <br>si mare, si terras porrectaque litora vidi,","st":"10"},{"sp":"N","t":"multa mihi terrae, multa minantur aquae. <br>caelum restabat; timeo simulacra deorum;<br>     destituor rapidis praeda cibusque feris.<br>sive colunt habitantque viri, diffidimus illis;<br>     externos didici laesa timere viros. <br>Viveret Androgeos utinam, nec facta luisses <br>     impia funeribus, Cecropi terra, tuis; <br>nec tua mactasset nodoso stipite, Theseu, <br>     ardua parte virum dextera, parte bovem; <br>nec tibi, quae reditus monstrarent, fila dedissem, <br>     fila per adductas saepe recepta manus. <br>non equidem miror, si stat victoria tecum<br>     strataque Cretaeam belua planxit humum. <br>non poterant figi praecordia ferrea cornu; <br>     ut te non tegeres, pectore tutus eras. <br>illic tu silices, illic adamanta tulisti, <br>     illic, qui silices, Thesea, vincat, habes. <br>Crudeles somni, quid me tenuistis inertem? <br>     aut semel aeterna nocte premenda fui. <br>vos quoque crudeles venti, nimiumque parati <br>     flaminaque in lacrimas officiosa meas;<br>dextera crudelis, quae me fratremque necavit, <br>     et data poscenti, nomen inane, fides:<br>in me iurarunt somnus ventusque fidesque:<br>     prodita sum causis una puella tribus.<br>Ergo ego nec lacrimas matris moritura videbo<br>     nec mea qui digitis lumina condat, erit.<br>spiritus infelix peregrinas ibit in auras<br>     nec positos artus unguet amica manus.<br>ossa superstabunt volucres inhumata marinae;<br>     haec sunt officiis digna sepulcra meis.<br>ibis Cecropios portus patriaque receptus, <br>     cum steteris urbis celsus in arce tuae <br>et bene narraris letum taurique virique <br>     sectaque per dubias saxea tecta vias;<br>me quoque narrato sola tellure relictam;<br>     non ego sum titulis subripienda tuis!<br>nec pater est Aegeus, nec tu Pittheidos Aethrae <br>     filius; auctores saxa fretumque tui.<br>Di facerent ut me summa de puppe videres,<br>     movisset vultus maesta figura tuos.<br>nunc quoque non oculis, sed qua potes, adspice mente <br>     haerentem scopulo quem vaga pulsat aqua;<br>adspice demissos lugentis more capillos <br>     et tunicas lacrimis sicut ab imbre graves!<br>corpus ut impulsae segetes aquilonibus horret<br>     litteraque articulo pressa tremente labat. <br>non te per meritum, quoniam male cessit, adoro; <br>     debita sit facto gratia nulla meo. <br>sed ne poena quidem. si non ego causa salutis, <br>     non tamen est cur sis tu mihi causa necis.<br>Has tibi plangendo lugubria pectora lassas <br>     infelix tendo trans freta lata manus; <br>hos tibi qui superant ostendo maesta capillos;<br>     per lacrimas oro, quas tua facta movent:<br>flecte ratem, Theseu, versoque relabere vento;<br>     si prius occidero, tu tamen ossa feres.","st":"10"},{"sp":"HDR","t":"XI","st":"11"},{"sp":"N","t":"Aeolis Aeolidae quam non habet ipsa salutem<br>mittit et armata verba notata manu.","st":"11"},{"sp":"N","t":"Siqua tamen caecis errabunt scripta lituris, <br>     oblitus a dominae caede libellus erit. <br>dextra tenet calamum, strictum tenet altera ferrum<br>     et iacet in gremio charta soluta meo. <br>haec est Aeolidos fratri scribentis imago; <br>     sic videor duro posse placere patri. <br>Ipse necis cuperem nostrae spectator adesset<br>     auctorisque oculis exigeretur opus<br>ut ferus est multoque suis truculentior euris, <br>     spectasset siccis vulnera nostra genis. <br>scilicet est aliquid cum saevis vivere ventis; <br>     ingenio populi convenit ille sui. <br>ille Noto Zephyroque et Sithonio Aquiloni <br>     imperat et pinnis, Eure proterve, tuis. <br>imperat heu! ventis; tumidae non imperat irae<br>     possidet et vitiis regna minora suis. <br>quid iuvat admotam per avorum nomina caelo <br>     inter cognatos posse referre Iovem? <br>num minus infestum, funebria munera, ferrum <br>     feminea teneo, non mea tela, manu? <br>O utinam, Macareu, quae nos commisit in unum, <br>     venisset leto serior hora meo! <br>cur umquam plus me, frater, quam frater amasti<br>     et tibi, non debet quod soror esse, fui? <br>ipsa quoque incalui, qualemque audire solebam, <br>     nescio quem sensi corde tepente deum. <br>fugerat ore color, macies adduxerat artus,<br>     sumebant minimos ora coacta cibos;","st":"11"},{"sp":"N","t":"nec somni faciles et nox erat annua nobis<br>     et gemitum nullo laesa dolore dabam. <br>nec cur haec facerem, poteram mihi reddere causam <br>     nec noram quid amans esset; at illud eram. <br>Prima malum nutrix animo praesensit anili; <br>     prima mihi nutrix “Aeoli,” dixit, “amas!” <br>erubui gremioque pudor deiecit ocellos; <br>     haec satis in tacita signa fatentis erant. <br>iamque tumescebant vitiati pondera ventris<br>     aegraque furtivum membra gravabat onus. <br>quas mihi non herbas, quae non medicamina nutrix <br>     attulit audaci supposuitque manu, <br>ut penitus nostris — hoc te celavimus unum — <br>     visceribus crescens excuteretur onus! <br>a! nimium vivax admotis restitit infans <br>     artibus et tecto tutus ab hoste fuit.<br>iam noviens erat orta soror pulcherrima Phoebi<br>     et nova luciferos Luna movebat equos; <br>nescia, quae faceret subitos mihi causa dolores, <br>     et rudis ad partus et nova miles eram. <br>nec tenui vocem. “quid” ait “tua crimina prodis?”<br>     oraque clamantis conscia pressit anus. <br>quid faciam infelix? gemitus dolor edere cogit, <br>     sed timor et nutrix et pudor ipse vetant. <br>contineo gemitus elapsaque verba reprendo <br>     et cogor lacrimas combibere ipsa meas. <br>mors erat ante oculos et opem Lucina negabat<br>     et grave si morerer mors quoque crimen erat;<br>cum super incumbens scissa tunicaque comaque <br>     pressa refovisti pectora nostra tuis, <br>et mihi “vive, soror, soror o carissima,” aisti<br>     “vive nec unius corpore perde duos. <br>spes bona det vires; fratri nam nupta futura es. <br>     illius de quo mater et uxor eris.”<br>Mortua, crede mihi, tamen ad tua verba revixi <br>     et positum est uteri crimen onusque mei. <br>quid tibi grataris? media sedet Aeolus aula; <br>     crimina sunt oculis subripienda patris. <br>frugibus infantem ramisque albentis olivae <br>     et levibus vittis sedula celat anus<br>fictaque sacra facit dicitque precantia verba; <br>     dat populus sacris, dat pater ipse viam. <br>iam prope limen erat. patrias vagitus ad aures <br>     venit et indicio proditur ille suo.<br>eripit infantem mentitaque sacra revelat <br>     Aeolus. insana regia voce sonat. <br>ut mare fit tremulum, tenui cum stringitur aura, <br>     ut quatitur tepido fraxina virga Noto, <br>sic mea vibrari pallentia membra videres; <br>     quassus ab imposito corpore lectus erat. <br>inruit et nostrum vulgat clamore pudorem<br>     et vix a misero continet ore manus. <br>ipsa nihil praeter lacrimas pudibunda profudi.<br>     torpuerat gelido lingua retenta metu. <br>Iamque dari parvum canibusque avibusque nepotem <br>     iusserat in solis destituique locis. <br>vagitus dedit ille miser — sensisse putares — <br>     quaque suum poterat voce rogabat avum. <br>quid mihi tunc animi credis, germane, fuisse<br>     (nam potes ex animo colligere ipse tuo) <br>cum mea me coram silvas inimicus in altas <br>     viscera montanis ferret edenda lupis? <br>exierat thalamo. tunc demum pectora plangi <br>     contigit inque meas unguibus ire comas. <br>Interea patrius vultu maerente satelles <br>     venit et indignos edidit ore sonos: <br>‘Aeolus hunc ensem mittit tibi’ — tradidit ensem — <br>     ‘et iubet ex merito scire, quid iste velit.’ <br>scimus et utemur violento fortiter ense; <br>     pectoribus condam dona paterna meis. <br>his mea muneribus, genitor, conubia donas? <br>     hac tua dote, pater, filia dives erit?<br>tolle procul, decepte, faces, Hymenaee, maritas <br>     et fuge turbato tecta nefanda pede! <br>ferte faces in me quas fertis, Erinyes atrae, <br>     et meus ex isto luceat igne rogus! <br>nubite felices Parca meliore sorores;<br>     amissae memores sed tamen este mei! <br>Quid puer admisit tam paucis editus horis? <br>     quo laesit facto vix bene natus avum? <br>si potuit meruisse necem, meruisse putetur;<br>     a! miser admisso plectitur ille meo! <br>nate, dolor matris, rapidarum praeda ferarum, <br>     ei mihi! natali dilacerate tuo,<br>nate, parum fausti miserabile pignus amoris,<br>     haec tibi prima dies, haec tibi summa fuit. <br>non mihi te licuit lacrimis perfundere iustis, <br>     in tua non tonsas ferre sepulcra comas; <br>non super incubui, non oscula frigida carpsi;<br>     diripiunt avidae viscera nostra ferae. <br>Ipsa quoque infantis cum vulnere prosequar umbras;","st":"11"},{"sp":"N","t":"nec mater fuero dicta nec orba diu. <br>tu tamen, o frustra miserae sperate sorori, <br>     sparsa, precor, nati collige membra tui<br>et refer ad matrem socioque impone sepulcro<br>     urnaque nos habeat quamlibet arta duos! <br>vive memor nostri lacrimasque in vulnera funde, <br>     neve reformida corpus amantis amans. <br>tu, rogo, dilectae nimium mandata sororis <br>     perfer! mandatum persequar ipsa patris.","st":"11"},{"sp":"HDR","t":"XII","st":"12"},{"sp":"N","t":"Exul inops comtempta novo Medea marito<br>dicit, an a regnis tempora nulla vacant?","st":"12"},{"sp":"N","t":"At tibi Colchorum, memini, regina vacavi, <br>     ars mea cum peteres ut tibi ferret opem!<br>tunc quae dispensant mortalia fila sorores,<br>     debuerant fusos evoluisse meos;<br>tum potui Medea mori bene! quidquid ab illo <br>     produxi vitae tempore, poena fuit. <br>Ei mihi! cur umquam iuvenalibus acta lacertis <br>     Phrixeam petiit Pelias arbor ovem? <br>cur umquam Colchi Magnetida vidimus Argon<br>     turbaque Phasiacam Graia bibistis aquam? <br>cur mihi plus aequo flavi placuere capilli <br>     et decor et linguae gratia ficta tuae? <br>aut, semel in nostras quoniam nova puppis harenas <br>     venerat audacis attuleratque viros, <br>isset anhelatos non praemedicatus in ignes <br>     inmemor Aesonides oraque adusta boum!<br>semina iecisset totidem sevisset et hostes, <br>     ut caderet cultu cultor ab ipse suo! <br>quantum perfidiae tecum, scelerate, perisset!<br>     dempta forent capiti quam mala multa meo!<br>Est aliqua ingrato meritum exprobrare voluptas;<br>     hac fruar, haec de te gaudia sola feram. <br>iussus inexpertam Colchos advertere puppim <br>     intrasti patriae regna beata meae. <br>hoc illic Medea fui, nova nupta quod hic est; <br>     quam pater est illi, tam mihi dives erat. <br>hic Ephyren bimarem, Scythia tenus ille nivosa <br>     omne tenet, Ponti qua plaga laeva iacet. <br>Accipit hospitio iuvenes Aeeta Pelasgos, <br>     et premitis pictos corpora Graia toros.","st":"12"},{"sp":"N","t":"tunc ego te vidi, tunc coepi scire, quid esses; <br>     illa fuit mentis prima ruina meae. <br>et vidi et perii! nec notis ignibus arsi, <br>     ardet ut ad magnos pinea taeda deos. <br>et formosus eras et me mea fata trahebant:<br>     abstulerant oculi lumina nostra tui. <br>perfide, sensisti! quis enim bene celat amorem? <br>     eminet indicio prodita flamma suo. <br>Dicitur interea tibi lex, ut dura ferorum <br>     insolito premeres vomere colla boum. <br>Martis erant tauri plus quam per cornua saevi, <br>     quorum terribilis spiritus ignis erat,<br>aere pedes solidi praetentaque naribus aera, <br>     nigra per adflatus haec quoque facta suos. <br>semina praeterea populos genitura iuberis <br>     spargere devota lata per arva manu, <br>qui peterent natis secum tua corpora telis:<br>     illa est agricolae messis iniqua suo.<br>lumina custodis succumbere nescia somno<br>     ultimus est aliqua decipere arte labor. <br>Dixerat Aeetes: maesti consurgitis omnes, <br>     mensaque purpureos deserit alta toros. <br>quam tibi tunc longe regnum dotale Creusae <br>     et socer et magni nata Creontis erat?<br>tristis abis. oculis abeuntem prosequor udis<br>     et dixit tenui murmure lingua: “vale!” <br>ut positum tetigi thalamo male saucia lectum, <br>     acta est per lacrimas nox mihi quanta fuit.<br>ante oculos taurique meos segetesque nefandae, <br>     ante meos oculos pervigil anguis erat. <br>hinc amor, hinc timor est — ipsum timor auget amorem. <br>     mane erat et thalamo cara recepta soror <br>disiectamque comas aversaque in ora iacentem <br>     invenit et lacrimis omnia plena meis. <br>orat opem Minyis, alter petit, impetrat alter,<br>     Aesonio iuveni quod rogat illa, damus. <br>Est nemus et piceis et frondibus ilicis atrum, <br>     vix illuc radiis solis adire licet;<br>sunt in eo — fuerant certe — delubra Dianae:<br>     aurea barbarica stat dea facta manu. <br>noscis an exciderunt mecum loca? venimus illuc;<br>     orsus es infido sic prior ore loqui: <br>“ius tibi et arbitrium nostrae fortuna salutis <br>     tradidit inque tua est vitaque morsque manu.<br>perdere posse sat est, siquem iuvet ipsa potestas; <br>     sed tibi servatus gloria maior ero. <br>per mala nostra precor, quorum potes esse levamen, <br>     per genus et numen cuncta videntis avi, <br>per triplices vultus arcanaque sacra Dianae<br>     et si forte aliquos gens habet ista deos:<br>o virgo, miserere mei, miserere meorum, <br>     effice me meritis tempus in omne tuum! <br>quodsi forte virum non dedignare Pelasgum — <br>     sed mihi tam faciles unde meosque deos? — <br>spiritus ante meus tenues vanescet in auras,<br>     quam thalamo, nisi tu, nupta sit ulla meo.<br>conscia sit Iuno sacris praefecta maritis<br>     et dea marmorea cuius in aede sumus!”<br>Haec animum — et quota pars haec sunt? — movere puellae <br>     simplicis et dextrae dextera iuncta meae. <br>vidi etiam lacrimas — an pars est fraudis in illis?<br>     sic cito sum verbis capta puella tuis. <br>iungis et aeripedes inadusto corpore tauros <br>     et solidam iusso vomere findis humum. <br>arva venenatis pro semine dentibus imples, <br>     nascitur et gladios scutaque miles habet. <br>ipsa ego, quae dederam medicamina, pallida sedi, <br>     cum vidi subitos arma tenere viros, <br>donec terrigenae — facinus mirabile! — fratres <br>     inter se strictas conseruere manus.<br>Insopor ecce vigil squamis crepitantibus horrens <br>     sibilat et torto pectore verrit humum.<br>dotis opes ubi erant? ubi erat tibi regia coniunx<br>     quique maris gemini distinet Isthmos aquas? <br>illa ego, quae tibi sum nunc denique barbara facta,<br>     nunc tibi sum pauper, nunc tibi visa nocens, <br>flammea subduxi medicato lumina somno<br>     et tibi quae raperes vellera tuta dedi. <br>proditus est genitor, regnum patriamque reliqui,<br>     munus in exilio quod licet esse tuli,<br>virginitas facta est peregrini praeda latronis,<br>     optima cum cara matre relicta soror. <br>At non te fugiens sine me, germane, reliqui.<br>     deficit hoc uno littera nostra loco:<br>quod facere ausa mea est, non audet scribere dextra. <br>     sic ego, sed tecum, dilaceranda fui!<br>nec tamen extimui — quid enim post illa timerem? — <br>     credere me pelago femina iamque nocens. <br>numen ubi est? ubi di? meritas subeamus in alto, <br>     tu fraudis poenas, credulitatis ego.","st":"12"},{"sp":"N","t":"Compressos utinam Symplegades elisissent<br>     nostraque adhaererent ossibus ossa tuis!<br>aut nos Scylla rapax canibus misisset edendos!<br>     debuit ingratis Scylla nocere viris.<br>quaeque vomit totidem fluctus totidemque resorbet, <br>     nos quoque Trinacriae subposuisset aquae!<br>sospes ad Haemonias victorque reverteris urbes; <br>     ponitur ad patrios aurea lana deos. <br>Quid referam Peliae natas pietate nocentes <br>     caesaque virginea membra paterna manu? <br>ut culpent alii, tibi me laudare necesse est, <br>     pro quo sum totiens esse coacta nocens. <br>ausus es — o iusto desunt sua verba dolori! — <br>     ausus es “Aesonia” dicere “cede domo!” <br>iussa domo cessi natis comitata duobus <br>     et, qui me sequitur semper, amore tui. <br>ut subito nostras Hymen cantatus ad aures <br>     venit et accenso lampades igne micant<br>tibiaque effundit socialia carmina vobis, <br>     at mihi funerea flebiliora tuba, <br>pertimui, nec adhuc tantum scelus esse putabam,<br>     sed tamen in toto pectore frigus erat. <br>turba ruunt et “Hymen” clamant “Hymenaee!” frequenter;<br>     quo propior vox haec, hoc mihi peius erat. <br>diversi flebant servi lacrimasque tegebant — <br>     quis vellet tanti nuntius esse mali? <br>me quoque quidquid erat potius nescire iuvabat,<br>     sed tamquam scirem, mens mea tristis erat, <br>cum minor e pueris iussus studione videndi <br>     constitit ad geminae limina prima foris:<br>“hinc” mihi “mater adi! pompam pater” inquit “Iason <br>     ducit et adiunctos aureus urget equos!”<br>protinus abscissa planxi mea pectora veste<br>     tuta nec a digitis ora fuere meis. <br>ire animus mediae suadebat in agmina turbae <br>     sertaque conpositis demere rapta comis.<br>vix me continui, quin sic laniata capillos <br>     clamarem “meus est!” iniceremque manus. <br>Laese pater, gaude! Colchi gaudete relicti! <br>     inferias umbrae fratris habete mei!<br>deseror amissis regno patriaque domoque <br>     coniuge, qui nobis omnia solus erat.<br>serpentes igitur potui taurosque furentes,<br>     unum non potui perdomuisse virum.<br>quaeque feros pepuli doctis medicatibus ignes, <br>     non valeo flammas effugere ipsa meas. <br>ipsi me cantus herbaeque artesque relinquunt<br>     nil dea, nil Hecates sacra potentis agunt. <br>non mihi grata dies, noctes vigilantur amarae<br>     et tener a misero pectore somnus abit. <br>quae me non possum, potui sopire draconem.<br>     utilior cuivis quam mihi cura mea est. <br>quos ego servavi, paelex amplectitur artus<br>     et nostri fructus illa laboris habet. <br>Forsitan et, stultae dum te iactare maritae <br>     quaeris et iniustis auribus apta loqui, <br>in faciem moresque meos nova crimina fingas. <br>     rideat et vitiis laeta sit illa meis.<br>rideat et Tyrio iaceat sublimis in ostro — <br>     flebit et ardores vincet adusta meos.<br>dum ferrum flammaeque aderunt sucusque veneni, <br>     hostis Medeae nullus inultus erit.<br>Quod si forte preces praecordia ferrea tangunt, <br>     nunc animis audi verba minora meis.<br>tam tibi sum supplex, quam tu mihi saepe fuisti, <br>     nec moror ante tuos procubuisse pedes. <br>si tibi sum vilis, communis respice natos:<br>     saeviet in partus dira noverca meos. <br>et nimium similes tibi sunt, et imagine tangor<br>     et quotiens video, lumina nostra madent. <br>per superos oro, per avitae lumina flammae, <br>     per meritum et natos, pignora nostra, duos,<br>redde torum, pro quo tot res insana reliqui!<br>     adde fidem dictis auxiliumque refer! <br>non ego te imploro contra taurosque virosque, <br>     utque tua serpens victa quiescat ope; <br>te peto, quem merui, quem nobis ipse dedisti, <br>     cum quo sum pariter facta parente parens. <br>Dos ubi sit, quaeris? campo numeravimus illo, <br>     qui tibi laturo vellus arandus erat. <br>aureus ille aries villo spectabilis alto,<br>     dos mea: “quam” dicam si tibi “redde,” neges. <br>dos mea tu sospes, dos est mea Graia iuventus.<br>     i nunc, Sisyphias, inprobe, confer opes.<br>quod vivis, quod habes nuptam socerumque potentes, <br>     hoc ipsum, ingratus quod potes esse, meum est. <br>quos equidem actutum — sed quid praedicere poenam <br>     attinet? ingentis parturit ira minas.<br>quo feret ira sequar. facti fortasse pigebit;<br>     et piget infido consuluisse viro. <br>viderit ista deus, qui nunc mea pectora versat.","st":"12"},{"sp":"N","t":"nescio quid certe mens mea maius agit.","st":"12"},{"sp":"HDR","t":"XIII","st":"13"},{"sp":"N","t":"Mittit et optat amans, quo mittitur, ire salutem <br>     Haemonis Haemonio Laodamia viro. <br>Aulide te fama est vento retinente morari:<br>     a! me cum fugeres, hic ubi ventus erat? <br>tum freta debuerant vestris obsistere remis; <br>     illud erat saevis utile tempus aquis. <br>oscula plura viro mandataque plura dedissem<br>     et sunt quae volui dicere multa tibi. <br>raptus es hinc praeceps et qui tua vela vocaret, <br>     quem cuperent nautae, non ego, ventus erat.<br>ventus erat nautis aptus, non aptus amanti;<br>     solvor ab amplexu, Protesilae, tuo<br>linguaque mandantis verba inperfecta reliquit; <br>     vix illud potui dicere triste “vale.” <br>Incubuit Boreas abreptaque vela tetendit, <br>     iamque meus longe Protesilaus erat. <br>dum potui spectare virum, spectare iuvabat<br>     sumque tuos oculos usque secuta meis; <br>ut te non poteram, poteram tua vela videre, <br>     vela diu vultus detinuere meos. <br>at postquam nec te nec vela fugacia vidi, <br>     et quod spectarem, nil nisi pontus erat, <br>lux quoque tecum abiit, tenebrisque exanguis obortis <br>     succiduo dicor procubuisse genu. <br>vix socer Iphiclus, vix me grandaevus Acastus, <br>     vix mater gelida maesta refecit aqua.<br>officium fecere pium, sed inutile nobis:<br>     indignor miserae non licuisse mori.<br>Ut rediit animus, pariter rediere dolores;<br>     pectora legitimus casta momordit amor. <br>nec mihi pectendos cura est praebere capillos<br>     nec libet aurata corpora veste tegi. <br>ut quas pampinea tetigisse Bicorniger hasta<br>     creditur, huc illuc, qua furor egit, eo. <br>conveniunt matres Phylleides et mihi clamant: <br>     “Indue regales, Laodamia, sinus!”<br>scilicet ipsa geram saturatas murice lanas, <br>     bella sub Iliacis moenibus ille gerat? <br>ipsa comas pectar? galea caput ille premetur? <br>     ipsa novas vestes, dura vir arma ferat? <br>qua possum, squalore tuos imitata labores <br>     dicar et haec belli tempora tristis agam. <br>Dyspari Priamide, damno formose tuorum, <br>     tam sis hostis iners quam malus hospes eras!<br>aut te Taenariae faciem culpasse maritae<br>     aut illi vellem displicuisse tuam.<br>tu, qui pro rapta nimium, Menelae, laboras, <br>     ei mihi! quam multis flebilis ultor eris.<br>di, precor, a nobis omen removete sinistrum<br>     et sua det reduci vir meus arma Iovi! <br>sed timeo, quotiens subiit miserabile bellum; <br>     more nivis lacrimae sole madentis eunt. <br>Ilion et Tenedos Simoisque et Xanthus et Ide <br>     nomina sunt ipso paene timenda sono. <br>nec rapere ausurus, nisi se defendere posset, <br>     hospes erat: vires noverat ille suas. <br>venerat, ut fama est, multo spectabilis auro <br>     quique suo Phrygias corpore ferret opes, <br>classe virisque potens, per quae fera bella geruntur — <br>     et sequitur regni pars quota quemque sui? <br>his ego te victam, consors Ledaea gemellis, <br>     suspicor, haec Danais posse nocere puto. <br>Hectora nescio quem timeo; Paris Hectora dixit<br>     ferrea sanguinea bella movere manu;<br>Hectora, quisquis is est, si sum tibi cara, caveto: <br>     signatum memori pectore nomen habe! <br>hunc ubi vitaris, alios vitare memento <br>     et multos illic Hectoras esse puta<br>et facito ut dicas, quotiens pugnare parabis: <br>     “parcere me iussit Laodamia sibi.<br>si cadere Argolico fas est sub milite Troiam, <br>     te quoque non ullum vulnus habente cadat. <br>pugnet et adversos tendat Menelaus in hostes,<br>     hostibus e mediis nupta petenda viro est. <br>causa tua est dispar: tu tantum vivere pugna, <br>     inque pios dominae posse redire sinus!<br>Parcite, Dardanidae, de tot, precor, hostibus uni, <br>     ne meus ex illo corpore sanguis eat! <br>non est quem deceat nudo concurrere ferro<br>     saevaque in oppositos pectora ferre viros.<br>fortius ille potest multo, quam pugnat, amare. <br>     bella gerant alii; Protesilaus amet! <br>Nunc fateor: volui revocare, animusque ferebat; <br>     substitit auspicii lingua timore mali. <br>cum foribus velles ad Troiam exire paternis, <br>     pes tuus offenso limine signa dedit. <br>ut vidi, ingemui, tacitoque in pectore dixi: <br>     “signa reversuri sint, precor, ista viri!” <br>haec tibi nunc refero, ne sis animosus in armis.<br>     fac, meus in ventos hic timor omnis eat! <br>Sors quoque nescio quem fato designat iniquo,","st":"13"},{"sp":"N","t":"qui primus Danaum Troada tangat humum:<br>infelix, quae prima virum lugebit ademptum! <br>     di faciant, ne tu strenuus esse velis! <br>inter mille rates tua sit millensima puppis<br>     iamque fatigatas ultima verset aquas! <br>hoc quoque praemoneo: de nave novissimus exi!<br>     non est, quo properas, terra paterna tibi. <br>cum venies, remoque move veloque carinam <br>     inque tuo celerem litore siste gradum! <br>Sive latet Phoebus seu terris altior exstat, <br>     tu mihi luce celer, tu mihi nocte venis:<br>nocte tamen quam luce magis. nox grata puellis,<br>     quarum suppositus colla lacertus habet. <br>aucupor in lecto mendaces caelibe somnos; <br>     dum careo veris gaudia falsa iuvant. <br>Sed tua cur nobis pallens occurrit imago? <br>     cur venit a labris multa querela tuis? <br>excutior somno simulacraque noctis adoro; <br>     nulla caret fumo Thessalis ara meo:<br>tura damus lacrimamque super, qua sparsa relucet, <br>     ut solet adfuso surgere flamma mero. <br>quando ego te reducem cupidis amplexa lacertis<br>     languida laetitia solvar ab ipsa mea? <br>quando erit, ut lecto mecum bene iunctus in uno <br>     militiae referas splendida facta tuae? <br>quae mihi dum referes, quamvis audire iuvabit, <br>     multa tamen capies oscula, multa dabis. <br>semper in his apte narrantia verba resistunt; <br>     promptior est dulci lingua refecta mora. <br>Sed cum Troia subit, subeunt ventique fretumque; <br>     spes bona sollicito victa timore cadit. <br>hoc quoque, quod venti prohibent exire carinas, <br>     me movet: invitis ire paratis aquis. <br>quis velit in patriam vento prohibente reverti? <br>     a patria pelago vela vetante datis! <br>ipse suam non praebet iter Neptunus ad urbem. <br>     quo ruitis? vestras quisque redite domos! <br>quo ruitis, Danai? ventos audite vetantes! <br>     non subiti casus — numinis ista mora est.<br>quid petitur tanto nisi turpis adultera bello? <br>     dum licet, Inachiae vertite vela rates! <br>sed quid ago? revoco? revocaminis omen abesto<br>     blandaque compositas aura secundet aquas! <br>Troasin invideo, quae si lacrimosa suorum <br>     funera conspicient, nec procul hostis erit;<br>ipsa suis manibus forti nova nupta marito <br>     imponet galeam Dardanaque arma dabit;<br>arma dabit, dumque arma dabit, simul oscula sumet — <br>     hoc genus officii dulce duobus erit — <br>producetque virum dabit et mandata reverti <br>     et dicet: “referas ista fac arma Iovi!”<br>ille ferens dominae mandata recentia secum <br>     pugnabit caute respicietque domum. <br>exuet haec reduci clipeum galeamque resolvet<br>     excipietque suo corpora lassa sinu. <br>Nos sumus incertae, nos anxius omnia cogit, <br>     quae possunt fieri, facta putare timor. <br>dum tamen arma geres diverso miles in orbe, <br>     quae referat vultus est mihi cera tuos:<br>illi blanditias, illi tibi debita verba <br>     dicimus, amplexus accipit illa meos. <br>crede mihi, plus est, quam quod videatur, imago; <br>     adde sonum cerae, Protesilaus erit. <br>hanc specto teneoque sinu pro coniuge vero<br>     et tamquam possit verba referre, queror.<br>Per reditus corpusque tuum, mea numina, iuro<br>     perque pares animi coniugiique faces<br>perque quod ut videam canis albere capillis,<br>     quod tecum possis ipse referre, caput,<br>me tibi venturam comitem, quocumque vocaris, <br>     sive — quod heu! timeo — sive superstes eris. <br>ultima mandato claudetur epistula parvo: <br>     si tibi cura mei, sit tibi cura tui!","st":"13"},{"sp":"HDR","t":"XIV","st":"14"},{"sp":"N","t":"Mittit Hypermestra de tot modo fratribus uni;<br>     cetera nuptarum crimine turba iacet. <br>clausa domo teneor gravibusque coercita vinclis; <br>     est mihi supplicii causa fuisse piam. <br>quod manus extimuit iugulo demittere ferrum, <br>     sum rea; laudarer, si scelus ausa forem. <br>esse ream praestat, quam sic placuisse parenti; <br>     non piget immunes caedis habere manus. <br>me pater igne licet, quem non violavimus, urat, <br>     quaeque aderant sacris, tendat in ora faces<br>aut illo iugulet, quem non bene tradidit ensem, <br>     ut qua non cecidit vir nece, nupta cadam, — <br>non tamen ut dicant morientia “paenitet!” ora, <br>     efficiet. non est, quam piget esse piam!<br>paeniteat sceleris Danaum saevasque sorores; <br>     hic solet eventus facta nefanda sequi.<br>Cor pavet admonitu temeratae sanguine noctis<br>     et subitus dextrae praepedit ossa tremor. <br>quam tu caede putes fungi potuisse mariti, <br>     scribere de facta non sibi caede timet! <br>Sed tamen experiar. modo facta crepuscula terris,<br>     ultima pars lucis primaque noctis erat. <br>ducimur Inachides magni sub tecta Pelasgi<br>     et socer armatas accipit ipse nurus. <br>undique conlucent praecinctae lampades auro; <br>     dantur in invitos impia tura focos.<br>vulgus “Hymen, Hymenaee!” vocant. fugit ille vocantes; <br>     ipsa Iovis coniunx cessit ab urbe sua. <br>ecce mero dubii comitum clamore frequentes<br>     flore novo madidas impediente comas, <br>in thalamos laeti — thalamos sua busta — feruntur <br>     strataque corporibus funere digna premunt. <br>Iamque cibo vinoque graves somnoque iacebant<br>     securumque quies alta per Argos erat.<br>circum me gemitus morientum audire videbar<br>     et tamen audibam quodque verebar, erat. <br>sanguis abit, mentemque calor corpusque relinquit<br>     inque novo iacui frigida facta toro. <br>ut leni Zephyro graciles vibrantur aristae, <br>     frigida populeas ut quatit aura comas, <br>aut sic, aut etiam tremui magis. ipse iacebas<br>     quaeque tibi dederant vina, soporis eras.<br>Excussere metum violenti iussa parentis; <br>     erigor et capio tela tremente manu. <br>non ego falsa loquar. ter acutum sustulit ensem, <br>     ter male sublato reccidit ense manus. <br>admovi iugulo sine me tibi vera fateri;<br>[tandem victa mei saeva formidine patris]<br>     admovi iugulo tela paterna tuo; <br>sed timor et pietas crudelibus obstitit ausis<br>     castaque mandatum dextra refugit opus. <br>purpureos laniata sinus, laniata capillos <br>     exiguo dixi talia verba sono: <br>“saevus, Hypermestra, pater est tibi; iussa parentis <br>     effice; germanis sit comes iste suis! <br>femina sum et virgo, natura mitis et annis; <br>     non faciunt molles ad fera tela manus. <br>quin age dumque iacet, fortis imitare sorores;<br>     credibile est caesos omnibus esse viros.","st":"14"},{"sp":"N","t":"si manus haec aliquam posset committere caedem, <br>     morte foret dominae sanguinolenta suae. <br>at meruere necem patruelia regna tenendo; <br>     quae tamen externis danda forent generis<br>finge viros meruisse mori: quid fecimus ipsae? <br>     quo mihi commisso non licet esse piae? <br>quid mihi cum ferro? quo bellica tela puellae? <br>     aptior est digitis lana colusque meis.”<br>Haec ego. dumque queror, lacrimae sua verba sequuntur <br>     deque meis oculis in tua membra cadunt. <br>dum petis amplexus sopitaque bracchia iactas, <br>     paene manus telo saucia facta tua est. <br>iamque patrem famulosque patris lucemque timebam.<br>     expulerunt somnos haec mea dicta tuos: <br>“surge age, Belide, de tot modo fratribus unus! <br>     nox tibi, ni properas, ista perennis erit!”<br>territus exsurgis, fugit omnis inertia somni, <br>     adspicis in timida fortia tela manu. <br>quaerenti causam “dum nox sinit, effuge!” dixi,<br>     dum nox atra sinit, tu fugis, ipsa moror. <br>Mane erat et Danaus generos ex caede iacentes <br>     dinumerat. summae criminis unus abes. <br>fert male cognatae iacturam mortis in uno <br>     et queritur facti sanguinis esse parum. <br>abstrahor a patriis pedibus raptamque capillis<br>   — haec meruit pietas praemia? — carcer habet. <br>Scilicet ex illo Iunonia permanet ira, <br>     cum bos ex homine est, ex bove facta dea — <br>at satis est poenae teneram mugisse puellam <br>     nec modo formosam posse placere Iovi. <br>adstitit in ripa liquidi nova vacca parentis<br>     cornuaque in patriis non sua vidit aquis<br>conatoque queri mugitus edidit ore <br>     territaque est forma, territa voce sua. <br>quid furis, infelix? quid te miraris in unda? <br>     quid numeras factos ad nova membra pedes? <br>illa Iovis magni paelex metuenda sorori <br>     fronde levas nimiam caespitibusque famem; <br>fonte bibis spectasque tuam stupefacta figuram <br>     et, te ne feriant quae geris arma, times.<br>quaeque modo, ut posses etiam Iove digna videri, <br>     dives eras, nuda nuda recumbis humo. <br>per mare, per terras cognataque flumina curris; <br>     dat mare, dant amnes, dat tibi terra viam. <br>quae tibi causa fugae? quid, io! freta longa pererras? <br>     non poteris vultus effugere ipsa tuos. <br>Inachi, quo properas? eadem sequerisque fugisque; <br>     tu tibi dux comiti, tu comes ipsa duci. <br>Per septem Nilus portus emissus in aequor <br>     exuit insana paelicis ora bove. <br>ultima quid referam, quorum mihi cana senectus <br>     auctor? dant anni quod querar, ecce, mei. <br>bella pater patruusque gerunt; regnoque domoque <br>     pellimur; eiectos ultimus orbis habet.<br>Ille ferox solus solio sceptroque potitur;<br>     cum sene nos inopi turba vagamur inops.<br>de fratrum populo pars exiguissima restat;<br>     quique dati leto, quaeque dedere, fleo.<br>nam mihi quot fratres, totidem periere sorores;<br>     accipiat lacrimas utraque turba meas.<br>en ego, quod vivis, poenae crucianda reservor:<br>     quid fiet sonti, cum rea laudis agar?<br>et consanguineae quondam centesima turbae <br>     infelix uno fratre manente cadam.<br>At tu, siqua piae, Lynceu, tibi cura sororis<br>     quaeque tibi tribui munera, dignus habes,<br>vel fer opem vel dede neci; defunctaque vita <br>     corpora furtivis insuper adde rogis<br>et sepeli lacrimis perfusa fidelibus ossa<br>     sculptaque sint titulo nostra sepulcra brevi: <br>“exul Hypermestra, pretium pietatis iniquum, <br>     quam mortem fratri depulit, ipsa tulit.” <br>Scribere plura libet, sed pondere lapsa catenae <br>     est manus et vires subtrahit ipse timor.","st":"14"},{"sp":"HDR","t":"XV","st":"15"},{"sp":"N","t":"Ecquid, ut adspecta est studiosae littera dextrae, <br>     Protinus est oculis cognita nostra tuis?<br>an, nisi legisses auctoris nomina Sapphus, <br>     hoc breve nescires unde veniret opus? <br>Forsitan et quare mea sint alterna requiras <br>     carmina, cum lyricis sim magis apta modis:<br>flendus amor meus est; elegiae flebile carmen; <br>     non facit ad lacrimas barbitos ulla meas. <br>Uror ut indomitis ignem exercentibus Euris <br>     fertilis accensis messibus ardet ager. <br>arva Phaon celebrat diversa Typhoidos Aetnae; <br>     me calor Aetnaeo non minor igne tenet.<br>nec mihi, dispositis quae iungam carmina nervis, <br>     proveniunt; vacuae carmina mentis opus.<br>nec me Pyrrhiades Methymniadesve puellae, <br>     nec me Lesbiadum cetera turba iuvant. <br>vilis Anactorie, vilis mihi candida Cydro,<br>     non oculis grata est Atthis ut ante meis<br>atque aliae centum, quas non sine crimine amavi.<br>     improbe, multarum quod fuit, unus habes!<br>Est in te facies, sunt apti lusibus anni,<br>     o facies oculis insidiosa meis! <br>sume fidem et pharetram — fies manifestus Apollo; <br>     accedant capiti cornua — Bacchus eris.<br>et Phoebus Daphnen, et Cnosida Bacchus amavit<br>     nec norat lyricos illa vel illa modos.<br>at mihi Pegasides blandissima carmina dictant; <br>     iam canitur toto nomen in orbe meum;<br>nec plus Alcaeus, consors patriaeque lyraeque<br>     laudis habet, quamvis grandius ille sonet. <br>si mihi difficilis formam natura negavit, <br>     ingenio formae damna repende meae. <br>sum brevis. at nomen, quod terras impleat omnes, <br>     est mihi: mensuram nominis ipsa fero. <br>candida si non sum, placuit Cepheia Perseo <br>     Andromede patriae fusca colore suae. <br>et variis albae iunguntur saepe columbae<br>     et niger a viridi turtur amatur ave. <br>si nisi quae facie poterit te digna videri, <br>     nulla futura tua est, nulla futura tua est!<br>At mea cum legerem, sat iam formosa videbar:<br>     unam iurabas usque decere loqui. <br>cantabam, memini (meminerunt omnia amantes)<br>     oscula cantanti tu mihi rapta dabas. <br>hoc quoque laudabas, omni tibi parte placebam<br>     sed tunc praecipue, cum fit Amoris opus. <br>tunc te plus solito lascivia nostra iuvabat<br>     crebraque mobilitas aptaque verba ioco<br>et quod, ubi amborum fuerat confusa voluptas, <br>     plurimus in lasso corpore languor erat.<br>Nunc tibi Sicelides veniunt nova praeda puellae. <br>     quid mihi cum Lesbo? Sicelis esse volo. <br>o vos erronem tellure remittite vestra, <br>     Nisiades matres Nisiadesque nurus!<br>nec vos decipiant blandae mendacia linguae:<br>     quod vobis dicit, dixerat ante mihi. <br>tu quoque quae montes celebras, Erycina, Sicanos<br>     (nam tua sum) vati consule, diva, tuae! <br>an gravis inceptum peragit fortuna tenorem <br>     et manet in cursu semper acerba suo? <br>sex mihi natales ierant, cum lecta parentis <br>     ante diem lacrimas ossa bibere meas. <br>arsit inops frater meretricis captus amore <br>     mixtaque cum turpi damna pudore tulit.<br>factus inops agili peragit freta caerula remo, <br>     quasque male amisit, nunc male quaerit opes.<br>me quoque, quod monui bene multa fideliter, odit; <br>     hoc mihi libertas, hoc pia lingua dedit. <br>et tamquam desit, quae me sine fine fatiget, <br>     accumulat curas filia parva meas. <br>Ultima tu nostris accedis causa querelis;<br>     non agitur vento nostra carina suo. <br>ecce iacent collo sparsi sine lege capilli <br>     nec premit articulos lucida gemma meos.<br>veste tegor vili, nullum est in crinibus aurum, <br>     non Arabum noster dona capillus habet. <br>cui colar infelix aut cui placuisse laborem? <br>     ille mei cultus unicus auctor abes. <br>molle meum levibusque cor est violabile telis<br>     et semper causa est, cur ego semper amem,<br>sive ita nascenti legem dixere Sorores <br>     nec data sunt vitae fila severa meae, <br>sive abeunt studia in mores artisque magistra <br>     ingenium nobis molle Thalia facit. <br>quid mirum, si me primae lanuginis aetas <br>     abstulit atque anni quos vir amare potest? <br>hunc ne pro Cephalo raperes, Aurora, timebam!<br>     (et faceres sed te prima rapina tenet!)<br>hunc si conspiciat, quae conspicit omnia, Phoebe, <br>     iussus erit somnos continuare Phaon.<br>hunc Venus in caelum curru vexisset eburneo,","st":"15"},{"sp":"N","t":"sed videt et Marti posse placere suo. <br>o nec adhuc iuvenis, nec iam puer, utilis aetas, <br>     o decus atque aevi gloria magna tui, <br>huc ades inque sinus, formose, relabere nostros:<br>     non ut ames oro, me sed amare sinas!<br>Scribimus et lacrimis oculi rorantur obortis; <br>     adspice quam sit in hoc multa litura loco.<br>si tam certus eras hinc ire, modestius isses, <br>     et modo dixisses “Lesbi puella, vale!” <br>non tecum lacrimas, non oscula nostra tulisti; <br>     denique non timui, quod dolitura fui. <br>nil de te mecum est, nisi tantum iniuria. nec tu, <br>     admoneat quod te, pignus amantis habes. <br>non mandata dedi. neque enim mandata dedissem <br>     ulla, nisi ut nolles immemor esse mei. <br>per tibi qui numquam longe discedit Amorem<br>     perque novem iuro, numina nostra, deas, <br>cum mihi nescio quis “fugiunt tua gaudia” dixit<br>     nec me flere diu, nec potuisse loqui;<br>et lacrimae deerant oculis et verba palato, <br>     adstrictum gelido frigore pectus erat. <br>postquam se dolor invenit nec pectora plangi <br>     nec puduit scissis exululare comis, <br>non aliter quam si nati pia mater adempti <br>     portet ad exstructos corpus inane rogos. <br>gaudet et e nostro crescit maerore Charaxus <br>     frater et ante oculos itque reditque meos.<br>utque pudenda mei videatur causa doloris, <br>     “quid dolet haec? certe filia vivit!” ait. <br>non veniunt in idem pudor atque amor; omne videbat <br>     vulgus; eram lacero pectus aperta sinu. <br>Tu mihi cura, Phaon; te somnia nostra reducunt — <br>     somnia formoso candidiora die. <br>illic te invenio, quamvis regionibus absis; <br>     sed non longa satis gaudia somnus habet.<br>saepe tuos nostra cervice onerare lacertos, <br>     saepe tuae videor supposuisse meos.<br>oscula cognosco, quae tu committere lingua <br>     aptaque consueras accipere, apta dare. <br>blandior interdum verisque simillima verba <br>     eloquor et vigilant sensibus ora meis; — <br>ulteriora pudet narrare, sed omnia fiunt — <br>     et iuvat — et siccae non licet esse mihi. <br>At cum se Titan ostendit et omnia secum, <br>     tam cito me somnos destituisse queror; <br>antra nemusque peto, tamquam nemus antraque prosint:<br>     conscia deliciis illa fuere meis. <br>illuc mentis inops, ut quam furialis Enyo <br>     attigit, in collo crine iacente feror. <br>antra vident oculi scabro pendentia tofo, <br>     quae mihi Mygdonii marmoris instar erant:<br>invenio silvam, quae saepe cubilia nobis <br>     praebuit et multa texit opaca coma.<br>at non invenio dominum silvaeque meumque. <br>     vile solum locus est — dos erat ille loci. <br>cognovi pressas noti mihi caespitis herbas; <br>     de nostro curvum pondere gramen erat. <br>incubui tetigique locum qua parte fuisti; <br>     grata prius lacrimas combibit herba meas. <br>quin etiam rami positis lugere videntur<br>     frondibus et nullae dulce queruntur aves.<br>sola virum non ulta pie maestissima mater <br>     concinit Ismarium Daulias ales Ityn. <br>ales Ityn, Sappho desertos cantat amores;<br>     hactenus, ut media cetera nocte, silent. <br>Est nitidus vitroque magis perlucidus omni <br>     fons sacer; hunc multi numen habere putant.<br>quem supra ramos expandit aquatica lotos, <br>     una nemus, tenero caespite terra viret. <br>hic ego cum lassos posuissem flebilis artus, <br>     constitit ante oculos Naias una meos;<br>constitit et dixit: “quoniam non ignibus aequis <br>     ureris, Ambracia est terra petenda tibi. <br>Phoebus ab excelso, quantum patet, adspicit aequor:<br>     Actiacum populi Leucadiumque vocant. <br>hinc se Deucalion Pyrrhae succensus amore <br>     misit, et illaeso corpore pressit aquas. <br>nec mora, versus amor fugit lentissima mersi <br>     pectora; Deucalion igne levatus erat. <br>hanc legem locus ille tenet. pete protinus altam <br>     Leucada nec saxo desiluisse time!” <br>Ut monuit, cum voce abiit. ego frigida surgo<br>     nec lacrimas oculi continuere mei. <br>ibimus, o nymphe, monstrataque saxa petemus; <br>     sit procul insano victus amore timor.<br>quidquid erit, melius quam nunc erit. aura, subito — <br>     et mea non magnum corpora pondus habent.<br>tu quoque, mollis Amor, pinnas suppone cadenti, <br>     ne sim Leucadiae mortua crimen aquae.<br>inde chelyn Phoebo, communia munera, ponam, <br>     et sub ea versus unus et alter erunt:","st":"15"},{"sp":"N","t":"“grata lyram posui tibi, Phoebe, poetria Sappho:<br>     convenit illa mihi, convenit illa tibi.”<br>Cur tamen Actiacas miseram me mittis ad oras, <br>     cum profugum possis ipse referre pedem? <br>tu mihi Leucadia potes esse salubrior unda; <br>     et forma et meritis tu mihi Phoebus eris. <br>an potes, o scopulis undaque ferocior omni, <br>     si moriar, titulum mortis habere meae? <br>a quanto melius tecum mea pectora iungi, <br>     quam saxis poterant praecipitanda dari! <br>haec sunt illa, Phaon, quae tu laudare solebas<br>     visaque sunt totiens ingeniosa tibi. <br>nunc vellem facunda forem! dolor artibus obstat<br>     ingeniumque meis substitit omne malis. <br>non mihi respondent veteres in carmina vires; <br>     plectra dolore tacent muta, dolore lyra est. <br>Lesbides aequoreae, nupturaque nuptaque proles, <br>     Lesbides, Aeolia nomina dicta lyra, <br>Lesbides, infamem quae me fecistis amatae, <br>     desinite ad citharas turba venire meas! <br>abstulit omne Phaon, quod vobis ante placebat, <br>     me miseram! dixi quam modo paene: “meus.” <br>efficite ut redeat. vates quoque vestra redibit. <br>     ingenio vires ille dat, ille rapit. <br>Ecquid ago precibus pectusve agreste movetur,<br>     an riget et Zephyri verba caduca ferunt? <br>qui mea verba ferunt, vellem tua vela referrent; <br>     hoc te, si saperes, lente, decebat opus. <br>sive redis, puppique tuae votiva parantur <br>     munera, quid laceras pectora nostra mora? <br>solve ratem! Venus orta mari mare praestat amanti. <br>     aura dabit cursum — tu modo solve ratem! <br>ipse gubernator residens in puppe Cupido; <br>     ipse dabit tenera vela legetque manu. <br>sive iuvat longe fugisse Pelasgida Sappho<br>     (nec tamen invenies, cur ego digna fugi)<br>hoc saltem miserae crudelis epistula dicat, <br>     ut mihi Leucadiae fata petantur aquae.","st":"15"},{"sp":"HDR","t":"XVI","st":"16"},{"sp":"N","t":"Hanc tibi Priamides mitto, Ledaea, salutem, <br>     quae tribui sola te mihi dante potest. <br>eloquar, an flammae non est opus indice notae, <br>     et plus quam vellem, iam meus extat amor? <br>ille quidem lateat malim, dum tempora dentur <br>     laetitiae mixtos non habitura metus. <br>sed male dissimulo; quis enim celaverit ignem, <br>     lumine qui semper proditur ipse suo? <br>si tamen expectas, vocem quoque rebus ut addam: <br>     uror — habes animi nuntia verba mei.<br>parce, precor, fasso, nec vultu cetera duro <br>     perlege, sed formae conveniente tuae. <br>iamdudum gratum est, quod epistula nostra recepta <br>     spem facit, hoc recipi me quoque posse modo. <br>quae rata sit; nec te frustra promiserit, opto, <br>     hoc mihi quae suasit, mater Amoris, iter.<br>namque ego divino monitu — ne nescia pecces — <br>     advehor et coepto non leve numen adest. <br>praemia magna quidem, sed non indebita posco:<br>     pollicita est thalamo te Cytherea meo.<br>hac duce Sigeo dubias a litore feci <br>     longa Phereclea per freta puppe vias. <br>illa dedit faciles auras ventosque secundos — <br>     in mare nimirum ius habet orta mari. <br>perstet et ut pelagi, sic pectoris adiuvet aestum,<br>     deferat in portus et mea vota suos. <br>attulimus flammas, non hic invenimus, illas. <br>     hae mihi tam longae causa fuere viae.<br>nam neque tristis hiems neque nos huc appulit error; <br>     Taenaris est classi terra petita meae.<br>nec me crede fretum merces portante carina <br>     findere — quas habeo, di tueantur opes.<br>nec venio Graias veluti spectator ad urbes;<br>     oppida sunt regni divitiora mei. <br>te peto, quam pepigit lecto Venus aurea nostro; <br>     te prius optavi quam mihi nota fores.<br>ante tuos animo vidi quam lumine vultus; <br>     prima tulit vulnus nuntia fama tui. <br>nec tamen est mirum, si sicut oportuit arcu, <br>     missilibus telis eminus ictus amo.<br>sic placuit fatis; quae ne convellere temptes, <br>     accipe cum vera dicta relata fide. <br>matris adhuc utero partu remorante tenebar; <br>     iam gravidus iusto pondere venter erat. <br>illa sibi ingentem visa est sub imagine somni <br>     flammiferam pleno reddere ventre facem. <br>territa consurgit metuendaque noctis opacae <br>     visa seni Priamo, vatibus ille refert. <br>arsurum Paridis vates canit Ilion igni — <br>     pectoris, ut nunc est, fax fuit illa mei.<br>forma vigorque animi, quamvis de plebe videbar, <br>     indicium tectae nobilitatis erat. <br>est locus in mediis nemorosae vallibus Idae <br>     devius et piceis ilicibusque frequens, <br>qui nec ovis placidae nec amantis saxa capellae <br>     nec patulo tardae carpitur ore bovis;<br>hinc ego Dardaniae muros excelsaque tecta <br>     et freta prospiciens arbore nixus eram — <br>ecce, pedum pulsu visa est mihi terra moveri — <br>     vera loquar veri vix habitura fidem — <br>constitit ante oculos actus velocibus alis <br>     Atlantis magni Pleionesque nepos — <br>fas vidisse fuit, fas sit mihi visa referre — <br>     inque dei digitis aurea virga fuit.<br>tresque simul divae, Venus et cum Pallade Iuno, <br>     graminibus teneros inposuere pedes. <br>obstupui, gelidusque comas erexerat horror, <br>     cum mihi ‘pone metum!’ nuntius ales ait:<br>‘arbiter es formae; certamina siste dearum,<br>     vincere quae forma digna sit una duas.’<br>neve recusarem, verbis Iovis imperat et se <br>     protinus aetheria tollit in astra via. <br>mens mea convaluit, subitoque audacia venit<br>     nec timui vultu quamque notare meo. <br>vincere erant omnes dignae iudexque querebar <br>     non omnes causam vincere posse suam. <br>sed tamen ex illis iam tunc magis una placebat, <br>     hanc esse ut scires, unde movetur amor.<br>tantaque vincendi cura est; ingentibus ardent <br>     iudicium donis sollicitare meum.<br>regna Iovis coniunx, virtutem filia iactat; <br>     ipse potens dubito fortis an esse velim. <br>dulce Venus risit; ‘nec te, Pari, munera tangant <br>     utraque suspensi plena timoris,’ ait; <br>‘nos dabimus, quod ames, et pulchrae filia Ledae <br>     ibit in amplexus pulchrior illa tuos.’ <br>dixit, et ex aequo donis formaque probata <br>     victorem caelo rettulit illa pedem.<br>interea, credo, versis ad prospera fatis <br>     regius agnoscor per rata signa puer.<br>laeta domus nato per tempora longa recepto,","st":"16"},{"sp":"N","t":"addit et ad festos hunc quoque Troia diem. <br>utque ego te cupio, sic me cupiere puellae; <br>     multarum votum sola tenere potes. <br>nec tantum regum natae petiere ducumque, <br>     sed nymphis etiam curaque amorque fui. <br>quas super Oenonen facies mutarer in orbem<br>     nec Priamo est a te dignior ulla nurus. <br>sed mihi cunctarum subeunt fastidia, postquam <br>     coniugii spes est, Tyndari, facta tui.<br>te vigilans oculis, animo te nocte videbam, <br>     lumina cum placido victa sopore iacent. <br>quid facies praesens, quae nondum visa placebas? <br>     ardebam, quamvis hic procul ignis erat.<br>nec potui debere mihi spem longius istam, <br>     caerulea peterem quin mea vota via. <br>Troia caeduntur Phrygia pineta securi <br>     quaeque erat aequoreis utilis arbor aquis; <br>ardua proceris spoliantur Gargara silvis, <br>     innumerasque mihi longa dat Ida trabes.<br>fundatura citas flectuntur robora naves<br>     texitur et costis panda carina suis. <br>addimus antennas et vela sequentia malo<br>     accipit et pictos puppis adunca deos; <br>qua tamen ipse vehor, comitata Cupidine parvo<br>     sponsor coniugii stat dea picta sui.<br>imposita est factae postquam manus ultima classi, <br>     protinus Aegaeis ire lubebat aquis.<br>at pater et genetrix inhibent mea vota rogando <br>     propositumque pia voce morantur iter;<br>et soror effusis ut erat Cassandra capillis, <br>     cum vellent nostrae iam dare vela rates, <br>‘quo ruis?’ exclamat, ‘referes incendia tecum! <br>     quanta per has nescis flamma petatur aquas!’ <br>vera fuit vates; dictos invenimus ignes<br>     et ferus in molli pectore flagrat amor.<br>portubus egredior ventisque ferentibus usus <br>     applicor in terras, Oebali nympha, tuas. <br>excipit hospitio vir me tuus: hoc quoque factum <br>     non sine consilio numinibusque deum.<br>ille quidem ostendit, quidquid Lacedaemone tota <br>     ostendi dignum conspicuumque fuit; <br>sed mihi laudatam cupienti cernere formam <br>     lumina nil aliud quo caperentur erat. <br>ut vidi, obstipui praecordiaque intima sensi <br>     attonitus curis intumuisse novis. <br>his similes vultus, quantum reminiscor, habebat,<br>     venit in arbitrium cum Cytherea meum. <br>si tu venisses pariter certamen in illud, <br>     in dubium Veneris palma futura fuit.<br>magna quidem de te rumor praeconia fecit, <br>     nullaque de facie nescia terra tua est; <br>nec tibi par usquam Phrygia nec solis ab ortu <br>     inter formosas altera nomen habet! <br>credis et hoc nobis? — minor est tua gloria vero<br>     famaque de forma paene maligna tua est.<br>plus hic invenio, quam quod promiserat illa, <br>     et tua materia gloria victa sua est. <br>ergo arsit merito, qui noverat omnia, Theseus, <br>     et visa es tanto digna rapina viro,<br>more tuae gentis nitida dum nuda palaestra <br>     ludis et es nudis femina mixta viris. <br>quod rapuit, laudo; miror quod reddidit umquam. <br>     tam bona constanter praeda tenenda fuit. <br>ante recessisset caput hoc cervice cruenta, <br>     quam tu de thalamis abstraherere meis. <br>tene manus umquam nostrae dimittere vellent? <br>     tene meo paterer vivus abire sinu? <br>si reddenda fores, aliquid tamen ante tulissem<br>     nec Venus ex toto nostra fuisset iners.<br>vel mihi virginitas esset libata vel illud <br>     quod poterat salva virginitate rapi. <br>da modo te, quae sit Paridis constantia nosces:<br>     flamma rogi flammas finiet una meas. <br>praeposui regnis ego te, quae maxima quondam <br>     pollicita est nobis nupta sororque Iovis,<br>dumque tuo possem circumdare bracchia collo, <br>     contempta est virtus Pallade dante mihi. <br>nec piget aut umquam stulte legisse videbor; <br>     permanet in voto mens mea firma suo.<br>spem modo ne nostram fieri patiare caducam, <br>     deprecor, o tanto digna labore peti!<br>non ego coniugium generosae degener opto, <br>     nec mea, crede mihi, turpiter uxor eris. <br>Pliada, si quaeres, in nostra gente Iovemque <br>     invenies, medios ut taceamus avos.<br>sceptra parens Asiae, qua nulla beatior ora est, <br>     finibus inmensis vix obeunda, tenet. <br>innumeras urbes atque aurea tecta videbis<br>     quaeque suos dicas templa decere deos.<br>Ilion adspicies firmataque turribus altis <br>     moenia, Phoebeae structa canore lyrae. <br>quid tibi de turba narrem numeroque virorum?","st":"16"},{"sp":"N","t":"vix populum tellus sustinet illa suum. <br>occurrent denso tibi Troades agmine matres<br>     nec capient Phrygias atria nostra nurus. <br>o quotiens dices: ‘quam pauper Achaia nostra est!’ <br>     una domus quaevis urbis habebit opes. <br>nec mihi fas fuerit Sparten contemnere vestram:<br>     in qua tu nata es, terra beata mihi est.<br>parca sed est Sparte, tu cultu divite digna; <br>     ad talem formam non facit iste locus. <br>hanc faciem largis sine fine paratibus uti <br>     deliciisque decet luxuriare novis. <br>cum videas cultus nostra de gente virorum, <br>     qualem Dardanias credis habere nurus? <br>da modo te facilem nec dedignare maritum, <br>     rure Therapnaeo nata puella, Phrygem. <br>Phryx erat et nostro genitus de sanguine, qui nunc <br>     cum dis potando nectare miscet aquas.<br>Phryx erat Aurorae coniunx, tamen abstulit illum <br>     extremum noctis quae dea finit iter. <br>Phryx etiam Anchises, volucrum cui mater Amorum <br>     gaudet in Idaeis concubuisse iugis. <br>nec, puto, conlatis forma Menelaus et annis <br>     iudice te nobis anteferendus erit. <br>non dabimus certe socerum tibi clara fugantem <br>     lumina, qui trepidos a dape vertat equos; <br>nec Priamo pater est soceri de caede cruentus <br>     et qui Myrtoas crimine signat aquas;<br>nec proavo Stygia nostro captantur in unda <br>     poma, nec in mediis quaeritur umor aquis. <br>quid tamen hoc refert, si te tenet ortus ab illis?<br>     cogitur huic domui Iuppiter esse socer.<br>heu facinus! totis indignus noctibus ille <br>     te tenet amplexu perfruiturque tuo; <br>at mihi conspiceris posita vix denique mensa<br>     multaque quae laedant hoc quoque tempus habet. <br>hostibus eveniant convivia talia nostris, <br>     experior posito qualia saepe mero.<br>paenitet hospitii, cum me spectante lacertos <br>     imponit collo rusticus iste tuo. <br>rumpor et invideo — quid ni tamen omnia narrem? — <br>     membra superiecta cum tua veste fovet. <br>oscula cum vero coram non dura daretis, <br>     ante oculos posui pocula sumpta meos; <br>lumina demitto cum te tenet artius ille, <br>     crescit et invito lentus in ore cibus.<br>saepe dedi gemitus; et te, lasciva, notavi <br>     in gemitu risum non tenuisse meo.<br>saepe mero volui flammam compescere, at illa <br>     crevit, et ebrietas ignis in igne fuit.<br>multaque ne videam, versa cervice recumbo; <br>     sed revocas oculos protinus ipsa meos. <br>quid faciam, dubito; dolor est meus illa videre, <br>     sed dolor a facie maior abesse tua. <br>qua licet et possum, luctor celare furorem,<br>     sed tamen apparet dissimulatus amor. <br>nec tibi verba damus; sentis mea vulnera, sentis;<br>     atque utinam soli sint ea nota tibi.<br>a, quotiens lacrimis venientibus ora reflexi, <br>     ne causam fletus quaereret ille mei.<br>a, quotiens aliquem narravi potus amorem, <br>     ad vulnus referens singula verba tuos, <br>indiciumque mei ficto sub nomine feci;<br>     ille ego, si nescis, verus amator eram. <br>quin etiam ut possem verbis petulantius uti, <br>     non semel ebrietas est simulata mihi. <br>Prodita sunt, memini, tunica tua pectora laxa <br>     atque oculis aditum nuda dedere meis<br>pectora vel puris nivibus vel lacte tuamve <br>     complexo matrem candidiora Iove. <br>dum stupeo visis — nam pocula forte tenebam — <br>     tortilis a digitis excidit ansa meis. <br>oscula si natae dederas, ego protinus illa <br>     Hermiones tenero laetus ab ore tuli.<br>et modo cantabam veteres resupinus amores<br>     et modo per nutum signa tegenda dabam. <br>et comitum primas Clymenen Aethramque, tuarum <br>     ausus sum blandis nuper adire sonis;<br>quae mihi non aliud, quam formidare locutae <br>     orantis medias deseruere preces. <br>di facerent, pretium magni certaminis esses, <br>     teque suo posset victor habere toro,<br>ut tulit Hippomenes Schoeneida praemia cursus, <br>     venit ut in Phrygios Hippodamia sinus, <br>ut ferus Alcides Acheloia cornua fregit, <br>     dum petit amplexus, Deianira, tuos. <br>nostra per has leges audacia fortiter isset<br>     teque mei scires esse laboris opus.<br>nunc mihi nil superest nisi te, formosa, precari<br>     amplectique tuos, si patiare, pedes. <br>o decus, o praesens geminorum gloria fratrum, <br>     o Iove digna viro, ni Iove nata fores, <br>aut ego Sigeos repetam te coniuge portus","st":"16"},{"sp":"N","t":"aut hic Taenaria contegar exul humo! <br>non mea sunt summa leviter destricta sagitta <br>     pectora; descendit vulnus ad ossa meum! <br>hoc mihi, nam repeto, fore ut a caeleste sagitta <br>     figar, erat verax vaticinata soror.<br>parce datum fatis, Helene, contemnere amorem — <br>     sic habeas faciles in tua vota deos.<br>multa quidem subeunt; sed coram ut plura loquamur, <br>     excipe me lecto nocte silente tuo.<br>an pudet et metuis Venerem temerare maritam <br>     castaque legitimi fallere iura tori? <br>a, nimium simplex Helene, ne rustica dicam, <br>     hanc faciem culpa posse carere putas? <br>aut faciem mutes aut sis non dura, necesse est; <br>     lis est cum forma magna pudicitiae.<br>Iuppiter his gaudet, gaudet Venus aurea furtis; <br>     haec tibi nempe patrem furta dedere Iovem. <br>vix fieri, si sunt vires in semine amorum, <br>     et Iovis et Ledae filia casta potes. <br>casta tamen tum sis, cum te mea Troia tenebit, <br>     et tua sim quaeso crimina solus ego. <br>nunc ea peccemus quae corriget hora iugalis, <br>     si modo promisit non mihi vana Venus.<br>sed tibi et hoc suadet rebus, non voce, maritus, <br>     neve sui furtis hospitis obstet, abest.<br>non habuit tempus, quo Cresia regna videret<br>     aptius — o mira calliditate virum! <br>‘res, et ut Idaei mando tibi,’ dixit iturus, <br>     ‘curam pro nobis hospitis, uxor, agas.’ <br>neglegis absentis, testor, mandata mariti;<br>     cura tibi non est hospitis ulla tui. <br>huncine tu speras hominem sine pectore dotes <br>     posse satis formae, Tyndari, nosse tuae? <br>falleris: ignorat, nec, si bona magna putaret, <br>     quae tenet, externo crederet illa viro.<br>ut te nec mea vox nec te meus incitet ardor, <br>     cogimur ipsius commoditate frui:<br>aut erimus stulti, sic ut superemus et ipsum, <br>     si tam securum tempus abibit iners.<br>paene suis ad te manibus deducit amantem; <br>     utere mandantis simplicitate viri! <br>sola iaces viduo tam longa nocte cubili; <br>     in viduo iaceo solus et ipse toro. <br>te mihi meque tibi communia gaudia iungant; <br>     candidior medio nox erit illa die.<br>tunc ego iurabo quaevis tibi numina meque <br>     adstringam verbis in sacra vestra meis; <br>tunc ego, si non est fallax fiducia nostri, <br>     efficiam praesens, ut mea regna petas. <br>si pudet et metuis ne me videare secuta, <br>     ipse reus sine te criminis huius ero.<br>nam sequar Aegidae factum fratrumque tuorum;<br>     exemplo tangi non propiore potes. <br>te rapuit Theseus, geminas Leucippidas illi; <br>     quartus in exemplis adnumerabor ego.<br>Troia classis adest armis instructa virisque; <br>     iam facient celeres remus et aura vias. <br>ibis Dardanias ingens regina per urbes, <br>     teque novam credet vulgus adesse deam, <br>quaque feres gressus, adolebunt cinnama flammae, <br>     caesaque sanguineam victima planget humum. <br>dona pater fratresque et cum genetrice sorores <br>     Iliadesque omnes totaque Troia dabit. <br>ei mihi! pars a me vix dicitur ulla futuri. <br>     plura feres quam quae littera nostra refert.<br>nec tu rapta time, ne nos fera bella sequantur, <br>     concitet et vires Graecia magna suas. <br>tot prius abductis ecqua est repetita per arma? <br>     crede mihi, vanos res habet ista metus. <br>nomine ceperunt Aquilonis Erechthida Thraces<br>     et tuta a bello Bistonis ora fuit.<br>Phasida puppe nova vexit Pagasaeus Iason, <br>     laesa neque est Colcha Thessala terra manu. <br>te quoque qui rapuit, rapuit Minoida Theseus; <br>     nulla tamen Minos Cretas ad arma vocat.<br>terror in his ipso maior solet esse periclo;<br>     quaeque timere libet, pertimuisse pudet. <br>finge tamen, si vis, ingens consurgere bellum:<br>     et mihi sunt vires, et mea tela nocent. <br>nec minor est Asiae quam vestrae copia terrae:<br>     illa viris dives, dives abundat equis. <br>nec plus Atrides animi Menelaus habebit <br>     quam Paris aut armis anteferendus erit. <br>paene puer caesis abducta armenta recepi<br>     hostibus et causam nominis inde tuli.<br>paene puer iuvenes vario certamine vici, <br>     in quibus Ilioneus Deiphobusque fuit.<br>neve putes, non me nisi comminus esse timendum, <br>     figitur in iusso nostra sagitta loco. <br>num potes haec illi primae dare facta iuventae,<br>     instruere Atriden num potes arte mea? <br>omnia si dederis, numquid dabis Hectora fratrem?","st":"16"},{"sp":"N","t":"unus is innumeri militis instar erit.<br>quid valeam nescis et te mea robora fallunt; <br>     ignoras cui sis nupta futura viro.<br>aut igitur nullo belli repetere tumultu, <br>     aut cedent Marti Dorica castra meo. <br>nec tamen indigner pro tanta sumere ferrum <br>     coniuge; certamen praemia magna movent. <br>tu quoque, si de te totus contenderit orbis, <br>     nomen ab aeterna posteritate feres <br>spe modo non timida dis hinc egressa secundis<br>     exige cum plena munera pacta fide.","st":"16"},{"sp":"HDR","t":"XVII","st":"17"},{"sp":"N","t":"Si mihi quae legi, Pari, non legisse liceret,<br>     servarem numeros sicut et ante probae. <br>Nunc oculos tua cum violarit epistula nostros, <br>     non rescribendi gloria visa levis. <br>ausus es hospitii temeratis advena sacris <br>     legitimam nuptae sollicitare fidem! <br>scilicet idcirco ventosa per aequora vectum <br>     excepit portu Taenaris ora suo<br>nec tibi, diversa quamvis e gente venires, <br>     oppositas habuit regia nostra fores, <br>esset ut officii merces iniuria tanti?<br>     qui sic intrabas, hospes an hostis eras?<br>nec dubito quin haec, cum sit tam iusta, vocetur <br>     rustica iudicio nostra querela tuo. <br>rustica sim sane, dum non oblita pudoris<br>     dumque tenor vitae sit sine labe meae. <br>si non est ficto tristis mihi vultus in ore<br>     nec sedeo duris torva superciliis, <br>fama tamen clara est, et adhuc sine crimine lusi<br>     et laudem de me nullus adulter habet. <br>quo magis admiror, quae sit fiducia coepti<br>     spemque tori dederit quae tibi causa mei.<br>an quia vim nobis Neptunius attulit heros, <br>     rapta semel videor bis quoque digna rapi? <br>crimen erat nostrum, si delenita fuissem; <br>     cum sim rapta, meum quid nisi nolle fuit? <br>non tamen e facto fructum tulit ille petitum; <br>     excepto redii passa timore nihil. <br>oscula luctanti tantummodo pauca protervus <br>     abstulit: ulterius nil habet ille mei. <br>quae tua nequitia est, non his contenta fuisset.<br>     di melius! similis non fuit ille tui.<br>reddidit intactam minuitque modestia crimen<br>     et iuvenem facti paenituisse patet.<br>Thesea paenituit, Paris ut succederet illi, <br>     ne quando nomen non sit in ore meum? <br>nec tamen irascor — quis enim succenset amanti? — <br>     si modo, quem praefers, non simulatur amor. <br>hoc quoque enim dubito, non quod fiducia desit, <br>     aut mea sit facies non bene nota mihi,<br>sed quia credulitas damno solet esse puellis<br>     verbaque dicuntur vestra carere fide.<br>at peccant aliae, matronaque rara pudica est. <br>     quis prohibet raris nomen inesse meum? <br>nam mea quod visa est tibi mater idonea, cuius <br>     exemplo flecti me quoque posse putes, <br>matris in admisso falsa sub imagine lusae <br>     error inest; pluma tectus adulter erat. <br>nil ego, si peccem, possum nescisse; nec ullus <br>     error qui facti crimen obumbret erit. <br>illa bene erravit vitiumque auctore redemit. <br>     felix in culpa quo Iove dicar ego?<br>et genus et proavos et regia nomina iactas;<br>     clara satis domus haec nobilitate sua est. <br>Iuppiter ut soceri proavus taceatur et omne <br>     Tantalidae Pelopis Tyndareique decus;<br>dat mihi Leda Iovem cygno decepta parentem, <br>     quae falsam gremio credula fovit avem. <br>i nunc et Phrygiae late primordia gentis <br>     cumque suo Priamum Laumedonte refer! <br>quos ego suspicio; sed qui tibi gloria magna est <br>     quintus, is a nostro nomine primus erit.<br>sceptra tuae quamvis rear esse potentia terrae, <br>     non tamen haec illis esse minora puto. <br>si iam divitiis locus hic numeroque virorum <br>     vincitur, at certe barbara terra tua est. <br>munera tanta quidem promittit epistula dives <br>     ut possint ipsas illa movere deas.<br>sed si iam vellem fines transire pudoris, <br>     tu melior culpae causa futurus eras. <br>aut ego perpetuo famam sine labe tenebo<br>     aut ego te potius quam tua dona sequar.<br>utque ea non sperno, sic acceptissima semper <br>     munera sunt, auctor quae pretiosa facit. <br>plus multo est, quod amas, quod sum tibi causa laboris, <br>     quod per tam longas spes tua venit aquas.<br>illa quoque, adposita quae nunc facis, improbe, mensa, <br>     quamvis experiar dissimulare, noto — <br>cum modo me spectas oculis, lascive, protervis, <br>     quos vix instantes lumina nostra ferunt, <br>et modo suspiras, modo pocula proxima nobis <br>     sumis, quaque bibi, tu quoque parte bibis.<br>a, quotiens digitis, quotiens ego tecta notavi <br>     signa supercilio paene loquente dari! <br>et saepe extimui ne vir meus illa videret, <br>     non satis occultis erubuique notis.<br>saepe vel exiguo vel nullo murmure dixi: <br>     ‘nil pudet hunc!’ nec vox haec mea falsa fuit. <br>orbe quoque in mensae legi sub nomine nostro, <br>     quod deducta mero littera fecit, ‘amo.’ <br>credere me tamen hoc oculo renuente negavi.","st":"17"},{"sp":"N","t":"ei mihi, iam didici sic ego posse loqui!<br>his ego blanditiis, si peccatura fuissem, <br>     flecterer; his poterant pectora nostra capi. <br>est quoque, confiteor, facies tibi rara potestque <br>     velle sub amplexus ire puella tuos.<br>altera sed potius felix sine crimine fiat, <br>     quam cadat externo noster amore pudor. <br>disce modo exemplo formosis posse carere; <br>     est virtus placitis abstinuisse bonis. <br>quam multos credis iuvenes optare, quod optas?<br>     qui sapiant, oculos an Paris unus habes?<br>non tu plus cernis, sed plus temerarius audes;<br>     nec tibi plus cordis sed minus oris, adest.<br>tunc ego te vellem celeri venisse carina, <br>     cum mea virginitas mille petita procis.<br>si te vidissem, primus de mille fuisses;<br>     iudicio veniam vir dabit ipse meo. <br>ad possessa venis praeceptaque gaudia serus; <br>     spes tua lenta fuit; quod petis, alter habet. <br>ut tamen optarim fieri tua Troica coniunx, <br>     invitam sic me nec Menelaus habet.<br>desine molle, precor, verbis convellere pectus<br>     neve mihi, quam te dicis amare, noce; <br>sed sine quam tribuit sortem fortuna tueri<br>     nec spolium nostri turpe pudoris habe.<br>at Venus hoc pacta est, et in altae vallibus Idae <br>     tres tibi se nudas exhibuere deae;<br>unaque cum regnum, belli daret altera laudem<br>     ‘Tyndaridis coniunx,’ tertia dixit, ‘eris!’ <br>credere vix equidem caelestia corpora possum <br>     arbitrio formam supposuisse tuo;<br>utque sit hoc verum, certe pars altera ficta est, <br>     iudicii pretium qua data dicor ego. <br>non est tanta mihi fiducia corporis, ut me <br>     maxima teste dea dona fuisse putem. <br>contenta est oculis hominum mea forma probari; <br>     laudatrix Venus est invidiosa mihi. <br>sed nihil infirmo; faveo quoque laudibus istis;<br>     nam, mens, vox quare, quod cupit esse, neget? <br>nec tu succense nimium mihi creditus aegre; <br>     tarda solet magnis rebus inesse fides.<br>prima mea est igitur Veneri placuisse voluptas;<br>     proxima, me visam praemia summa tibi, <br>nec te Palladios nec te Iunonis honores <br>     auditis Helenae praeposuisse bonis. <br>ergo ego sum virtus, ego sum tibi nobile regnum?<br>     ferrea sim, si non hoc ego pectus amem. <br>ferrea, crede mihi, non sum; sed amare repugno <br>     illum, quem fieri vix puto posse meum. <br>quid bibulum curvo proscindere litus aratro<br>     spemque sequi coner quam locus ipse negat?<br>sum rudis ad Veneris furtum nullaque fidelem — <br>     di mihi sunt testes! — lusimus arte virum!<br>nunc quoque, quod tacito mando mea verba libello, <br>     fungitur officio littera nostra novo. <br>felices, quibus usus adest! ego nescia rerum <br>     difficilem culpae suspicor esse viam. <br>ipse malo metus est; iam nunc confundor et omnes <br>     in nostris oculos vultibus esse reor. <br>nec reor hoc falso; sensi mala murmura vulgi<br>     et quasdam voces rettulit Aethra mihi.<br>at tu dissimula, nisi si desistere mavis.<br>     sed cur desistas? dissimulare potes. <br>lude, sed occulte! maior, non maxima, nobis <br>     est data libertas, quod Menelaus abest. <br>ille quidem procul est, ita re cogente, profectus; <br>     magna fuit subitae iustaque causa viae;<br>aut mihi sic visum est. ego, cum dubitaret an iret, <br>     ‘quam primum,’ dixi, ‘fac rediturus eas!’ <br>omine laetatus dedit oscula, ‘resque domusque <br>     et tibi sit curae Troicus hospes,’ ait.<br>vix tenui risum, quem dum conpescere luctor, <br>     nil illi potui dicere praeter ‘erit.’ <br>uela quidem Creten ventis dedit ille secundis; <br>     sed tu non ideo cuncta licere puta! <br>sic meus hinc vir abest ut me custodiat absens.<br>     an nescis longas regibus esse manus? <br>forma quoque est oneri; nam quo constantius ore <br>     laudamur vestro, iustius ille timet. <br>quae iuvat, ut nunc est, eadem mihi gloria damno est, <br>     et melius famae verba dedisse fuit.<br>nec quod abest hic me tecum mirare relictam;<br>     moribus et vitae credidit ille meae. <br>de facie metuit, vitae confidit, et illum <br>     securum probitas, forma timere facit. <br>tempora ne pereant ultro data praecipis, utque <br>     simplicis utamur commoditate viri. <br>et libet et timeo, nec adhuc exacta voluntas <br>     est satis; in dubio pectora nostra labant. <br>et vir abest nobis et tu sine coniuge dormis,","st":"17"},{"sp":"N","t":"inque vicem tua me, te mea forma capit;<br>et longae noctes et iam sermone coimus <br>     et tu, me miseram! blandus, et una domus. <br>et peream, si non invitant omnia culpam; <br>     nescio quo tardor sed tamen ipsa metu.<br>quod male persuades, utinam bene cogere posses! <br>     vi mea rusticitas excutienda fuit. <br>utilis interdum est ipsis iniuria passis. <br>     sic certe felix esse coacta forem. <br>dum novus est, potius coepto pugnemus amori! <br>     flamma recens parva sparsa resedit aqua.<br>certus in hospitibus non est amor; errat, ut ipsi, <br>     cumque nihil speres firmius esse, fugit. <br>Hypsipyle testis, testis Minoia virgo est;<br>     in non exhibitis utraque lusa toris. <br>tu quoque dilectam multos, infide, per annos <br>     diceris Oenonen destituisse tuam. <br>nec tamen ipse negas; et nobis omnia de te <br>     quaerere, si nescis, maxima cura fuit. <br>adde quod, ut cupias constans in amore manere, <br>     non potes. expediunt iam tua vela Phryges;<br>dum loqueris mecum, dum nox sperata paratur, <br>     qui ferat in patriam, iam tibi ventus erit. <br>cursibus in mediis novitatis plena relinques <br>     gaudia; cum ventis noster abibit amor. <br>an sequar, ut suades, laudataque Pergama visam <br>     pronurus et magni Laumedontis ero? <br>non ita contemno volucris praeconia famae, <br>     ut probris terras impleat illa meis. <br>quid de me poterit Sparte, quid Achaia tota, <br>     quid gentes Asiae, quid tua Troia loqui?<br>quid Priamus de me, Priami quid sentiet uxor<br>     totque tui fratres Dardanidesque nurus? <br>tu quoque qui poteris fore me sperare fidelem<br>     et non exemplis anxius esse tuis? <br>quicumque Iliacos intraverit advena portus, <br>     is tibi solliciti causa timoris erit. <br>ipse mihi quotiens iratus ‘adultera!’ dices, <br>     oblitus nostro crimen inesse tuum! <br>delicti fies idem reprehensor et auctor. <br>     terra, precor, vultus obruat ante meos!<br>at fruar Iliacis opibus cultuque beato<br>     donaque promissis uberiora feram:<br>purpura nempe mihi pretiosaque texta dabuntur, <br>     congestoque auri pondere dives ero! <br>da veniam fassae! non sunt tua munera tanti; <br>     nescio quo tellus me tenet ista modo. <br>quis mihi, si laedar, Phrygiis succurret in oris? <br>     unde petam fratres, unde parentis opem? <br>omnia Medeae fallax promisit Iason:<br>     pulsa est Aesonia num minus illa domo?<br>non erat Aeetes, ad quem despecta rediret, <br>     non Idyia parens Chalciopeve soror. <br>tale nihil timeo, sed nec Medea timebat;<br>     fallitur augurio spes bona saepe suo. <br>omnibus invenies, quae nunc iactantur in alto, <br>     navibus a portu lene fuisse fretum. <br>fax quoque me terret, quam se peperisse cruentam <br>     ante diem partus est tua visa parens; <br>et vatum timeo monitus, quos igne Pelasgo <br>     Ilion arsurum praemonuisse ferunt.<br>utque favet Cytherea tibi, quia vicit habetque <br>     parta per arbitrium bina tropaea tuum, <br>sic illas vereor, quae, si tua gloria vera est, <br>     iudice te causam non tenuere duae;<br>nec dubito, quin te si prosequar arma parentur. <br>     ibit per gladios, ei mihi! noster amor. <br>an fera Centauris indicere bella coegit <br>     Atracis Haemonios Hippodamia viros:<br>tu fore tam iusta lentum Menelaon in ira <br>     et geminos fratres Tyndareumque putas?<br>quod bene te iactes et fortia facta loquaris, <br>     a verbis facies dissidet ista suis. <br>apta magis Veneri quam sunt tua corpora Marti. <br>     bella gerant fortes, tu, Pari, semper ama! <br>Hectora, quem laudas, pro te pugnare iubeto; <br>     militia est operis altera digna tuis. <br>his ego, si saperem pauloque audacior essem, <br>     uterer; utetur, siqua puella sapit.<br>aut ego deposito sapiam fortasse pudore <br>     et dabo cunctatas tempore victa manus.<br>quod petis, ut furtim praesentes ista loquamur, <br>     scimus, quid captes conloquiumque voces; <br>sed nimium properas, et adhuc tua messis in herba est. <br>     haec mora sit voto forsan amica tuo. <br>hactenus; arcanum furtivae conscia mentis <br>     littera iam lasso pollice sistat opus. <br>cetera per socias Clymenen Aethramque loquamur, <br>     quae mihi sunt comites consiliumque duae.","st":"17"},{"sp":"HDR","t":"XVIII","st":"18"},{"sp":"N","t":"Quam cuperem solitas, Hero, tibi ferre per undas<br>     accipe Leandri, dum venit ipse, manum. <br>Mittit Abydenus, quam mallet ferre, salutem, <br>     si cadat unda maris, Sesti puella, tibi. <br>si mihi di faciles si sunt in amore secundi, <br>     invitis oculis haec mea verba leges. <br>sed non sunt faciles; nam cur mea vota morantur <br>     currere me nota nec patiuntur aqua? <br>ipsa vides caelum pice nigrius et freta ventis <br>     turbida perque cavas vix adeunda rates. <br>unus, et hic audax, a quo tibi littera nostra <br>     redditur, e portu navita movit iter;<br>adscensurus eram, nisi quod cum vincula prorae <br>     solveret, in speculis omnis Abydos erat. <br>non poteram celare meos, velut ante, parentes, <br>     quemque tegi volumus, non latuisset amor. <br>protinus haec scribens, ‘felix, i, littera!’ dixi, <br>     ‘iam tibi formosam porriget illa manum. <br>forsitan admotis etiam tangere labellis, <br>     rumpere dum niveo vincula dente volet.’ <br>talibus exiguo dictis mihi murmure verbis, <br>     cetera cum charta dextra locuta mea est.<br>at quanto mallem, quam scriberet, illa nataret, <br>     meque per adsuetas sedula ferret aquas! <br>aptior illa quidem placido dare verbera ponto; <br>     est tamen et sensus apta ministra mei.<br>septima nox agitur, spatium mihi longius anno, <br>     sollicitum raucis ut mare fervet aquis. <br>his ego si vidi mulcentem pectora somnum <br>     noctibus, insani sit mora longa freti. <br>rupe sedens aliqua specto tua litora tristis <br>     et, quo non possum corpore, mente feror.<br>lumina quin etiam summa vigilantia turre <br>     aut videt aut acies nostra videre putat. <br>ter mihi deposita est in sicca vestis harena; <br>     ter grave temptavi carpere nudus iter:<br>obstitit inceptis tumidum iuvenalibus aequor<br>     mersit et adversis ora natantis aquis. <br>at tu, de rapidis inmansuetissime ventis, <br>     quid mecum certa proelia mente geris? <br>in me, si nescis, Borea, non aequora, saevis.<br>     quid faceres, esset ni tibi notus amor?<br>tam gelidus quod sis, num te tamen, improbe, quondam <br>     ignibus Actaeis incaluisse negas? <br>gaudia rapturo siquis tibi claudere vellet <br>     aerios aditus, quo paterere modo? <br>parce, precor, facilemque move moderatius auram! <br>     imperet Hippotades sic tibi triste nihil! <br>vana peto; precibusque meis obmurmurat ipse <br>     quasque quatit, nulla parte coercet aquas. <br>nunc daret audaces utinam mihi Daedalus alas!<br>     Icarium quamvis hinc prope litus abest.<br>quidquid erit, patiar, liceat modo corpus in auras <br>     tollere, quod dubia saepe pependit aqua.<br>interea, dum cuncta negant ventique fretumque, <br>     mente agito furti tempora prima mei. <br>nox erat incipiens — namque est meminisse voluptas — <br>     cum foribus patriis egrediebar amans. <br>nec mora, deposito pariter cum veste timore <br>     iactabam liquido bracchia lenta mari. <br>luna fere tremulum praebebat lumen eunti <br>     ut comes in nostras officiosa vias.<br>hanc ego suspiciens, ‘faveas, dea candida,’ dixi, <br>     ‘et subeant animo Latmia saxa tuo.<br>non sinit Endymion te pectoris esse severi;<br>     flecte, precor, vultus ad mea furta tuos! <br>tu dea mortalem caelo delapsa petebas; <br>     vera loqui liceat! — quam sequor ipsa dea est. <br>neu referam mores caelesti pectore dignos, <br>     forma nisi in veras non cadit illa deas. <br>a Veneris facie non est prior ulla tuaque; <br>     neve meis credas vocibus, ipsa vide!<br>quantum, cum fulges radiis argentea puris, <br>     concedunt flammis sidera cuncta tuis, <br>tanto formosis formosior omnibus illa est;<br>     si dubitas, caecum, Cynthia, lumen habes.’ <br>haec ego vel certe non his diversa locutus <br>     per mihi cedentes sponte ferebar aquas. <br>unda repercussae radiabat imagine lunae<br>     et nitor in tacita nocte diurnus erat.<br>nullaque vox usquam, nullum veniebat ad aures <br>     praeter dimotae corpore murmur aquae.<br>Alcyones solae memores Ceycis amati<br>     nescio quid visae sunt mihi dulce queri. <br>iamque fatigatis umero sub utroque lacertis <br>     fortiter in summas erigor altus aquas. <br>ut procul adspexi lumen, ‘meus ignis in illo est: <br>     illa meum,’ dixi, ‘litora lumen habent.’ <br>et subito lassis vires rediere lacertis, <br>     visaque quam fuerat mollior unda mihi.","st":"18"},{"sp":"N","t":"frigora ne possim gelidi sentire profundi, <br>     qui calet in cupido pectore, praestat amor.<br>quo magis accedo propioraque litora fiunt, <br>     quoque minus restat, plus libet ire mihi. <br>cum vero possum cerni quoque, protinus addis <br>     spectatrix animos, ut valeamque facis. <br>nunc etiam nando dominae placuisse laboro, <br>     atque oculis iacto bracchia nostra tuis. <br>te tua vix prohibet nutrix descendere in altum; <br>     hoc quoque enim vidi, nec mihi verba dabas. <br>nec tamen effecit, quamvis retinebat euntem, <br>     ne fieret prima pes tuus udus aqua.<br>excipis amplexu feliciaque oscula iungis — <br>     oscula, di magni, trans mare digna peti!<br>eque tuis demptos umeris mihi tradis amictus<br>     et madidam siccas aequoris imbre comam. <br>cetera nox et nos et turris conscia novit<br>     quodque mihi lumen per vada monstrat iter. <br>non magis illius numerari gaudia noctis <br>     Hellespontiaci quam maris alga potest; <br>quo brevius spatium nobis ad furta dabatur, <br>     hoc magis est cautum, ne foret illud iners.<br>iamque fugatura Tithoni coniuge noctem <br>     praevius Aurorae Lucifer ortus erat;<br>oscula congerimus properata sine ordine raptim <br>     et querimur parvas noctibus esse moras. <br>atque ita cunctatus monitu nutricis amaro <br>     frigida deserta litora turre peto. <br>digredimur flentes repetoque ego virginis aequor <br>     respiciens dominam, dum licet, usque meam. <br>siqua fides vero est, veniens hinc esse natator, <br>     cum redeo, videor naufragus esse mihi.<br>hoc quoque, si credes: ad te via prona videtur; <br>     a te cum redeo, clivus inertis aquae. <br>invitus repeto patriam; quis credere possit? <br>     invitus certe nunc moror urbe mea. <br>ei mihi! cur animis iuncti secernimur undis<br>     unaque mens, tellus non habet una duos? <br>vel tua me Sestus, vel te mea sumat Abydos; <br>     tam tua terra mihi, quam tibi nostra placet. <br>cur ego confundor, quotiens confunditur aequor? <br>     cur mihi causa levis, ventus, obesse potest?<br>iam nostros curvi norunt delphines amores<br>     ignotum nec me piscibus esse reor. <br>iam patet attritus solitarum limes aquarum, <br>     non aliter multa quam via pressa rota. <br>quod mihi non esset nisi sic iter, ante querebar; <br>     at nunc per ventos hoc quoque deesse queror. <br>fluctibus immodicis Athamantidos aequora canent<br>     vixque manet portu tuta carina suo; <br>hoc mare, cum primum de virgine nomina mersa, <br>     quae tenet, est nanctum, tale fuisse puto.<br>est satis amissa locus hic infamis ab Helle est, <br>     utque mihi parcat, nomine crimen habet.<br>invideo Phrixo, quem per freta tristia tutum <br>     aurea lanigero vellere vexit ovis; <br>nec tamen officium pecoris navisve requiro, <br>     dummodo, quas findam corpore, dentur aquae. <br>arte egeo nulla; fiat modo copia nandi, <br>     idem navigium, navita, vector ero<br>nec sequor aut Helicen aut qua Tyros utitur Arcton; <br>     publica non curat sidera noster amor.<br>Andromedan alius spectet claramque Coronam<br>     quaeque micat gelido Parrhasis Ursa polo; <br>at mihi quod Perseus et cum Iove Liber amarunt, <br>     indicium dubiae non placet esse viae. <br>est aliud lumen, multo mihi certius istis, <br>     non errat tenebris quo duce noster amor; <br>hoc ego dum spectem, Colchos et in ultima Ponti<br>     quaque viam fecit Thessala pinus eam<br>et iuvenem possim superare Palaemona nando <br>     morsaque quem subito reddidit herba deum.<br>saepe per adsiduos languent mea bracchia motus, <br>     vixque per immensas fessa trahuntur aquas. <br>his ego cum dixi: ‘pretium non vile laboris, <br>     iam dominae vobis colla tenenda dabo,’ <br>protinus illa valent, atque ad sua praemia tendunt, <br>     ut celer Eleo carcere missus equus. <br>ipse meos igitur servo, quibus uror, amores <br>     teque, magis caelo digna puella, sequor. <br>digna quidem caelo, sed adhuc tellure morare, <br>     aut dic, ad superos et mihi qua sit iter!<br>hic es et exigue misero contingis amanti, <br>     cumque mea fiunt turbida mente freta. <br>quid mihi, quod lato non separor aequore, prodest? <br>     num minus haec nobis tam brevis obstat aqua? <br>an malim, dubito, toto procul orbe remotus <br>     cum domina longe spem quoque habere meam. <br>quo propius nunc es, flamma propiore calesco<br>     et res non semper, spes mihi semper adest.","st":"18"},{"sp":"N","t":"paene manu quod amo, tanta est vicinia, tango; <br>     saepe sed, heu, lacrimas hoc mihi ‘paene’ movet!<br>velle quid est aliud fugientia prendere poma <br>     spemque suo refugi fluminis ore sequi? <br>ergo ego te numquam, nisi cum volet unda, tenebo<br>     et me felicem nulla videbit hiems, <br>cumque minus firmum nil sit quam ventus et unda, <br>     in ventis et aqua spes mea semper erit? <br>aestus adhuc tamen est. quid, cum mihi laeserit aequor <br>     Plias et Arctophylax Oleniumque pecus? <br>aut ego non novi, quam sim temerarius, aut me <br>     in freta non cautus tum quoque mittet Amor;<br>neve putes id me, quod abest, promittere, tempus, <br>     pignora polliciti non tibi tarda dabo. <br>sit tumidum paucis etiam nunc noctibus aequor;<br>     ire per invitas experiemur aquas.<br>aut mihi continget felix audacia salvo<br>     aut mors solliciti finis amoris erit.<br>optabo tamen ut partis expellar in illas<br>     et teneant portus naufraga membra tuos.<br>flebis enim tactuque meum dignabere corpus <br>     et ‘mortis,’ dices, ‘huic ego causa fui!’<br>scilicet interitus offenderis omine nostri, <br>     litteraque invisa est hac mea parte tibi. <br>desino; parce queri. sed ut et mare finiat iram, <br>     accedant, quaeso, fac tua vota meis. <br>pace brevi nobis opus est, dum transferor isto; <br>     cum tua contigero litora, perstet hiems!<br>istic est aptum nostrae navale carinae<br>     et melius nulla stat mea puppis aqua. <br>illic me claudat Boreas, ubi dulce morari est;<br>     tunc piger ad nandum, tunc ego cautus ero<br>nec faciam surdis convicia fluctibus ulla<br>     triste nataturo nec querar esse fretum. <br>me pariter venti teneant tenerique lacerti, <br>     per causas istic impediarque duas<br>cum patietur hiems, remis ego corporis utar; <br>     lumen in adspectu tu modo semper habe.<br>interea pro me pernoctet epistula tecum, <br>     quam precor ut minima prosequar ipse mora.","st":"18"},{"sp":"HDR","t":"XIX","st":"19"},{"sp":"N","t":"Quam mihi misisti verbis, Leandre, salutem <br>     ut possim missam rebus habere, veni! <br>longa mora est nobis omnis, quae gaudia differt. <br>     da veniam fassae; non patienter amo.<br>urimur igne pari, sed sum tibi viribus impar: <br>     fortius ingenium suspicor esse viris. <br>ut corpus, teneris ita mens infirma puellis;<br>     deficiam, parvi temporis adde moram.<br>vos modo venando, modo rus geniale colendo <br>     ponitis in varia tempora longa mora.<br>aut fora vos retinent aut unctae dona palaestrae<br>     flectitis aut freno colla sequacis equi; <br>nunc volucrem laqueo, nunc piscem ducitis hamo,<br>     diluitur posito serior hora mero. <br>his mihi summotae, vel si minus acriter urar, <br>     quod faciam, superest praeter amare nihil. <br>quod superest facio, teque, o mea sola voluptas, <br>     plus quoque, quam reddi quod mihi possit, amo.<br>aut ego cum cana de te nutrice susurro, <br>     quaeque tuum, miror, causa moretur iter;<br>aut mare prospiciens odioso concita vento <br>     corripio verbis aequora paene tuis; <br>aut ubi saevitiae paulum gravis unda remisit, <br>     posse quidem, sed te nolle venire, queror; <br>dumque queror lacrimae per amantia lumina manant, <br>     pollice quas tremulo conscia siccat anus. <br>saepe tui specto si sint in litore passus, <br>     impositas tamquam servet harena notas; <br>utque rogem de te et scribam tibi, siquis Abydo <br>     venerit aut, quaero, siquis Abydon eat.<br>quid referam, quotiens dem vestibus oscula, quas tu <br>     Hellespontiaca ponis iturus aqua? <br>sic ubi lux acta est et noctis amicior hora <br>     exhibuit pulso sidera clara die, <br>protinus in summa vigilantia lumina turre <br>     ponimus, adsuetae signa notamque viae,<br>tortaque versato ducentes stamina fuso <br>     feminea tardas fallimus arte moras. <br>quid loquar interea tam longo tempore, quaeris:<br>     nil nisi Leandri nomen in ore meo est.<br>‘iamne putas exisse domo mea gaudia, nutrix, <br>     an vigilant omnes, et timet ille suos? <br>iamne suas umeris illum deponere vestes, <br>     pallade iam pingui tinguere membra putas?’ <br>adnuit illa fere; non nostra quod oscula curet, <br>     sed movet obrepens somnus anile caput. <br>postque morae minimum ‘iam certe navigat,’ inquam, <br>     ‘lentaque dimotis bracchia iactat aquis.’ <br>paucaque cum tacta perfeci stamina terra<br>     an medio possis, quaerimus, esse freto.<br>et modo prospicimus, timida modo voce precamur, <br>     ut tibi det faciles utilis aura vias; <br>auribus incertas voces captamus et omnem <br>     adventus strepitum credimus esse tui. <br>sic ubi deceptae pars est mihi maxima noctis <br>     acta, subit furtim lumina fessa sopor. <br>forsitan invitus mecum tamen, improbe, dormis<br>     et, quamquam non vis ipse venire, venis. <br>nam modo te videor prope iam spectare natantem, <br>     bracchia nunc umeris umida ferre meis,<br>nunc dare quae soleo, madidis velamina membris, <br>     pectora nunc nostro iuncta fovere sinu <br>multaque praeterea linguae reticenda modestae<br>     quae fecisse iuvat, facta referre pudet. <br>me miseram! brevis est haec et non vera voluptas; <br>     nam tu cum somno semper abire soles.<br>firmius, o, cupidi tandem coeamus amantes, <br>     nec careant vera gaudia nostra fide.<br>cur ego tot viduas exegi frigida noctes? <br>     cur totiens a me, lente morator, abes?<br>est mare, confiteor, non nunc tractabile nanti; <br>     nocte sed hesterna lenior aura fuit. <br>cur ea praeterita est? cur non ventura timebas? <br>     tam bona cur periit, nec tibi rapta via est? <br>protinus ut similis detur tibi copia cursus, <br>     hoc melior certe, quo prior, illa fuit. <br>at cito mutata est pacati forma profundi. <br>     tempore, cum properas, saepe minore venis. <br>hic, puto, deprensus nil quod querereris haberes<br>     meque tibi amplexo nulla noceret hiems.<br>certe ego tum ventos audirem laeta sonantes<br>     et numquam placidas esse precarer aquas. <br>quid tamen evenit, cur sis metuentior undae <br>     contemptumque prius nunc vereare fretum? <br>nam memini, cum te saevum veniente minaxque <br>     non minus, aut multo non minus, aequor erat; <br>cum tibi clamabam: ‘sic tu temerarius esto, <br>     ne miserae virtus sit tua flenda mihi.’ <br>unde novus timor hic quoque illa audacia fugit? <br>     magnus ubi est spretis ille natator aquis?","st":"19"},{"sp":"N","t":"sis tamen hoc potius, quam quod prius esse solebas, <br>     et facias placidum per mare tutus iter — <br>dummodo sis idem; dum sic, ut scribis, amemur<br>     flammaque non fiat frigidus illa cinis.<br>non ego tam ventos timeo mea vota morantes, <br>     quam similis vento ne tuus erret amor, <br>ne non sim tanti, superentque pericula causam<br>     et videar merces esse labore minor. <br>interdum metuo, patria ne laedar et impar <br>     dicar Abydeno Thressa puella toro.<br>ferre tamen possum patientius omnia, quam si <br>     otia nescio qua paelice captus agis, <br>in tua si veniunt alieni colla lacerti<br>     fitque novus nostri finis amoris amor. <br>a, potius peream, quam crimine vulnerer isto, <br>     fataque sint culpa nostra priora tua! <br>nec quia venturi dederis mihi signa doloris, <br>     haec loquor aut fama sollicitata nova. <br>omnia sed vereor! quis enim securus amavit? <br>     cogit et absentes plura timere locus.<br>felices illas, sua quas praesentia nosse <br>     crimina vera iubet, falsa timere vetat.<br>nos tam vana movet, quam facta iniuria fallit, <br>     incitat et morsus error uterque pares. <br>o utinam venias! aut ut ventusve paterve <br>     causaque sit certe femina nulla morae! <br>quodsi quam sciero, moriar, mihi crede, dolendo; <br>     iamdudum pecca, si mea fata petis.<br>sed neque peccabis, frustraque ego terreor istis, <br>     quoque minus venias, invida pugnat hiems.<br>me miseram! quanto planguntur litora fluctu, <br>     et latet obscura condita nube dies! <br>forsitan ad pontum mater pia venerit Helles<br>     mersaque roratis nata fleatur aquis;<br>an mare ab inviso privignae nomine dictum <br>     vexat in aequoream versa noverca deam? <br>non favet, ut nunc est, teneris locus iste puellis; <br>     hac Helle periit, hac ego laedor aqua. <br>at tibi flammarum memori, Neptune, tuarum <br>     nullus erat ventis impediendus amor:<br>si neque Amymone nec, laudatissima forma, <br>     criminis est Tyro fabula vana tui, <br>lucidaque Alcyone Calyceque Hecataeone nata, <br>     et nondum nexis angue Medusa comis<br>flavaque Laudice caeloque recepta Celaeno<br>     et quarum memini nomina lecta mihi. <br>has certe pluresque canunt, Neptune, poetae <br>     molle latus lateri conposuisse tuo. <br>cur igitur, totiens vires expertus amoris, <br>     adsuetum nobis turbine claudis iter?<br>parce, ferox, latoque mari tua proelia misce;<br>     seducit terras haec brevis unda duas. <br>te decet aut magnas magnum iactare carinas<br>     aut etiam totis classibus esse trucem; <br>turpe deo pelagi iuvenem terrere natantem<br>     gloriaque est stagno quolibet ista minor. <br>nobilis ille quidem est et clarus origine, sed non <br>     a tibi suspecto ducit Ulixe genus. <br>da veniam servaque duos. natat ille; sed isdem <br>     corpus Leandri, spes mea pendet aquis.<br>sternuit etn lumen — posito nam scribimus illo — <br>     sternuit et nobis prospera signa dedit. <br>ecce, merum nutrix faustos instillat in ignes<br>     ‘cras’ que ‘erimus plures’ inquit et ipsa bibit. <br>effice nos plures evicta per aequora lapsus, <br>     o penitus toto corde recepte mihi! <br>in tua castra redi, socii desertor amoris; <br>     ponuntur medio cur mea membra toro? <br>quod timeas, non est! auso Venus ipsa favebit<br>     sternet et aequoreas aequore nata vias.<br>ire libet medias ipsi mihi saepe per undas, <br>     sed solet hoc maribus tutius esse fretum. <br>nam cur hac vectis Phrixo Phrixique sorore <br>     sola dedit vastis femina nomen aquis? <br>forsitan ad reditum metuas ne tempora desint, <br>     aut gemini nequeas ferre laboris onus. <br>at nos diversi medium coeamus in aequor <br>     obviaque in summis oscula demus aquis<br>atque ita quisque suas iterum redeamus ad urbes; <br>     exiguum sed plus quam nihil illud erit.<br>vel pudor hic utinam, qui nos clam cogit amare,<br>     vel timidus famae cedere vellet amor! <br>nunc male res iunctae, calor et reverentia pugnant. <br>     quid sequar, in dubio est; haec decet, ille iuvat. <br>ut semel intravit Colchos Pagasaeus Iason, <br>     impositam celeri Phasida puppe tulit; <br>ut semel Idaeus Lacedaemona venit adulter, <br>     cum praeda rediit protinus ille sua.<br>tu quam saepe petis quod amas, tam saepe relinquis, <br>     et quotiens grave sit puppibus ire, natas.<br>sic tamen, o iuvenis, tumidarum victor aquarum,","st":"19"},{"sp":"N","t":"sic facito spernas, ut vereare, fretum. <br>arte laboratae merguntur ab aequore naves; <br>     tu tua plus remis bracchia posse putas? <br>quod cupis, hoc nautae metuunt, Leandre, natare; <br>     exitus hic fractis puppibus esse solet. <br>me miseram! cupio non persuadere quod hortor<br>     sisque, precor, monitis fortior ipse meis;<br>dummodo pervenias excussaque saepe per undas <br>     inicias umeris bracchia lassa meis.<br>sed mihi, caeruleas quotiens obvertor ad undas, <br>     nescio quid pavidum frigore pectus habet. <br>nec minus hesternae confundor imagine noctis, <br>     quamvis est sacris illa piata meis. <br>namque sub aurora iam dormitante lucerna<br>     somnia quo cerni tempore vera solent, <br>stamina de digitis cecidere sopore remissis<br>     collaque pulvino nostra ferenda dedi. <br>hic ego ventosas nantem delphina per undas <br>     cernere non dubia sum mihi visa fide:<br>quem postquam bibulis illisit fluctus harenis, <br>     unda simul miserum vitaque deseruit. <br>quidquid id est, timeo; nec tu mea somnia ride <br>     nec nisi tranquillo bracchia crede mari.<br>si tibi non parcis, dilectae parce puellae, <br>     quae numquam nisi te sospite sospes ero.<br>spes tamen est fractis vicinae pacis in undis; <br>     tu placidas toto pectore finde vias.<br>interea, quoniam nanti freta pervia non sunt, <br>     leniat invisas littera missa moras.","st":"19"},{"sp":"HDR","t":"XX","st":"20"},{"sp":"N","t":"Accipe, Cydippe, despecti namen Aconti — <br>     illius in pomo qui tibi verba dedit. <br>Pone metum! nihil hic iterum iurabis amanti; <br>     promissam satis est te semel esse mihi. <br>perlege! discedat sic corpore languor ab isto, <br>     quod meus est ulla parte dolere dolor!","st":"20"},{"sp":"N","t":"quid pudor ante subit? nam, sicut in aede Dianae<br>     suspicor ingenuas erubuisse genas. <br>coniugium pactamque fidem, non crimina posco; <br>     debitus ut coniunx, non ut adulter amo. <br>verba licet repetas, quae demptus ab arbore fetus <br>     pertulit ad castas me iaciente manus;<br>invenies illic id te spondere, quod opto <br>     te potius, virgo, quam meminisse deam. <br>nunc quoque idem (timeo), sed idem tamen acrius illud; <br>     adsumpsit vires auctaque flamma mora est, <br>quique fuit numquam parvus, nunc tempore longo <br>     et spe, quam dederas tu mihi, crevit amor.<br>spem mihi tu dederas; meus hic tibi credidit ardor. <br>     non potes hoc factum teste negare dea. <br>adfuit et praesens, ut erat, tua verba notavit <br>     et visa est mota dicta tulisse coma.<br>deceptam dicas nostra te fraude licebit, <br>     dum fraudis nostrae causa feratur amor. <br>fraus mea quid petiit, nisi uti tibi iungerer uni? <br>     id me, quod quereris, conciliare potest. <br>non ego natura nec sum tam callidus usu; <br>     sollertem tu me, crede, puella, facis. <br>te mihi compositis, siquid tamen egimus, a me <br>     adstrinxit verbis ingeniosus Amor. <br>dictatis ab eo feci sponsalia verbis<br>     consultoque fui iuris Amore vafer.<br>sit fraus huic facto nomen, dicarque dolosus, <br>     si tamen est, quod ames, velle tenere dolus. <br>en, iterum scribo mittoque rogantia verba! <br>     altera fraus haec est, quodque queraris habes. <br>si noceo, quod amo, fateor, sine fine nocebo, <br>     teque, peti caveas tu licet, usque petam. <br>per gladios alii placitas rapuere puellas; <br>     scripta mihi caute littera crimen erit? <br>di faciant, possim plures imponere nodos, <br>     ut tua sit nulla libera parte fides.<br>mille doli restant, clivo sudamus in imo; <br>     ardor inexpertum nil sinet esse meus. <br>sit dubium, possisne capi; captabere certe. <br>     exitus in dis est, sed capiere tamen.<br>ut partem effugias, non omnia retia falles, <br>     quae tibi, quam credis, plura tetendit Amor. <br>si non proficient artes, veniemus ad arma, <br>     inque tui cupido rapta ferere sinu. <br>non sum qui soleam Paridis reprehendere factum<br>     nec quemquam, qui vir, posset ut esse, fuit.<br>nos quoque — sed taceo. mors huius poena rapinae <br>     ut sit, erit quam te non habuisse minor. <br>aut esses formosa minus, peterere modeste; <br>     audaces facie cogimur esse tua. <br>tu facis hoc oculique tui, quibus ignea cedunt <br>     sidera, qui flammae causa fuere meae; <br>hoc faciunt flavi crines et eburnea cervix<br>     quaeque, precor, veniant in mea colla manus<br>et decor et vultus sine rusticitate pudentes<br>     et, Thetidis qualis vix rear esse, pedes.<br>cetera si possem laudare, beatior essem, <br>     nec dubito, totum quin sibi par sit opus. <br>hac ego compulsus, non est mirabile, forma,<br>     si pignus volui vocis habere tuae. <br>denique, dum captam tu te cogare fateri, <br>     insidiis esto capta puella meis. <br>invidiam patiar; passo sua praemia dentur. <br>     cur suus a tanto crimine fructus abest? <br>Hesionen Telamon, Briseida cepit Achilles; <br>     utraque victorem nempe secuta virum.<br>quamlibet accuses et sis irata licebit, <br>     irata liceat dum mihi posse frui.<br>idem qui facimus, factam tenuabimus iram, <br>     copia placandi sit modo parva tui. <br>ante tuos liceat flentem consistere vultus <br>     et liceat lacrimis addere verba suis<br>utque solent famuli, cum verbera saeva verentur, <br>     tendere submissas ad tua crura manus! <br>ignoras tua iura; voca! cur arguor absens? <br>     iamdudum dominae more venire iube.<br>ipsa meos scindas licet imperiosa capillos<br>     oraque sint digitis livida nostra tuis. <br>omnia perpetiar; tantum fortasse timebo, <br>     corpore laedatur ne manus ista meo. <br>sed neque conpedibus nec me conpesce catenis;<br>     servabor firmo vinctus amore tui.<br>cum bene se quantumque volet satiaverit ira, <br>     ipsa tibi dices: ‘quam patienter amat!’ <br>ipsa tibi dices, ubi videris omnia ferre: <br>     ‘tam bene qui servit, serviat iste mihi!’<br>nunc reus infelix absens agor, et mea, cum sit <br>     optima, non ullo causa tuente perit. <br>hoc quoque quod tum vis, sit scriptum iniuria nostrum, <br>     quod de me solo nempe queraris, habes. <br>non meruit falli mecum quoque Delia; si non","st":"20"},{"sp":"N","t":"vis mihi promissum reddere, redde deae. <br>adfuit et vidit, cum tu decepta rubebas, <br>     et vocem memori condidit aure tuam. <br>omina re careant! nihil est violentius illa, <br>     cum sua, quod nolim, numina laesa videt.<br>testis erit Calydonis aper sic saevus, ut illo <br>     sit magis in natum saeva reperta parens. <br>testis et Actaeon, quondam fera creditus illis, <br>     ipse dedit leto cum quibus ante feras; <br>quaeque superba parens saxo per corpus oborto <br>     nunc quoque Mygdonia flebilis adstat humo. <br>ei mihi! Cydippe, timeo tibi dicere verum, <br>     ne videar causa falsa monere mea; <br>dicendum tamen est. hoc est, mihi crede, quod aegra <br>     ipso nubendi tempore saepe iaces.<br>consulit ipsa tibi, neu sis periura, laborat, <br>     et salvam salva te cupit esse fide. <br>inde fit, ut, quotiens existere perfida temptas, <br>     peccatum totiens corrigat illa tuum. <br>parce movere feros animosae virginis arcus; <br>     mitis adhuc fieri, si patiare, potest. <br>parce, precor, teneros corrumpere febribus artus; <br>     servetur facies ista fruenda mihi. <br>serventur vultus ad nostra incendia nati, <br>     quique subest niveo lenis in ore rubor.<br>hostibus et siquis, ne fias nostra, repugnat, <br>     sic sit ut invalida te solet esse mihi.<br>torqueor ex aequo vel te nubente vel aegra <br>     dicere nec possum, quid minus ipse velim; <br>maceror interdum, quod sim tibi causa dolendi <br>     teque mea laedi calliditate puto. <br>in caput ut nostrum dominae periuria, quaeso, <br>     eveniant; poena tuta sit illa mea!<br>ne tamen ignorem, quid agas, ad limina crebro <br>     anxius huc illuc dissimulanter eo;<br>subsequor ancillam furtim famulumque requirens,<br>     profuerint somni quid tibi quidve cibi. <br>me miserum, quod non medicorum iussa ministro<br>     effingoque manus insideoque toro! <br>et rursus miserum, quod me procul inde remoto, <br>     quem minime vellem, forsitan alter adest.<br>ille manus istas effingit et adsidet aegrae <br>     invisus superis cum superisque mihi, <br>dumque suo temptat salientem pollice venam, <br>     candida per causam bracchia saepe tenet<br>contrectatque sinus et forsitan oscula iungit;<br>     officio merces plenior ista suo est.<br>quis tibi permisit nostras praecerpere messes? <br>     ad saepem alterius quis tibi fecit iter?<br>iste sinus meus est! mea turpiter oscula sumis! <br>     a mihi promisso corpore tolle manus! <br>improbe, tolle manus! quam tangis, nostra futura est; <br>     postmodo si facies istud, adulter eris. <br>elige de vacuis quam non sibi vindicet alter; <br>     si nescis: dominum res habet ista suum.<br>nec mihi credideris: recitetur formula pacti; <br>     neu falsam dicas esse, fac ipsa legat.<br>alterius thalamo tibi nos, tibi dicimus exi! <br>     quid facis hic? exi! non vacat iste torus.<br>nam quod habes et tu gemini verba altera pacti, <br>     non erit idcirco par tua causa meae. <br>haec mihi se pepigit, pater hanc tibi, primus ab illa; <br>     sed propior certe quam pater ipsa sibi est. <br>promisit pater hanc, haec se iuravit amanti; <br>     ille homines, haec est testificata deam.<br>hic metuit mendax, haec et periura vocari; <br>     an dubitas, hic sit maior an ille metus? <br>denique ut amborum conferre pericula possis, <br>     respice ad eventus: haec cubat, ille valet. <br>nos quoque dissimili certamina mente subimus;<br>     nec spes par nobis nec timor aequus adest. <br>tu petis ex tuto; gravior mihi morte repulsa est, <br>     idque ego iam, quod tu forsan amabis, amo. <br>si tibi iustitiae, si recti cura fuisset, <br>     cedere debueras ignibus ipse meis.<br>nunc, quoniam ferus hic pro causa pugnat iniqua, <br>     ad quid, Cydippe, littera nostra redit. <br>hic facit ut iaceas et sis suspecta Dianae; <br>     hunc tu, si sapias, limen adire vetes. <br>hoc faciente subis tam saeva pericula vitae,<br>     atque utinam pro te, qui movet illa, cadat! <br>quem si reppuleris nec, quem dea damnat, amaris, <br>     tu tunc continuo, certe ego salvus ero. <br>siste metum, virgo! stabili potiere salute, <br>     fac modo polliciti conscia templa colas;<br>non bove mactato caelestia numina gaudent, <br>     sed, quae praestanda est et sine teste, fide.<br>ut valeant aliae, ferrum patiuntur et ignes, <br>     fert aliis tristem sucus amarus opem.","st":"20"},{"sp":"N","t":"nil opus est istis; tantum periuria vita <br>     teque simul serva meque datamque fidem! <br>praeteritae veniam dabit ignorantia culpae:<br>     exciderant animo foedera lecta tuo. <br>admonita es modo voce mea, modo casibus istis, <br>     quos, quotiens temptas fallere, ferre soles.<br>his quoque vitatis in partu nempe rogabis, <br>     ut tibi luciferas adferat illa manus? <br>audiet et repetens quae sunt audita requiret, <br>     iste tibi de quo coniuge partus eat. <br>promittes votum; scit te promittere falso.<br>     iurabis; scit te fallere posse deos.<br>non agitur de me; cura maiore laboro. <br>     anxia sunt causa pectora nostra tua. <br>cur modo te dubiam pavidi flevere parentes, <br>     ignaros culpae quos facis esse tuae?<br>et cur ignorent? matri licet omnia narres. <br>     nil tua, Cydippe, facta ruboris habent. <br>ordine fac referas ut sis mihi cognita primum <br>     sacra pharetratae dum facit ipsa deae; <br>ut te conspecta subito, si forte notasti, <br>     restiterim fixis in tua membra genis; <br>et te dum nimium miror, nota certa furoris, <br>     deciderint umero pallia lapsa meo; <br>postmodo nescio qua venisse volubile malum<br>     verba ferens doctis insidiosa notis;<br>quod quia sit lectum sancta praesente Diana<br>     esse tuam vinctam numine teste fidem.<br>ne tamen ignoret, scripti sententia quae sit, <br>     lecta tibi quondam nunc quoque verba refer. <br>‘nube, precor’ dicet ‘cui te bona numina iungunt; <br>     quem fore iurasti, sit gener ille mihi. <br>quisquis is est, placeat, quoniam placet ante Dianae.’ <br>     talis erit mater, si modo mater erit. <br>sed tamen ut quaerat quis sim qualisque; videto:<br>     inveniet vobis consuluisse deam.<br>insula Coryciis quondam celeberrima nymphis<br>     cingitur Aegaeo, nomine Cea, mari. <br>illa mihi patria est; nec, si generosa probatis <br>     nomina, despectis arguor ortus avis. <br>sunt et opes nobis, sunt et sine crimine mores; <br>     amplius utque nihil, me tibi iungit Amor. <br>appeteres talem vel non iurata maritum; <br>     iuratae vel non talis habendus erat. <br>haec tibi me in somnis iaculatrix scribere Phoebe; <br>     haec tibi me vigilem scribere iussit Amor;<br>e quibus alterius mihi iam nocuere sagittae, <br>     alterius noceant ne tibi tela, cave! <br>iuncta salus nostra est — miserere meique tuique:<br>     quid dubitas unam ferre duobus opem? <br>quod si contigerit, cum iam data signa sonabunt, <br>     tinctaque votivo sanguine Delos erit,<br>aurea ponetur mali felicis imago, <br>     causaque versiculis scripta duobus erit: <br>“effigie pomi testatur acontius huius <br>     quae fuerint in eo scripta fuisse rata.”<br>longior infirmum ne lasset epistula corpus <br>     clausaque consueto sit sibi fine: vale!","st":"20"},{"sp":"HDR","t":"XXI","st":"21"},{"sp":"N","t":"Littera pervenit tua quo consuevit, Aconti<br>     et paene est oculis insidiata meis. <br>Pertimui scriptumque tuum sine murmure legi, <br>     iuraret ne quos inscia lingua deos. <br>et, puto, captasses iterum, nisi ut ipse fateris, <br>     promissam scires me satis esse semel. <br>nec lectura fui, sed si tibi dura fuissem, <br>     aucta foret saevae forsitan ira deae. <br>omnia cum faciam, cum dem pia tura Dianae, <br>     illa tamen iusta plus tibi parte favet<br>utque cupis credi, memori te vindicat ira:<br>     talis in Hippolyto vix fuit illa suo.<br>at melius virgo favisset virginis annis, <br>     quos vereor paucos ne velit esse mihi. <br>languor enim causis non apparentibus haeret,<br>     adiuvor et nulla fessa medentis ope. <br>quam tibi nunc gracilem vix haec rescribere quamque <br>     pallida vix cubito membra levare putas? <br>nunc timor accedit, ne quis nisi conscia nutrix <br>     colloquii nobis sentiat esse vices. <br>ante fores sedet haec quid agamque rogantibus intus, <br>     ut possim tuto scribere, ‘dormit’ ait.<br>mox, ubi, secreti longi causa optima, somnus <br>     credibilis tarda desinit esse mora, <br>iamque venire videt quos non admittere durum est, <br>     excreat et dicta dat mihi signa nota. <br>sicut erant, properans verba inperfecta relinquo, <br>     et tegitur trepido littera coepta sinu. <br>inde meos digitos iterum repetita fatigat; <br>     quantus sit nobis adspicis ipse labor. <br>quo peream si dignus eras, ut vera loquamur; <br>     sed melior iusto quamque mereris ego.","st":"21"},{"sp":"N","t":"ergo te propter totiens incerta salutis <br>     commentis poenas doque dedique tuis? <br>haec nobis formae te laudatore superbae <br>     contingit merces et placuisse nocet? <br>si tibi deformis, quod mallem, visa fuissem, <br>     culpatum nulla corpus egeret ope; <br>nunc laudata gemo, nunc me certamine vestro <br>     perditis et proprio vulneror ipsa bono. <br>dum neque tu cedis, nec se putat ille secundum, <br>     tu votis obstas illius, ille tuis,<br>ipsa velut navis iactor, quam certus in altum <br>     propellit Boreas, aestus et unda refert.<br>cumque dies caris optata parentibus instat, <br>     immodicus pariter corporis ardor inest.<br>nunc mihi coniugii tempus crudelis ad ipsum <br>     Persephone nostras pulsat acerba fores.<br>iam pudet et timeo, quamvis mihi conscia non sim, <br>     offensos videar ne meruisse deos. <br>accidere haec aliquis casu contendit, et alter <br>     acceptum superis hunc negat esse virum;<br>neve nihil credas in te quoque dicere famam, <br>     facta veneficiis pars putat ista tuis. <br>causa latet, mala nostra patent; vos pace movetis <br>     aspera submota proelia, plector ego.<br>dic mihi nunc, solitoque tibi ne decipe more;<br>     quid facies odio, sic ubi amore noces? <br>si laedis quod amas, hostem sapienter amabis;<br>     me, precor, ut serves, perdere velle velis! <br>aut tibi iam nulla est speratae cura puellae, <br>     quam ferus indigna tabe perire sinis,<br>aut dea si frustra pro me tibi saeva rogatur, <br>     quid mihi te iactas? gratia nulla tua est. <br>elige, quid fingas: non vis placare Dianam.<br>     immemor es nostri; non potes — illa tui est.<br>vel numquam mallem vel non mihi tempore in illo <br>     esset in Aegaeis cognita Delos aquis.<br>tunc mea difficili deducta est aequore navis<br>     et fuit ad coeptas hora sinistra vias. <br>quo pede processi? quo me pede limine movi?<br>     picta citae tetigi quo pede texta ratis?<br>bis tamen adverso redierunt carbasa vento:<br>     mentior, a demens! ille secundus erat.<br>ille secundus erat qui me referebat euntem<br>     quique parum felix impediebat iter. <br>atque utinam constans contra mea vela fuisset!<br>     sed stultum est venti de levitate queri. <br>mota loci fama properabam visere Delon <br>     et facere ignava puppe videbar iter. <br>quam saepe ut tardis feci convicia remis<br>     questaque sum vento lintea parca dari.<br>et iam transieram Myconon, iam Tenon et Andron, <br>     inque meis oculis candida Delos erat; <br>quam procul ut vidi, ‘quid me fugis, insula’ dixi<br>     ‘laberis in magno numquid ut ante mari?’ <br>institeram terrae, cum iam prope luce peracta <br>     demere purpureis sol iuga vellet equis. <br>quos idem solitos postquam revocavit ad ortus, <br>     comuntur nostrae matre iubente comae. <br>ipsa dedit gemmas digitis et crinibus aurum<br>     et vestes umeris induit ipsa meis.<br>protinus egressae superis, quibus insula sacra est, <br>     flava salutatis tura merumque damus; <br>dumque parens aras votivo sanguine tingit<br>     sectaque fumosis ingerit exta focis, <br>sedula me nutrix altas quoque ducit in aedes<br>     erramusque vago per loca sacra pede;<br>et modo porticibus spatior modo munera regum <br>     miror et in cunctis stantia signa locis.<br>miror et innumeris structam de cornibus aram<br>     et de qua pariens arbore nixa dea est<br>et quae praeterea — neque enim meminive libetve <br>     quidquid ibi vidi dicere — Delos habet. <br>forsitan haec spectans a te spectabar, Aconti, <br>     visaque simplicitas est mea posse capi. <br>in templum redeo gradibus sublime Dianae — <br>     tutior hoc ecquis debuit esse locus? <br>mittitur ante pedes malum cum carmine tali — <br>     ei mihi! iuravi nunc quoque paene tibi! <br>sustulit hoc nutrix mirataque ‘perlege’ dixit. <br>     insidias legi, magne poeta, tuas.<br>nomine coniugii dicto confusa pudore, <br>     sensi me totis erubuisse genis, <br>luminaque in gremio veluti defixa tenebam,<br>     lumina propositi facta ministra tui. <br>improbe, quid gaudes aut quae tibi gloria parta est? <br>     quidve vir elusa virgine laudis habes? <br>non ego constiteram sumpta peltata securi, <br>     qualis in Iliaco Penthesilea solo; <br>nullus Amazonio caelatus balteus auro, <br>     sicut ab Hippolyta, praeda relata tibi est.<br>verba quid exultas tua si mihi verba dederunt","st":"21"},{"sp":"N","t":"sumque parum prudens capta puella dolis? <br>Cydippen pomum, pomum Schoeneida cepit; <br>     tu nunc Hippomenes scilicet alter eris?<br>at fuerat melius, si te puer iste tenebat, <br>     quem tu nescio quas dicis habere faces, <br>more bonis solito spem non corrumpere fraude; <br>     exoranda tibi, non capienda fui.<br>cur, me cum peteres, ea non profitenda putabas, <br>     propter quae nobis ipse petendus eras?<br>cogere cur potius quam persuadere volebas, <br>     si poteram audita condicione capi? <br>quid tibi nunc prodest iurandi formula iuris <br>     linguaque praesentem testificata deam? <br>quae iurat mens est. nil coniuravimus illa; <br>     illa fidem dictis addere sola potest. <br>consilium prudensque animi sententia iurat<br>     et nisi iudicii vincula nulla valent. <br>si tibi coniugium volui promittere nostrum, <br>     exige polliciti debita iura tori.<br>sed si nil dedimus praeter sine pectore vocem, <br>     verba suis frustra viribus orba tenes. <br>non ego iuravi, legi iurantia verba; <br>     vir mihi non isto more legendus eras. <br>decipe sic alias, succedat epistula pomo;<br>     si valet hoc magnas ditibus aufer opes; <br>fac iurent reges sua se tibi regna daturos<br>     sitque tuum toto quidquid in orbe placet! <br>maior es hoc ipsa multo, mihi crede, Diana, <br>     si tua tam praesens littera numen habet.<br>cum tamen haec dixi, cum me tibi firma negavi, <br>     cum bene promissi causa peracta mei est, <br>confiteor, timeo saevae Latoidos iram <br>     et corpus laedi suspicor inde meum.<br>nam quare, quotiens socialia sacra parantur, <br>     nupturae totiens languida membra cadunt? <br>ter mihi iam veniens positas Hymenaeus ad aras <br>     fugit, et a thalami limine terga dedit<br>vixque manu pigra totiens infusa resurgunt <br>     lumina, vix moto corripit igne faces.<br>saepe coronatis stillant unguenta capillis <br>     et trahitur multo splendida palla croco. <br>cum tetigit limen, lacrimas mortisque timorem <br>     cernit et a cultu multa remota suo, <br>proicit ipse sua deductas fronte coronas<br>     spissaque de nitidis tergit amoma comis; <br>et pudet in tristi laetum consurgere turba, <br>     quique erat in palla, transit in ora rubor. <br>at mihi, vae miserae! torrentur febribus artus <br>     et gravius iusto pallia pondus habent.<br>nostraque plorantes video super ora parentes<br>     et face pro thalami fax mihi mortis adest. <br>parce laboranti, picta dea laeta pharetra, <br>     daque salutiferam iam mihi fratris opem. <br>turpe tibi est, illum causas depellere leti, <br>     te contra titulum mortis habere meae. <br>numquid, in umbroso cum velles fonte lavari, <br>     imprudens vultus ad tua labra tuli?<br>praeteriive tuas de tot caelestibus aras, <br>     ave mea spreta est vestra parente parens?<br>nil ego peccavi, nisi quod periuria legi <br>     inque parum fausto carmine docta fui. <br>tu quoque pro nobis, si non mentiris amorem, <br>     tura feras; prosint quae nocuere manus! <br>cur, qui succenses quod adhuc tibi pacta puella <br>     non tua sit, fieri ne tua possit, agis? <br>omnia de viva tibi sunt speranda; quid aufert <br>     saeva mihi vitam, spem tibi diva mei? <br>nec tu credideris illum, cui destinor uxor, <br>     aegra superposita membra fovere manu.<br>adsidet ille quidem, quantum permittitur ipsi;<br>     sed meminit nostrum virginis esse torum. <br>iam quoque nescio quid de se sensisse videtur; <br>     nam lacrimae causa saepe latente cadunt, <br>et minus audacter blanditur et oscula rara <br>     applicat et timido me vocat ore suam. <br>nec miror sensisse, notis cum prodar apertis; <br>     in dextrum vertor, cum venit ille, latus<br>nec loquor, et tecto simulatur lumine somnus<br>     captantem tactus reicioque manum.<br>ingemit et tacito suspirat pectore, me quod<br>     offensam, quamvis non mereatur, habet. <br>ei mihi, quod gaudes et te iuvat ista voluntas! <br>     ei mihi, quod sensus sum tibi fassa meos! <br>tu mihi siqua foret, tu nostra iustius ira, <br>     qui mihi tendebas retia, dignus eras. <br>scribis, ut invalidum liceat tibi visere corpus:<br>     es procul a nobis, et tamen inde noces. <br>mirabar quare tibi nomen Acontius esset; <br>     quod faciat longe vulnus, acumen habes.<br>certe ego convalui nondum de vulnere tali, <br>     ut iaculo scriptis eminus icta tuis. <br>quid tamen huc venias? sane miserabile corpus,","st":"21"},{"sp":"N","t":"ingenii videas magna tropaea tui! <br>concidimus macie; color est sine sanguine, qualem <br>     in pomo refero mente fuisse tuo.<br>candida nec mixto sublucent ora rubore. <br>     forma novi talis marmoris esse solet; <br>argenti color est inter convivia talis, <br>     quod tactum gelidae frigore pallet aquae.<br>si me nunc videas, visam prius esse negabis;<br>     ‘arte nec est’ dices ‘ista petita mea.’ <br>promissique fidem, ne sim tibi iuncta, remittes<br>     et cupies illud non meminisse deam. <br>forsitan et facies iurem ut contraria rursus, <br>     quaeque legam mittes altera verba mihi. <br>sed tamen adspiceres vellem prout ipse rogabas, <br>     et discas sponsae languida membra tuae! <br>durius ut ferro iam sit tibi pectus, Aconti, <br>     tu veniam nostris vocibus ipse petas.<br>ne tamen ignores: ope qua revalescere possim, <br>     quaeritur a Delphis fata canente deo. <br>is quoque nescio quam, nunc ut vaga fama susurrat, <br>     neglectam queritur testis habere fidem. <br>hoc deus, hoc vates, hoc edita carmina dicunt:<br>     a, desunt voto numina nulla tuo! <br>unde tibi favor hic? nisi si nova forte reperta est,<br>     quae capiat magnos littera lecta deos.<br>teque tenente deos numen sequor ipsa deorum<br>     doque libens victas in tua vota manus;<br>fassaque sum matri deceptae foedera linguae <br>     lumina fixa tenens plena pudoris humo. <br>cetera cura tua est plus hoc quoque virgine factum;<br>     non timuit tecum quod mea charta loqui. <br>iam satis invalidos calamo lassavimus artus;<br>     et manus officium longius aegra negat. <br>quid nisi, si cupio mihi iam contingere tecum, <br>     restat, ut adscribat littera nostra “Vale!”","st":"21"}]);})();
